window.IDIOMS = [
  {"name": "如火燎原", "cid": 469044, "pid": 25112289, "num": 1, "meaning": "燎：烧；原：原野。如火在原野燃烧。比喻声势很大，难于阻抑。", "source": "《尚书·盘庚上》", "example": "到期不能“剿灭”，反而～，他们有些做封疆大吏的，轻则降级、削职，重则下狱、砍头。（姚雪垠《李自成》第二卷第三十六章）", "story": "周武王伐纣时，商朝百姓早就痛恨纣王的暴政。周军一到，商军纷纷倒戈投降。古人形容这种形势，说百姓盼望周军，就像'火之燎于原'一样势不可挡。后来便用'如火燎原'形容事物迅速发展、不可阻挡。"},
  {"name": "休戚相关", "cid": 469044, "pid": 25112290, "num": 2, "meaning": "彼此欢乐忧愁、幸福祸患，互相关联。语本《国语．周语下》。后用「休戚相关」形容彼此间的关系密切，利害一致。_x000D_\n△「休戚与共」", "source": "《国语．周语下》", "example": "我们两家休戚相关，荣辱与共，难分彼此。", "story": "《国语．周语下》曾提到一段故事：孙周是晋襄公的曾孙，因为受到在位的晋厉公排挤，而避难到周王室，担任单襄公的家臣。他当时虽然年纪轻，但却为人忠厚，做事合于义理，即使远走他乡，对于晋国的一切仍然非常关心。听到晋国有不好的消息，总是跟著感到悲伤；而听到晋国有可喜的事情，心情也会跟著感到高兴。单襄公看得出来孙周是个才德兼备的青年，前途光明无限，因此在病重的时候，叮咛儿子单顷公说：「要好好善待晋国的公子，因为他虽然身处异乡，但却非常关心晋国的一切，不忘其本，自觉与晋国的荣辱安危互相关联。现在的晋厉公是个昏君，将来孙周一定会回国去接任国君，继承王位，所以你一定要好好对待他。」后来，晋国发生叛乱，厉公被杀，孙周果然被迎回晋国，即位为晋悼公。后来「休戚相关」这句成语，当就从这里的原文「为晋休戚，不背本也」演变而出，形容彼此间的关系密切，利害一致。"},
  {"name": "众志成城", "cid": 469044, "pid": 25112291, "num": 3, "meaning": "众人同心，力量坚固如城。比喻团结一致，同心协力。语本《国语．周语下》。\n△「众口铄金」", "source": "《国语．周语下》", "example": "军民团结，众志成城，是国家安全的最佳保障。", "story": "「众志成城」原作「众心成城」。据《国语．周语下》载，春秋末年，周景王打算要铸造一口极大的钟。单穆公和乐师州鸠知道了这件事，便劝阻景王打消铸钟的念头。他们认为：那么大的钟虽然少见，但是声音不一定和谐好听，若因此劳民伤财，造成人民的痛苦，更是没有必要。然而景王没有采纳他们的意见，仍然执意铸钟。隔年，大钟铸成了，平日惯于献媚的乐工们，纷纷向景王赞美大钟的声音非常和谐、好听。景王十分高兴，就找来当初反对铸钟的乐师州鸠，对他夸耀说：「看吧，钟声果然很好听，你的顾虑是多余的。」州鸠对于景王的无知和自夸十分不以为然，就回答说：「大王铸造大钟，如果人民都十分赞成，那才叫和谐。如今劳民伤财，人民都对大王十分怨恨，这种情形怎么能叫做和谐呢？而且人民所赞同的，很少有不成功的；人民所厌恶的，很少有不失败的。这就是俗话所说：『众心成城，众口铄金』的道理啊！」但是景王不接纳州鸠的劝谏，反而怒斥他已经老了，懂个什么？隔年，周景王驾崩，之后再也没有人说大钟的声音好听。后来「众志成城」这句成语就从这里演变而出，用来比喻团结一致，同心协力。出现「众志成城」的书证如五代十国后蜀．何光远《鉴诫录．卷七．陪臣谏》：「四海归仁，众志成城，天下治理。」"},
  {"name": "大义灭亲", "cid": 469044, "pid": 25112292, "num": 4, "meaning": "指为了维护公理正义，不徇私情，灭了犯罪的亲人，或让他们接受法律制裁。语出《左传．隐公四年》", "source": "《左传．隐公四年》", "example": "历史上那些能大义灭亲的人物，都是令人敬佩的。", "story": "据《左传．隐公四年》载，州吁是春秋时代卫国庄公与宠妾所生的儿子，庄公非常宠爱他，大夫石碏（ㄑㄩㄝˋ）曾经劝谏庄公不要把州吁给宠坏了，但是庄公不听，州吁也因此养成好战骄奢的个性。庄公死后，桓公继位，州吁密谋杀害桓公而自立为国君，引起人民不满而导致国内不安。州吁的亲信石厚就去问他的父亲石碏，要怎么做才能安定民心、巩固王位。石碏曾经是卫桓公的重臣，很受到人民的尊敬，当石厚来请教的时候，他说：「只有觐见周天子才能安定君位。」石厚又问：「如何才能觐见天子呢？」石碏说：「陈桓公正受到周天子的宠信，而现在陈国和卫国的关系非常和睦，因此如果去拜访陈国的国君，请他向周天子请示，必定可以得见。」于是石厚就跟随著州吁到陈国。这时石碏暗中派人告诉陈桓公：「卫国领土狭小，而我已经年老了，不能有所作为。州吁和石厚就是杀了我国国君的人，请你们趁这个机会处置他们。」陈国人就把他们抓起来，请卫国人亲自来处置二人。卫国派右宰丑在濮县把州吁杀了。至于石厚，大家认为因为是石碏的儿子，应该从宽处理，杀了首恶州吁就够了，但是石碏不认同这样的看法。他认为州吁做的许多坏事，石厚也都有参与筹划，不能不严惩，所以就派他的家臣獳（ㄋㄡˋ）羊肩到陈国杀死了石厚。石碏这种为了国家大义，而牺牲父子私情的做法，深受后人所敬佩和赞扬。后来原文中的「大义灭亲」演变为成语，就用来比喻为了维护公理正义，不徇私情，灭了犯罪的亲人，或让他们接受法律制裁。"},
  {"name": "如火如荼", "cid": 469044, "pid": 25112293, "num": 5, "meaning": "荼，茅草开的白花。「如火如荼」指像火那样红、像荼那样白。比喻军容壮盛浩大。语本《国语．吴语》。后用「如火如荼」形容事物的兴盛或气氛的热烈。", "source": "《国语．吴语》", "example": "国际棒球赛正在台北市如火如荼地进行著。", "story": "据《国语．吴语》载，春秋时，吴王夫差打败了越国，之后，又出兵北征，想压制国力最强的晋国，以成为霸主。越王句践便趁机带兵攻击吴国，以报亡国之恨。吴王听到这个消息，赶快召集大臣商量对策。王孙雒认为应该尽快争取到霸主地位再回国，以鼓舞民心。吴王同意王孙雒的看法。当晚，军士都先吃饱，马匹也喂足粮草。到了半夜，士兵们穿好盔甲，拿起武器，勒住马舌，也不点灯，只用煮饭剩余的灶火照明。然后就摆开阵势，以一百人为一行，形成百行共约一万人的方阵。共有左军、中军、右军三个方阵，合计约三万人的阵势。中军的士兵一律穿白衣、白盔甲，拿白旗，使用白羽毛装饰的箭，远远望去好像一片白色的花；左军的士兵则一律穿红衣、红盔甲，拿红旗，使用红羽毛装饰的箭，远远望去好像一团火球；右军的士兵则一律穿黑衣、黑盔甲，拿黑旗，使用黑色羽毛装饰的箭，远远望去一片乌黑。天刚亮，吴国军队已近晋营，吴王亲自擂起战鼓，三军也跟著呐喊，声音响彻天地。晋国国君见到这样盛大的军容，吓得赶紧派人议和，尊吴王为霸主，这件事才告结束。后来「如火如荼」这个成语，就从原文中用来形容军容的「望之如荼」、「望之如火」演变而出，用来比喻军容壮盛浩大，也用来形容事物的兴盛或气氛的热烈。"},
  {"name": "一鼓作气", "cid": 469044, "pid": 25112294, "num": 6, "meaning": "古代作战时，第一通鼓最能激起战士们的勇气。语出《左传．庄公十年》。后用「一鼓作气」比喻做事时要趁著初起时的勇气去做才容易成功。", "source": "《左传．庄公十年》", "example": "他拿起笔，一鼓作气连写了三幅字。", "story": "据《左传．庄公十年》载，春秋时，齐国的军队违背了盟约，出兵攻打鲁国。鲁庄公和曹刿（ㄍㄨㄟˋ）共乘一辆兵车，与齐国的军队交战于长勺。鲁庄公将击鼓准备进击，曹刿阻止说：「不可以。」等到齐军敲过了三通鼓后，曹刿才说：「可以击鼓进攻了！」鲁军战鼓一响，激起了士兵们高昂的士气，大家勇往直前，锐不可当，结果齐军大败，狼狈而逃。这时鲁庄公想乘胜追击，却又被曹刿阻止说：「还不可以！」接著就下车仔细观察地面上齐军兵车留下的轨迹，又登上车前的横木，瞭望齐军退走的情形，然后说：「现在可以追击了！」于是鲁军乘胜前进，追赶落败的齐军，把齐军赶出了鲁国，获得最后的胜利。鲁庄公就询问曹刿这么做的原因何在？曹刿说：「打仗是凭著一股勇气，第一通鼓响时，士兵的勇气最旺盛，第二通鼓响，士气就会稍微衰退，等到第三通鼓响，应战的勇气就已经消失殆尽了！这次和齐军作战，他们击了第三通鼓，我们才击第一通鼓，正是敌人的勇气大减，而我们士气最旺盛的时候，所以我们才能打败敌人。然而像齐国这样的大国，用兵是很难猜测的，我担心他们会有埋伏，所以下车查看，看到他们的车迹混乱，旗帜也散乱地倒下时，可以断定他们是真的被打败了，才敢放心地乘胜追击。」后来原文中的「一鼓作气」，就被用来比喻做事时要趁著初起时的勇气去做，勇往直前，才能一举成事。"},
  {"name": "暗箭伤人", "cid": 469044, "pid": 25112295, "num": 7, "meaning": "在隐蔽处放箭伤害他人。＃语本宋．刘炎《迩言》卷六。后用「暗箭伤人」比喻暗中用阴险的手段伤害人。_x000D_\n△「含沙射影」。", "source": "＃宋．刘炎《迩言》卷六*1*", "example": "他向来行事光明正大，从不暗箭伤人。", "story": "「暗箭伤人」原作「暗箭中人」。刘炎是南宋时的理学家之一，当时理学以朱熹和陆九渊为首，门户分立，相互争论。刘炎却能摒除门户之见，撷取各家之长，不流于意气口舌之争。他著有《迩言》一书，取《诗经．小雅．小旻》诗句「维迩言是听，唯迩言是争」之意，以浅近的言语，来阐述理学精微的道理。在这段文字中，刘炎详细说明了君子和小人的不同。他认为小人经常在背后发表中伤他人的言论，就像暗中放冷箭来伤害人一样，这两种行为都可以造成他人痛彻心扉的可怕伤害。而君子的为人光明磊落，认为与其用阴险的手段得胜，宁可用光明正大的手段来一较高下，即使失败了也没有怨言。后来「暗箭伤人」这句成语就从这里演变而出，用来比喻暗中用阴险的手段中伤他人。"},
  {"name": "唇亡齿寒", "cid": 469044, "pid": 25112296, "num": 8, "meaning": "没有了嘴唇，牙齿就会感到寒冷。比喻关系密切，利害相关。◎语出《左传．僖公五年》。\n△「唇齿相依」、「辅车相依」", "source": "《左传．僖公五年》\n《左传．哀公八年》", "example": "依战略形势来看，这两国有唇亡齿寒的利害关系。", "story": "据《左传．僖公五年》载：春秋时代，晋国与虞、虢两个小国相邻，晋国一直想并吞这两个小国。晋献公计划先攻打虢国，于是派人送良马和玉璧给虞国，希望能够借道攻打虢国。虞国受到诱惑，答应了晋国，晋国因此很快地攻下虢国的一个都城。过了三年，晋国又再度要求虞国借道以便攻打虢国，虞国大夫宫之奇极力劝谏虞公不要答应，他说：「虢国是虞国的屏障，两国互为表里，如果虢国灭亡了，虞国必然也会跟著灭亡。我们不能开启晋国侵略野心，更不能轻忽的引进外国的军队。一次已经太过分了，怎么可以再有第二次呢？谚语所说『颊骨和牙床互相依存，就像是没有了嘴唇，牙齿就会寒冷』的道理，指的就是虞国和虢国的情况。」但是虞公不听从规劝，认为晋国不会伤害同宗的虞国，因此答应了晋国的要求。果然晋国灭了虢国之后，就在回程中也把虞国给灭了。典源又见《左传．哀公八年》。内容则是表述鲁哀公八年时，吴国要攻打鲁国，公山不狃对吴王说：「鲁国虽然没有靠山，可是一旦有事情发生，诸侯都会来救援。晋国与齐国、楚国一起辅助鲁国，你要面对的是四个敌国。鲁国就像是齐国、晋国的嘴唇，君王应该明白唇亡齿寒的道理，他们怎么会不救鲁国呢？」后来「唇亡齿寒」就用来比喻关系密切，利害相关。"},
  {"name": "秦晋之好", "cid": 469044, "pid": 25112297, "num": 9, "meaning": "春秋时，秦晋两国不止一代互相婚嫁。泛指两家联姻。", "source": "元・乔梦符《两世姻缘》：“末将不才，便求小娘子以成秦晋之好，亦不玷辱了他，他如何便不相容。”", "example": "主公仰慕将军，欲求令爱为儿妇，永结～。（明・罗贯中《三国演义》第十六回）", "story": "春秋时期，秦国和晋国是相邻的两个大国。为了彼此和睦，两国经常互相通婚：晋献公把女儿嫁给秦穆公，秦穆公也娶了晋国公主。这种政治联姻世代不断，后来人们就把两家结成婚姻称作'秦晋之好'。"},
  {"name": "外强中干", "cid": 469044, "pid": 25112298, "num": 10, "meaning": "「外强中干」之「强」，典源作「彊」。「彊」同「强」。形容马的外表看似强壮，内在却气力衰竭。语出《左传．僖公十五年》。后用「外强中干」泛喻各种事物外表看似充实强盛，实则空虚衰弱。\n△「色厉内荏」", "source": "《左传．僖公十五年》", "example": "你别以为他壮得像头牛，其实外强中干，常常生病。", "story": "春秋时代，秦晋两国交战，晋惠公亲自领兵上阵。出发前，却选了四匹郑国进献的小马驾车，朝中大臣庆郑便劝他说：「古来遇到像战争这样的大事，一定用本国出产的马匹驾车，因为牠们和人生在同一片水土上，而知道当地人的心意，所以愿意接受他们的调教，且熟悉他们驾驭的方法，随便你怎样导引牠，都没有不如人意的。如今驾著外国的产物从事战争，等牠们一害怕起来，就会与人意相违。狂乱而烦躁，于是血液加速周身运行，使血管膨胀而青筋暴露。虽然从外表看起来非常强壮，内在却已气力衰竭。这时叫牠前进后退牠们都不肯，叫牠周折旋转牠们也不能。那时君一定会后悔的。」惠公不听，驾著小马，与秦军战于韩原，车马竟陷在泥泞里动弹不得，被秦人俘虏。《左传》「外彊中干」一语，本形容马受惊后生理与心理的变化，后来以「强」代「彊」，借以比喻各种事物看似充实强盛，实则空虚衰弱。"},
  {"name": "言归于好", "cid": 469044, "pid": 25112299, "num": 11, "meaning": "言：虚词；归于：回到；好：和好。指彼此重新和好。", "source": "先秦・左丘明《左传・僖公九年》：“凡我同盟之人，既盟之后，言归于好。”", "example": "郭沫若《再谈郁达夫》：“我们几位老朋友，尽管闹翻过一次，结果还是～了。”", "story": "春秋时，齐国召集各路诸侯会盟。在结盟的誓词中约定：凡是今天结盟的国家，从今以后都要摒弃前嫌，'言归于好'，永远和睦相处。意思就是把话说清楚，重新做回好朋友。后来这四个字就成了'重归于好'的意思。"},
  {"name": "宋襄之仁", "cid": 469044, "pid": 25112300, "num": 12, "meaning": "指不顾实际、迁腐虚伪的'仁义'，比喻对敌人讲仁慈反而害了自己。", "source": "《左传·僖公二十二年》", "example": "对坏人不能讲宋襄之仁，否则会吃亏。", "story": "春秋时宋国与楚国交战。楚军正在渡河，大臣劝宋襄公趁机率兵进攻，他却说要讲仁义，等楚军列好阵才开战。结果宋军大败，宋襄公也受了伤。后人讥笑这种不分场合的'仁义'，称为'宋襄之仁'，比喻假仁慈、太迂腐。"},
  {"name": "行将就木", "cid": 469044, "pid": 25112301, "num": 13, "meaning": "将要进棺材。指年纪已大，寿命将尽。语本《左传．僖公二十三年》。", "source": "《左传．僖公二十三年》", "example": "对方已是一个行将就木的人，你就饶了他吧！", "story": "晋公子重耳，是晋献公的次子，因为献公晚年十分宠爱骊姬，想要改立骊姬的儿子为太子，结果太子申生被迫自杀，重耳在狐偃、赵衰等臣子的掩护下逃亡国外十九年，先后到过狄、卫、齐、曹、宋、郑、楚、秦诸国。他在狄国住了十二年，并且娶季隗为妻，生下伯鯈（ㄔㄡˊ）、叔刘。后来决定离开狄国前往齐国时，他要季隗等他二十五年，如果没有回来就改嫁。季隗则表明说她已经二十五岁，再过二十五年就是快要进棺材的老太婆了，坚持要等他。后来重耳借助秦穆公的力量回到晋国，即位成为晋文公，并依言将季隗接回国。后来「行将就木」这个成语就从这里演变而出，用来指年纪已大，寿命将尽。"},
  {"name": "退避三舍", "cid": 469044, "pid": 25112302, "num": 14, "meaning": "舍，古人以三十里为一舍。「退避三舍」指作战时，将部队往后撤退九十里。◎语本《左传．僖公二十三年》。后用「退避三舍」比喻主动退让，不与人相争。", "source": "《左传．僖公二十三年》_x000D_\n《左传．僖公二十八年》", "example": "惹他做啥？先退避三舍吧！", "story": "据《左传．僖公二十三年》载，春秋时，晋献公宠爱骊姬，骊姬为了让亲生儿子奚齐当上太子，设计害死了原来的太子申生，接著又怂恿晋献公派兵捉拿另外二个儿子重耳、夷吾，两人于是先后逃奔出国。后来晋献公过世，奚齐也被臣下所杀，这时逃亡国外的夷吾则回国继位为国君，即晋惠公。晋惠公害怕重耳会回国谋夺君位，于是派人暗杀重耳。此时重耳则是在国外继续著流亡的日子，其间经过许多国家，但大部分国家的君王对他都不怎么礼遇。最后到了楚国，楚成王以酒宴盛情款待，并且问说：「将来你如果回到晋国当上国君，将要如何报答我呢？」重耳说：「奴仆和玉帛，楚国本来就有；珍禽异兽的羽毛皮革，则是楚国的特产。这些东西您多得是，我实在是不知该怎么回报您！」楚成王说：「虽然如此，还是说说可以报答我的方式吧！」重耳于是回答说：「假使托您的福，让我得以回到晋国，万一将来晋、楚之间发生战争，双方军队相遇于中原，那我一定会要我的军队向后撤退九十里，来报答您的恩惠。如果这样还不能得到您的谅解，楚军仍然继续进攻，那我也只好拿起弓箭，和您相对抗了。」后来从言里的原文「辟君三舍」演变出「退避三舍」这句成语，用来比喻主动退让，不与人相争。"},
  {"name": "有恃无恐", "cid": 469044, "pid": 25112303, "num": 15, "meaning": "形容有依靠而无所顾忌。语本《左传．僖公二十六年》。", "source": "《左传．僖公二十六年》", "example": "他有恃无恐地说：「有办法你去告我呀！」", "story": "《左传》记载了鲁僖公二十六年夏天，齐孝公亲自率兵攻打鲁国北部边境。鲁僖公得到消息后，立刻指派展喜带著酒食、财物前去慰劳齐国军队。才见面，齐孝公就问：「你们鲁国人害怕吗？」展喜回答：「小人会害怕，君子则不会。」齐侯说：「你们国家府库空虚，野地里连青草也看不到，凭什么不害怕？」展喜解释说：「依仗先王之命。昔日我先祖周公和齐国先祖姜太公辅佐成王时，曾立下『世世子孙，无相害也。』的盟誓，并且保存在盟府里。齐桓公在世时也尽力在协调解决诸侯间的问题，遵守盟约精神。您即位时，诸侯们都相信您也会遵守先王的盟约，由于我们相信您会信守互助不相攻的盟约，所以一点也不害怕。」齐孝公听了以后便撤兵回国。后来「有恃无恐」这句成语就从这里演变而出，用来形容有依靠而无所顾忌。"},
  {"name": "厉兵秣马", "cid": 469044, "pid": 25255086, "num": 16, "meaning": "磨利兵器，喂饱马匹。指完成作战准备。语出《左传．僖公三十三年》。后亦用「厉兵秣马」比喻完成事前准备工作。\n△「严阵以待」", "source": "《左传．僖公三十三年》", "example": "我军厉兵秣马，已完成备战工作。", "story": "厉兵，磨利兵器。秣马，喂马。「厉兵秣马」指完成作战的准备。《左传》记载：鲁僖公三十二年，驻防郑国都的秦将杞子，派人报告秦王他们已掌管郑国都的北门，是攻打郑国的好机会。三十三年春天，秦王决定派兵攻打郑国。郑国商人弦高在前往周都城经商途中遇到秦军，知道秦军意图后，他一方面用四张兽皮和十二头牛慰劳赏赐秦军，一方面则是派人赶紧回报郑穆公这件事。郑穆公获报后，派人去招待秦国驻军休息、居住的房舍察看，结果见到他们已经捆物装车、磨利兵器、喂好马匹，完成作战的准备。于是郑穆公将计就计派皇武子去送行，让秦军知道郑国已有防备，免去一场战争。后来「厉兵秣马」被用来指完成作战准备。亦用来比喻完成事前准备工作。另外在《左传．成公十六年》中，可见「秣马利兵」一词，也作比喻完成作战准备的意思。"},
  {"name": "董狐直笔", "cid": 469044, "pid": 25255087, "num": 17, "meaning": "董狐：春秋时晋国的史官。直笔：根据事实，如实记载。指敢于秉笔直书，尊重史实，不阿权贵的正直史家。", "source": "《左传·宣公二年》", "example": "作为一名记者，他坚持董狐直笔，如实报道事实。", "story": "春秋时晋国大臣赵穿杀了国君晋灵公，掌权的赵盾却没有治罪。史官董狐在史书上直写'赵盾弑其君'。赵盾不服，董狐说你身为正卿，逃亡未出国境，回来又不讨伐逆贼，罪名就是你。孔子称赞董狐是'古之良史'，敢于如实记载。"},
  {"name": "尔虞我诈", "cid": 469044, "pid": 25255088, "num": 18, "meaning": "彼此互相诈骗。语本《左传．宣公十五年》。后用「尔虞我诈」形容人与人之间的互相猜疑，玩弄欺骗手段。\n△「易子而食」、「析骸以爨」、「钩心斗角」", "source": "《左传．宣公十五年》", "example": "为了利益，商人们经常尔虞我诈。", "story": "春秋时，楚庄王率领大军攻打宋国，包围宋国的都城。双方相持了几个月，楚国一直无法攻下宋国。宋国城内粮食的供应也将近匮乏，又听说楚国将要在宋国内建造房屋，打算长期屯兵，因此宋国人民都非常害怕。宋国因此派大夫华元进入楚营，请求退兵。华元在一天夜里来到楚军统帅子反的营帐中，威胁说：「我们宋国现在的情况，已经到了交换孩子来充饥，拿死人骨头当柴火来煮饭的地步了，尽管如此，我们宁愿战死，也绝不接受城下之盟。如果楚国能退兵三十里，那宋国对于楚国将会唯命是听。」子反听了也很惊恐，只好和宋国签订盟约，同意退兵三十里。宋国和楚国因此讲和，并以华元为人质，盟约中明白地写著：「我不欺骗你，你不必对我猜忌。」说明两国必须以诚信相待。后来「尔虞我诈」这句成语就从这里演变而出，形容人与人之间的互相猜疑，玩弄欺骗手段。典源中的「我无尔诈，尔无我虞」，用的是倒装句，它的语意其实是「我无诈尔，尔无虞我」，后来用其反意，而成为「尔虞我诈」这句成语。"},
  {"name": "结草衔环", "cid": 469044, "pid": 25255089, "num": 19, "meaning": "「结草」，指魏颗救父妾，而获老人结草御敌的故事。比喻死后报恩。典出《左传．宣公十五年》。「衔环」，指杨宝救一只黄雀，后得黄衣童子以四枚白玉环相报的故事。比喻报恩。典出南朝梁．吴均《续齐谐记》。「结草衔环」比喻至死不忘感恩图报。", "source": "「结草」：《左传．宣公十五年》_x000D_\n「衔环」：南朝梁．吴均《续齐谐记》（据《后汉书．卷五四．杨震列传》李贤注引）", "example": "大恩不言谢，我就是结草衔环，也不足为报。", "story": "「结草衔环」系由「结草」及「衔环」二语组合而成。\n\n「结草」一语出自《左传．宣公十五年》。记载春秋时秦桓公攻打晋国，晋大夫魏颗在辅氏之役大败秦军，并且捉到秦国大力士杜回的故事。相传魏颗之所以能打胜仗是因为两军对战时，战场上出现一个老人，老人在秦军必经的地方把草打结，杜回经过时被草结绊倒而被掳，晋军才获得胜利。晚上魏颗梦见老人，老人自称是宠妾的父亲，因为魏颗在父亲魏武子死后，遵从父亲神智清醒时的交代，将父亲的宠妾改嫁，老人在战场上将草打结绊倒杜回，是为了报答魏颗救了他女儿性命的恩情。\n\n「衔环」一语则是出自南朝梁．吴均《续齐谐记》。内容记录杨宝九岁时在华阴山北面，发现鸱枭攻击一只黄雀，结果黄雀受伤坠落在树下，全身爬满蝼蚁，杨宝将黄雀带回家放在巾箱中救治，以黄花喂食，百来天后黄雀伤愈，就飞走了。夜里杨宝梦见一个黄衣童子，说他是西王母的使者，为了感谢杨宝救命之恩衔来四只白玉环送给他，希望杨宝的后世子孙品德清白如玉，位极三公。而「结草衔环」又有『生当衔环，死当结草』的说法，认为「衔环」是活著报恩，「结草」是指死后报恩。后来这两个词语被合用成「结草衔环」，用来比喻至死不忘感恩图报。如元．张国宾《合汗衫》第一折：「小人斗胆，敢问老爹奶奶一个名姓也，等小人日后结草衔环，做个报答。」"},
  {"name": "疲于奔命", "cid": 469044, "pid": 25255090, "num": 20, "meaning": "「疲于奔命」之「疲」，典源作「罢」。「罢」通「疲」。指不断接到命令而忙碌奔走，精疲力尽。◎语本《左传．成公七年》。后用「疲于奔命」形容事情繁多，奔波劳累。", "source": "《左传．成公七年》\n《左传．襄公二十六年》", "example": "事业失败后，他为了养家糊口而身兼数职，从早到晚疲于奔命。", "story": "「疲于奔命」原作「罢于奔命」。春秋时，楚国结束包围宋国那场战役后，将军子重自恃有功，向楚庄王要求申、吕两地为赏赐，庄王本来答应了，但巫臣却出面阻止，向庄王分析二城的重要性。庄王听了觉得很有道理，便收回成命，子重因此对巫臣怨恨在心。后来，又有另一大臣子反，想娶夏姬为妻，巫臣也出面阻止，结果自己却娶了她而投奔晋国，子反也对他怨恨在心。楚共王即位后，子重和子反二人联手报复巫臣，杀了他的族人子阎、子荡，以及清尹弗忌、襄老的儿子黑要，并瓜分他们的财产。巫臣在晋国听到消息，便写信给二人说：「你们如此邪恶贪婪，滥杀无辜，我一定要让你们忙碌奔走，直到累死为止。」巫臣向晋国要求出使吴国，到了吴国，便训练他们的军队，教导他们打仗的技艺，然后唆使他们出兵攻打楚国以及他们的属地，子重奉命前往救援。就这样，子重、子反一年中七次奉命到前线，劳累奔波，最后属地还是被吴国攻下了不少，使吴国因此而壮大起来。巫臣写给子反、子重的信里，用「罢于奔命」表示要让二人不断接到命令奔走，使他们精疲力尽，所以教唆吴国骚扰楚国边境。典源又见《左传．襄公二十六年》。内容亦是表述巫臣和子反因抢夏姬而反目成仇，巫臣投奔晋国后，出使吴国教唆他们背叛楚国，不断地攻打楚国的属地，让楚国为救援而疲于奔命。后来「疲于奔命」这句成语就从这里演变而出，形容事情繁多，奔波劳累。"},
  {"name": "病入膏肓", "cid": 469044, "pid": 25255091, "num": 21, "meaning": "膏，心下脂肪；肓，心脏和横膈膜之间。中医之「膏肓」即指心之下，膈之上的部位。膏肓相传是身体内药力所不及的地方。「病入膏肓」原指病位深隐难治，病情危重，无药可救。典出《左传．成公十年》。后用「病入膏肓」比喻人、事已到无可挽回的程度。", "source": "《左传．成公十年》", "example": "患病就得就医，难道要等到病入膏肓吗？", "story": "春秋时晋国景公作梦，梦见恶鬼来向他讨命，之后就生病了。病重时向秦国求良医，于是秦桓公派医生缓前来为景公治病。在缓还没到达之前，景公梦见疾病化成两个小孩，其中一个说：「缓是个良医，我怕会受到伤害，要逃到哪里才好？」另一个就说：「只要躲到心脏下、横隔膜上的部位，他就奈何不了我们。」等缓到了晋国，诊视过景公的病情，说：「病已经侵入心脏和横隔膜之间的部位，不管服用药物或是针灸，药力都无法到达，所以这个病是治不好了。」果真，景公没多久就过世了。后来这个故事浓缩成「病入膏肓」，用来指人病重，无药可救；亦用于比喻人、事已到无可挽回的程度。"},
  {"name": "从善如流", "cid": 469044, "pid": 25255092, "num": 22, "meaning": "听从好的意见，就像流水般的自然顺畅。比喻乐于接受别人好的意见。◎语出《左传．成公八年》。\n△「从诲如流」、「从谏如流」", "source": "《左传．成公八年》\n《左传．昭公十三年》", "example": "他能从善如流，就是他所以成功的原因。", "story": "「从善如流」这句成语出自《左传．成公八年》。春秋时，列国林立且彼此征伐不断。根据《左传．成公六年》的记载，该年秋天，楚国率兵攻打郑国，当时和郑国订有盟约的晋国于是派兵前往援助，并且还乘机攻打临近的蔡国。楚军一听到消息之后，马上动员申、息二地的军队，准备援救蔡国。这时，晋军将领赵同、赵括向主帅栾书建议正面迎击，向楚国进军。正当栾书准备下令时，知庄子、范文子、韩献子三人却劝他说：「我们是来援救郑国的，郑国的危机解除，我们不但不退兵，还去攻打蔡国，已经是不义之战了，现在还触怒楚国，真打起来一定赢不了。就算赢了，也不是件光荣的事，反而自取其辱，不如退兵吧！」栾书听了觉得很有道理，因此决定撤军。这种能接受部属提出好意见的处事态度，在《左传．成公八年》就提到说，晋军得以屡获战功，多在于栾书能听从知庄子等三人的建议，另如能掳获沈国国君揖初也是一个明显的例子。因此对于栾书攻打沈国获胜的这件事，就有君子评论说：「从善如流，宜哉！」意思是说听从好的、正确的意见，是最适当的行为。典源又见《左传．昭公十三年》。「从善如流」的故事在此处则是表述楚国的公子比不得民心，也不像齐桓公那样重用人才，听从正确的意见，因此无法得到王位。后来，「从善如流」被用来比喻乐于接受别人好的意见。"},
  {"name": "马首是瞻", "cid": 469044, "pid": 25255093, "num": 23, "meaning": "瞻，看。「马首是瞻」指士兵依据主将的马头来决定前进的方向，比喻服从指挥或跟随他人进退。语出《左传．襄公十四年》。\n△「塞井夷灶」", "source": "《左传．襄公十四年》", "example": "这个企划案是你提出，我们就以你马首是瞻，全力配合。", "story": "《左传》里记载鲁襄公十四年时，晋国会同鲁、齐、宋、郑等国军队伐秦，要报三年前栎地一战之仇。联军到了泾水边就停住了，不肯渡河。晋国大夫叔向去找鲁将叔孙穆子商量该怎么办，叔孙穆子便引了《诗经》的话：「匏有苦叶，济有深涉，深则厉，浅则揭。」意思是匏瓜也有苦叶，渡河也会遇到深的地方。水深的话就直接下水渡河，水浅的话就撩起衣服过去。要联军渡过泾水，继续朝秦国进攻。叔向听了，就回去准备船只渡河。秦国看联军集中在泾水边，派人在泾水上游下毒，因此而毒死了不少联军士兵。郑国军队的首领子𫊸非常生气，率先出兵和秦军交战，各国军队也跟著开打，但开战好一段时间都攻不下来。这时，晋国中军将领荀偃下令说：「我们等天一亮，鸡一叫就出征，做好填井毁灶的善后工作，然后跟著我的马行动，我的马头朝向哪里，你们就跟著哪个方向走。」下军的将领栾黡一向和荀偃处不来，听了荀偃的话不服气地说：「晋国从没有人下这种命令，我偏要把马头向东回国。」栾黡说完把马头一调就走，他的部下也跟著撤兵。荀偃看到这种情况，很后悔下了这道命令，造成自家军队的分裂，心想这样非但不能打胜仗，还可能会败北，只好下令撤军回国，结束了这场战争。荀偃这道命令中，有「马首是瞻」四个字，就是要晋军跟著他的马头方向前进。后来「马首是瞻」被用来比喻服从指挥或跟随他人进退。"},
  {"name": "居安思危", "cid": 469044, "pid": 25255094, "num": 24, "meaning": "处于安乐的时候，要想到危险可能会随时出现。语出《左传．襄公十一年》所引之《书》。", "source": "《左传．襄公十一年》", "example": "在安乐时居安思危，才能防患于未然。", "story": "春秋时，有一次几个诸侯国联合攻打郑国，郑国人相当害怕，就准备礼物要去贿赂其中最大的晋国，用以求和。郑国一共送了三名乐师，装配齐全的兵车一百辆，各种乐器以及歌女十六人给晋国。晋国国君晋悼公看到后，非常高兴，将半数的乐器与歌女赐给大臣魏绛，感谢他对国家的贡献。但魏绛却谢绝了晋悼公的赠礼，并借此机会向悼公进谏说：「今天国家这样的强盛，是因国君您的才能及众臣的同心协力，我个人哪有什么贡献呢？但臣希望您在享乐的同时，不要忘了国家大事。《书经》里有句话说：『处于安乐的时候，要想到危险可能随时会出现。』这样才能及早做防备，有了防备就不怕灾难。我斗胆以这句话规劝您。」晋悼公说：「您的教训我岂敢不接受？但是没有您的话，我不可能有今天这样的成就。赏赐臣子礼物是国家的常规，不可废除，您就收下吧！」魏绛也就遵循礼制，收下这些赠礼。后来此处所引的《书经》原文「居安思危」成为一成语，用来指处于安乐的时候，要想到危险可能会随时出现。"},
  {"name": "举棋不定", "cid": 469044, "pid": 25255095, "num": 25, "meaning": "本指拿著棋子，不能决定下一步怎样下。比喻做事犹豫不决，拿不定主意。语出《左传．襄公二十五年》。", "source": "《左传．襄公二十五年》", "example": "正式棋赛，对弈者举棋不定，也是要扣时间的。", "story": "「举棋不定」本指下棋时，不能决定下一步怎样下。《左传．襄公二十五年》记载一个故事：春秋时，因为无道被驱逐在外的卫献公，派使臣来和宁喜商议回国复位的事情，宁喜同意了。大叔文子听到之后就说：「唉！《诗经》有言：『我自身都不见容于人，哪里还顾得到我的后代？』宁喜可说是不顾后代的人。怎么可以答应这件事呢？君子行事要考虑周密，《书经》上说：『凡事自始至终都抱持谨慎小心的态度，才不会让自己陷入困境之中。』《诗经》也说：『要日夜努力不懈，全心全意地侍奉国君。』今天宁喜对迎立国君复位这事的态度还不如下棋来得慎重，他怎能免除祸害呢？下棋的人如果拿著棋子却不知道下在哪里好，就无法战胜对手，更何况是迎立国君这样的大事而无法拿捏恰当？他一定免不了灾祸。九世相传的卿族，若这样一举被灭掉，真是太可悲了！」果然，卫献公回国重登王位之后，便找了个借口，把宁喜全族给灭了。后来「举棋不定」就用来比喻做事犹豫不决，拿不定主意。"},
  {"name": "尾大不掉", "cid": 469044, "pid": 25255096, "num": 26, "meaning": "掉，转动。「尾大不掉」指尾巴过大就不易摆动。比喻下属的势力强大，在上者难以驾驭。语出《左传．昭公十一年》。后亦用「尾大不掉」比喻事物因轻重关系倒置，形成难以控制的局面。", "source": "《左传．昭公十一年》", "example": "想不到他一路坐大，现在对总经理而言，他已是个尾大不掉的人物了。", "story": "「尾」指鸟兽虫鱼等脊椎末梢突出的部分，也就是尾巴。「掉」是摆动、摇动的意思。「尾大不掉」指尾巴过大就不易摆动。尾巴是肢体的末梢，理应受到肢体的控制，如今却因为尾巴长得过大，使得肢体控制不易，难以摆动，于是古人就用这种情形来比喻下属的势力强大，使得在上者难以驾驭。在《左传．昭公十一年》中，楚灵王问申无宇说︰「一个国家有大城市是好是坏呢？」申无宇就举了郑国曼伯、宋国子游、齐国无知、卫国献公四人为例，指出他们都是因为大城首长的权力太大，中央无法控制，最后叛变，因而遭到杀害或被迫出逃。所以他认为︰「如果从这四个人的例子看来，有大城市对国家是有害的。树枝太粗就会折断，尾巴太大就摆动不易，大王您应该明白这道理。」后来「尾大不掉」被用来比喻下属的势力强大，在上者难以驾驭；亦用来比喻事物因轻重关系倒置，形成难以控制的局面。"},
  {"name": "宾至如归", "cid": 469044, "pid": 25255097, "num": 27, "meaning": "客人来到这里就好像回到自己的家里。语出《左传．襄公三十一年》。后用「宾至如归」形容主人招待周到亲切，使客人感到满意。", "source": "《左传．襄公三十一年》", "example": "这家旅馆标榜宾至如归，果然名不虚传。", "story": "据《左传．襄公三十一年》载：春秋时，郑国大夫子产随同郑伯出访晋国。那时正值鲁襄公去世，晋侯以此为借口不接见他们。子产便差人将使馆的外墙拆掉，把车马、物品安置进去。晋国大夫士文伯知道后，赶紧跑来劝阻说：「我国为防盗贼，保护宾客的安全，才建造了这座使馆，还特地把外墙加高、增厚，让来访的诸侯使臣无后顾之忧。如今您破坏它，虽然您的仆从可以保护您，但别国的宾客要怎么办？我国为各诸侯的盟主，为了接待诸侯使臣而建造这座坚固的使馆。如果一直有人破坏它，我国要如何是好？因此我国君差遣我来问您这么做的原因。」子产回答说：「我们郑国是个小国，夹在几个大国之间，时有纷扰，没什么安宁的日子可过，所以按时来进贡财物。到了这里，未获接见，也不知道到底什么时候才能见到贵国国君。不敢直接将贡品送进贵国国库，放在这里又怕因日晒雨淋而损坏，到时恐怕会得罪贵国。我听说晋文公做盟主时，住的是矮小的宫室，使馆却建造得像宫殿般宽敞舒适，车库马房都整修得相当完善，道路也平整顺畅。诸侯使臣一来到，就在庭中点起照明的火炬，随时有人查巡戒备，车马有地方安顿，还有仆役供差遣。座车按时保养，奴仆百官也尽忠职守，尽心照料前来的宾客，让他们像在自己家里一样舒适，不用担心灾祸盗贼。如今贵国连别宫都那么宽广，而诸侯住的地方连车马都容不下，又有高墙隔离，又怕盗匪肆虐、风雨损坏贡品，如不破坏外墙把东西运进来，您要我们怎么办呢？如果能顺利进贡，我们会把墙修好再走，不怕辛苦，因为能容许我们这么做也是贵国国君的恩惠啊！」士文伯回去向晋侯禀告，晋侯自知理亏，向子产道歉，并热情招待郑伯后送他们回国，还下令重建使馆。后来《左传》文中的「宾至如归」，就用来形容主人招待亲切周到，使客人如同回到家里一样感到舒适满意。"},
  {"name": "上下其手", "cid": 469044, "pid": 25255098, "num": 28, "meaning": "以手势高举和向下来暗示对方，以进行舞弊的伎俩。典出《左传．襄公二十六年》。后用「上下其手」比喻玩弄手段，暗中作弊。或形容带有邪念，不礼貌地触摸他人身体。", "source": "《左传．襄公二十六年》", "example": "这是一件一群人监守自盗，上下其手，贪污公款的弊案。", "story": "据《左传．襄公二十六年》载，春秋时代，楚、郑两国交战，楚国大将军穿封戌俘虏了郑国大夫皇颉，立下大功。同行的王子围见了眼红，想要把这个功劳占为己有，硬说皇颉是被自己捉到的。穿封戌也不甘势弱，两人争执不下，于是找了伯州犁来裁断是非。伯州犁说：「这要问问被虏来的皇颉，他说的一定错不了。」便把皇颉带上，由伯州犁来质问。但其实伯州犁想袒护王子围，于是他故意先高举一手指著王子围说：「这位是王子围，也是本国国君所宠爱的弟弟。」接著放下手，向下指著穿封戌说：「这位是穿封戌，是方城外的一个县官。这两人当中，究竟是那一个捉到你的？」皇颉看到他刻意分别的手势，也听懂了话中的暗示，就顺应著回答说：「我不敌王子围，就败下阵来了。」后来这个故事被浓缩成「上下其手」，用来比喻玩弄手段，暗中作弊。亦用来形容带有邪念，不礼貌地触摸他人身体。"},
  {"name": "数典忘祖", "cid": 469044, "pid": 25255099, "num": 29, "meaning": "典，典故。「数典忘祖」指列举典故来论说事情，却反而将自己祖先掌管典籍这件事给忘了。语出《左传．昭公十五年》。后用「数典忘祖」比喻人忘本。", "source": "《左传．昭公十五年》", "example": "他总是数典忘祖，真是不肖子孙。", "story": "「数典忘祖」的「数典」，就是举列典故的意思。既然会举列典故来论说事情，却反而将自己祖先就是掌管典籍这件事都忘了。故事出自于《左传．昭公十五年》。春秋时，晋国以荀跞和籍谈为使节出使周王室，周景王设宴款待二人，宴席中所用的酒壶是鲁国进贡的，景王于是问起：「各诸侯国都会进贡一些物品给王室，为什么独独晋国没有？」籍谈回答：「每个诸侯国都曾领受王室的赠予，所以必须进献宝贵的器物回馈王室的恩典。由于晋国地处深山边塞，与王室距离遥远，皇恩根本无从顾及，我们又穷于应付戎狄，哪有什么东西可用来贡献呢？」景王听了颇不以为然，于是细数从晋国祖先开始，周朝王室曾经赠予的种种赏赐，并责问籍谈：「你的先人是负责掌管国家典籍的，为什么你会忘了这些史事呢？」籍谈听了便无话可说。等荀跞与籍谈离开后，周景王又评论籍谈说：「我看像籍谈这么忘本的人，后代子孙应该不会有什么出息吧！竟然会列举一堆典故来评论事情，却反而将自己祖先掌管典籍这件事给忘了！」后来「数典忘祖」这句成语就从这里演变而出，用来比喻人忘本。"},
  {"name": "秦庭之哭", "cid": 469044, "pid": 25255102, "num": 30, "meaning": "原指向别国请求救兵。后也指哀求别人救助。", "source": "北周・庾信《哀江南赋》：“鬼同曹社之谋，人有秦庭之哭。”", "example": "我只能用下策，派人向绵竹（刘宇亮）作～。（姚雪垠《李自成》第一卷第二十三章）", "story": "春秋时吴国攻破楚国都城，楚臣申包胥赶到秦国求救。秦哀公犹豫不决，申包胥就在秦庭上痛哭了七天七夜，不吃不喝。秦哀公深受感动，终于出兵救楚，收复了失地。后来用'秦庭之哭'比喻求人救援的急切心情。"},
  {"name": "多多益善", "cid": 303878, "pid": 12287366, "num": 31, "meaning": "益，更加。善，好。「多多益善」指愈多愈好。语出《史记．卷九二．淮阴侯列传》。", "source": "《史记．卷九二．淮阴侯列传》", "example": "金老板爱钱如命，财富对他来说是多多益善。", "story": "韩信是汉高祖刘邦开拓天下时的大将，他帮助刘邦攻下许多地方，立下不少汗马功劳。《史记》中记载，刘邦经常与他谈论各将领统御军队的能力。有一回问他：「你看我可以带多少兵？」韩信说：「皇上您不过只能带十万人的军队而已。」刘邦又问他：「那你又可以带多少兵？」韩信回答说：「我是愈多愈好。」刘邦笑著说：「既然如此，为什么你会臣服于我呢？」韩信回答：「皇上您不善带兵，却能统御将领，这就是我为什么臣服于您的原因了。这是上天给予您的能力，不是一般人可以强求的。」韩信用「多多益善」表示自己带兵的能力，军队愈庞大愈能发挥实力。后来「多多益善」演变为成语，就用来指愈多愈好。"},
  {"name": "九牛一毛", "cid": 303878, "pid": 12287365, "num": 32, "meaning": "九头牛身上的一根毫毛。比喻极大数量中的一小部分。语本《汉书．卷六二．司马迁传》。\n△「沧海一粟」", "source": "《汉书．卷六二．司马迁传》", "example": "花这点钱对他来说有如九牛一毛，他不会在乎的。", "story": "司马迁是汉代著名的史学家。据《汉书．卷六二．司马迁传》载，当时汉武帝命令李陵将军出兵攻打匈奴，终因人力缺乏而战败投降，汉武帝得知后非常生气，而诛李陵全家。司马迁挺身为李陵辩护，但汉武帝不听，反而将司马迁囚禁，后来并处以残酷的「宫刑」（将男子去势的刑罚）。司马迁在身心受到极大打击后，本想一死了之。但他仔细一想，觉得像他这样官位低微的人，如果接受法律制裁被杀，就像九头牛身上少了一根毛，一点影响也没有，和死了一只蚂蚁又有什么差别？而世人也不会把他和壮烈成仁的人相比，只会觉得他罪大恶极，死有余辜。人都会死，但死有重于泰山，也有轻于鸿毛。于是司马迁决定忍受屈辱，坚强的活下去，并且完成《史记》这部伟大著作。后来「九牛一毛」这句成语，就从原文中「九牛之一毛」的演变而出，用来比喻极大数量中的一小部分。"},
  {"name": "以身试法", "cid": 303878, "pid": 12287364, "num": 33, "meaning": "试，试探、考验。原指故意从事违反法令的事情，以考验为政者执行律令的能力与决心，后专指某人无视于法律的制裁而故意犯法。语出《汉书．卷七六．赵尹韩张两王传．王尊》。\n△「知法犯法」", "source": "《汉书．卷七六．赵尹韩张两王传．王尊》", "example": "他身为税务人员，却又以身试法，屡屡逃漏税赋。", "story": "据《汉书．卷七六．赵尹韩张两王传．王尊》载，汉代王尊，是位廉洁奉公、处事严明、不畏豪强的官吏。在他小时候父母亲过世后，就跟著伯、叔父，以帮人牧羊维生。他十分好学，牧羊之余，熟读史书，日后也因此而有机会担任官职。元帝时，他被擢升为安定太守，一上任就发出公告给所属县衙，告诫官吏要以身作则，当人民的表率，革除贪婪鄙陋的恶习，明察谨慎的尽守职责，不要无视法律尊严，而亲身去试探。后来「以身试法」演变为成语，用来形容无视于法律的制裁而故意犯法。"},
  {"name": "鸟尽弓藏", "cid": 303878, "pid": 12287363, "num": 34, "meaning": "飞鸟射尽之后，就将弓箭收藏起来。比喻事成之后，有功之人却遭到杀戮或疏远的命运。＃语本《淮南子．说林》。\n△「兔死狗烹」、「鸟尽弓藏，兔死狗烹」", "source": "＃《淮南子．说林》", "example": "他甫一上任，就开除了辅选有功的部属，真是鸟尽弓藏。", "story": "刘安是汉高祖刘邦的孙子，世袭封为淮南王。他善于文辞，受汉武帝宠爱。武帝曾命他作一篇离骚赋，他仅花一个早上的时间就完成了，文思敏捷，可见一斑。刘安与门下食客、方士合著《淮南子》一书，内容多为道家思想，并融汇了先秦各家的学说，今日仅存内篇，余皆散佚。后来刘安因为谋反的计划泄露，自缢而死。《淮南子．说林》中提到「狡兔捕获了，就把猎犬烹煮来吃；高飞的鸟射尽了，就将弓箭收藏起来」，意思就是事情成功之后，有功之人已无利用价值，不但没有得到应有的奖赏，反因才能出众，受到猜忌，而遭到杀害或疏远。后来「鸟尽弓藏」这句成语就从这里演变而出，用来比喻事成之后，有功之人却遭到杀戮或疏远的命运。"},
  {"name": "感恩图报", "cid": 303878, "pid": 12287362, "num": 35, "meaning": "感激别人的恩情而想办法回报。", "source": "宋・曾巩《上欧阳舍人书》：“其感与报，宜若何而图之。”", "example": "如果能培植他出镇方面，则～，声气相应，岂不是平添了一条臂膀。（高阳《清宫外史》上册）", "story": "春秋时伍子胥逃亡到吴国，得到公子光的厚待。他立志报仇，后来辅助吴国伐楚，报了父兄之仇，又辅佐吴国强大以回报公子光的知遇之恩。后人用'感恩图报'形容受了恩惠，时刻想着如何报答。"},
  {"name": "羽毛未丰", "cid": 303878, "pid": 12287361, "num": 36, "meaning": "羽毛尚未长满成熟。比喻势力或能力不够雄厚，还不足以独当一面。语本《战国策．秦策一》。\n△「少不更事」、「乳臭未干」", "source": "《战国策．秦策一》", "example": "他羽毛未丰，社会经验尚待磨练。", "story": "苏秦（西元前？∼３１７），字季子，洛阳人，是战国时的纵横家，与张仪一同拜师于鬼谷子。据《战国策．秦策一》载，在他学成时，想向秦惠王求官，于是游说秦王说：「贵国西边有富庶的汉中和巴蜀，北方有胡地的皮革和代地的良马，南边的巫峡和黔中地形险要，东边的殽山和函谷是要塞。土地肥沃，人民生活富足，不但地大物博，又有天然屏障，可说是天府之国。加上大王您又是贤君，士兵人民众多，只要好好利用这些有利的资源，必能并吞所有诸侯，称霸天下。」秦惠王听了苏秦的话说：「我曾听说，一只鸟在羽毛还没长丰满之前，不可以高飞；一个国家在法令还没有制定之前，不可以严刑处罚；在照顾还不够时，不可以派使百姓做事；在政教还推动不顺的时候，不可以交付大臣其他任务。今天先生你远道来向我建言，我很感激，但目前条件尚未成熟，改日再向你请教。」苏秦在秦国耗费了所有资财，上书十多次，但都不被采纳，只有无奈的返家。后来「羽毛未丰」这句成语，就从原文中「毛羽不丰满者」演变而出，用来比喻势力或能力不够雄厚，还不足以独当一面。"},
  {"name": "脍炙人口", "cid": 303878, "pid": 12287360, "num": 37, "meaning": "脍，细切肉；炙，烤肉。脍、炙皆人间美味，「脍炙人口」指美味的食物人人爱吃，或比喻美妙的诗文为人所赞赏、传诵。语出唐．林嵩〈周朴诗集序〉。后亦用「脍炙人口」比喻事物精妙而备受称诵。", "source": "唐．林嵩〈周朴诗集序〉（据《全唐文．卷八二九．林嵩》引）", "example": "桌上摆满了脍炙人口的佳肴，令人垂涎欲滴。", "story": "唐僖宗干符年间，周朴因遇黄巢之乱，不屈从黄巢而被杀。朴死后，僧人楼浩搜其诗百篇，编成《周朴诗集》二卷。唐人林嵩为《周朴诗集》写了一篇序文，文中说到周朴一生淡泊名利，放纵心灵于山林宇宙之中，视富贵如浮云。与当时的建州刺史李频、处士方干结为诗友，其间往来之诗作，都是「脍炙人口」，为人所称美传诵的好作品。文中「脍炙人口」原用于比喻美妙的诗文为人所赞赏、传诵，后则亦用来比喻事物精妙而备受称诵。"},
  {"name": "老生常谈", "cid": 303878, "pid": 12287359, "num": 38, "meaning": "「老生常谈」之「谈」，典源作「谭」。\n「谭」同「谈」。老书生的寻常言论。比喻时常听到，了无新意的老话。语本《三国志．卷二九．魏书．方技传．管辂》。", "source": "《三国志．卷二九．魏书．方技传．管辂》", "example": "「有志者事竟成」虽是老生常谈，却是颠扑不破的。", "story": "「老生常谈」原作「老生常谭」。三国时代，魏国有个名叫管辂的人，他从小对天文、星象、占卜很有兴趣；长大后，更对《周易》极有研究，常帮人占卜，十分灵验。有一天吏部尚书何晏请管辂到家中替他占卜，尚书邓飏也在场作陪。何晏对管辂说：「请你算算我有没有升到三公高位的机会？还有，我最近常梦到有数十只青蝇往我鼻子扑，不知是什么预兆？」管辂听了就讲了一套仁义道德的道理，并且告诉何晏，只要依循先古圣贤的作为，就能名列三公，青蝇也可马上驱除了。一旁的邓飏听了，就说：「都是些老书生的寻常言论，一点新意都没有。」后来「老生常谈」这句成语就从这里演变而出，用来比喻时常听到，了无新意的老话。"},
  {"name": "见猎心喜", "cid": 303878, "pid": 12287358, "num": 39, "meaning": "看到有人打猎，激起旧日的爱好而心喜。＃语本宋．周敦颐〈周子遗事〉。后用「见猎心喜」比喻旧习难忘，看见有人在做自己所爱好的事情，便心情愉悦而跃跃欲试。也单指见到喜爱事物而心中欣喜。", "source": "＃宋．周敦颐〈周子遗事〉（据《周濂溪集》卷九引）", "example": "请原谅我观棋多嘴了，实在是见猎心喜，熬不住啊！", "story": "宋代思想家程颢在十六、七岁时，非常喜欢打猎，常常到郊外从事这样的活动，享受在田野中追逐猎物的快乐。但随著年纪增长，加上忙著求学作官，能像年轻时外出打猎的时间越来越少，便以为自己对这项活动不再感到兴趣了。但他的老师周敦颐却说：「要改掉旧习谈何容易？现在你只是将这个喜好隐藏起来，等哪天又有机会接触到，你就会像从前一样喜欢它了。」果真在十二年后，程颢有天在回家的路上，看见有人在打猎，不禁勾起他的回忆，想起从前打猎的快乐，一时不禁技痒，也想下去试试。〈周子遗事〉里就记载了这件事，说程颢「在田闲见猎者，不觉有喜心」，后来「见猎心喜」这句成语就从这里演变而出，比喻旧习难忘，看见有人在做自己所爱好的事情，便心情愉悦而跃跃欲试；也单指见到喜爱事物而心中欣喜。如《儿女英雄传》第一八回：「公子何不作一番我看，或者我见猎心喜，竟领会得一两件也不见得。」"},
  {"name": "两败俱伤", "cid": 303878, "pid": 12287357, "num": 40, "meaning": "两者相争，俱受损伤。语本《新五代史．卷三八．宦者传．论》。", "source": "《新五代史．卷三八．宦者传．论》", "example": "我劝你们说和吧！免得两败俱伤。", "story": "「两败俱伤」是说双方争战，可能因此都受到损伤。这句话出自于《新五代史．卷三八．宦者传．论》。在传中，论及自古以来宦官的祸害远超过女色。因为宦官最亲近国君，在照顾日常生活起居中，有很多机会，可获得国君的信任，而让国君逐渐疏远忠良贤臣。于是国君慢慢地被宦官把持，祸害因而潜伏滋长，等到有一天国君发觉情形不对，终于想要重新信任忠臣来图谋改善。但是如果动作太慢，祸患必然加深；如果动作太猛，则宦官可能因此挟持国君。遇此状况，纵有圣贤明智之君臣，也难有所作为，最后还可能弄得双方都受到伤害。后来「两败俱伤」这句成语就从这里的原文「俱伤而两败」演变而出，用来比喻两者相争，俱受损伤。"},
  {"name": "精诚所至", "cid": 303878, "pid": 12287356, "num": 41, "meaning": "人的真诚的意志所到", "source": "《后汉书·广陵思王荆传》", "example": "精诚所至，金石为开，他的诚意终于打动了大家。", "story": "西汉时广陵王刘荆想谋反，写信招降一位名将，信中写道'精诚所加，金石为开'，意思是真诚到了极点，连金属和石头都能被打开。后来人们常说'精诚所至，金石为开'，比喻只要真心诚意，就没有办不成的事。"},
  {"name": "不入虎穴", "cid": 303878, "pid": 12287355, "num": 42, "meaning": "不冒险进入危险的境地，就不能获得大的成功，比喻要敢闯敢干。", "source": "《后汉书·班超传》", "example": "不入虎穴，焉得虎子，他决定亲自去调查真相。", "story": "东汉班超出使西域鄯善国。夜里匈奴使者来挑拨离间，班超对随从说：'不入虎穴，焉得虎子？'于是率人冲入匈奴营帐，全部歼灭。鄯善王大惊，从此归附汉朝。比喻不冒险深入险境，就不能获得成功。"},
  {"name": "曹冲称象", "cid": 303878, "pid": 12287354, "num": 43, "meaning": "比喻遇到难题要开动脑筋，用巧妙的办法解决。", "source": "《三国志·魏书·曹冲传》", "example": "这道题看似很难，我们不妨学曹冲称象，换个思路。", "story": "三国时曹操得到一头大象，众人不知如何称它的重量。小儿子曹冲想出办法：把象赶到船上，在船身刻下水痕，再换装石头直到水痕相同，分别称石，加起来就是象的重量。曹操大喜。这故事告诉我们遇事要巧想办法。"},
  {"name": "口若悬河", "cid": 303878, "pid": 12287353, "num": 44, "meaning": "说起话来像瀑布一样滔滔不绝，比喻能言善辩。＃语本南朝宋．刘义庆《世说新语．赏誉》。", "source": "＃南朝宋．刘义庆《世说新语．赏誉》", "example": "没有口若悬河的本事，怎能成为演说家？", "story": "「口若悬河」原作「悬河写水」。晋朝的郭象是玄学的集大成者，喜好《老》、《庄》，十分有才学，能言善辩，口齿伶俐，曾为《庄子》作注，流传于后世。在《世说新语．赏誉》中，记载一段太尉王衍对郭象的评语，他说：「郭象说话议论时，就像山上直泻而下的瀑布，源源不绝的灌注而下，好像永远不会枯竭的样子。」后来「口若悬河」这句成语就从这里演变而出，比喻说话滔滔不绝，能言善辩。出现「口若悬河」的书证如宋．赵蕃〈赠耆英见过〉诗四首之一：「髯曾暇能过我，诵诗口若悬河。」"},
  {"name": "势如破竹", "cid": 303878, "pid": 12287351, "num": 45, "meaning": "形势如同劈竹子一般，只要劈开上端，底下自然就会随著刀势分开。比喻战事进展顺利，毫无阻碍。语本《晋书．卷三四．杜预列传》。后亦用「势如破竹」来比喻事情进展顺利，毫无阻碍。\n△「锐不可当」、「势不可当」", "source": "《晋书．卷三四．杜预列传》", "example": "国军一路挺进，势如破竹。", "story": "据《晋书．卷三四．杜预列传》载，杜预是西晋时的著名大将，他的学识渊博，时人称为「杜武库」。蜀汉灭亡之后，孙吴偏安江东。于是晋武帝派杜预为「镇南大将军」，统军攻打东吴。战事进展得很顺利，短短数日就攻占吴国许多城池，吴军都督孙歆等人被俘。杜预想要趁胜追击，但有官员表示反对。他们认为吴国立国已久，一下子很难攻下；而且南方正是雨季，容易河水泛滥，行军不易；加上天气炎热，疫病容易流行。不如暂停进攻，等到冬天再说。但杜预举出当年乐毅的济西之战为例，认为「我军现在士气旺盛，如果趁机伐吴，就像用刀劈开竹子一样，只要劈开前面几节，下面也会顺著刀势轻易地劈开了」。后来晋军继续进攻吴国，果然节节顺利，很快地灭了吴国。「势如破竹」这句成语就从原文中的「譬如破竹」演变而出，用来比喻作战顺利，毫无阻碍；亦用来比喻事情进展顺利。"},
  {"name": "一饭千金", "cid": 303878, "pid": 12287350, "num": 46, "meaning": "比喻重重地报答对自己有恩的人。", "source": "西汉・司马迁《史记・淮阴侯列传》：“信钓于城下，诸漂母漂，有一母见信饥，饭信，竟漂数十日。又：“信至国，如所从食漂母，赐千金。”", "example": "唐・沉亚之《旌故平卢军节士》：“当渴饥之望也，～，未足者不能十金。”", "story": "汉初大将韩信少年时穷困，一位漂洗丝絮的老妇人常分饭给他吃。后来韩信被封为楚王，专程找到那位老妇人，赠她一千金以报答当年的一饭之恩。后人用'一饭千金'形容受人小恩、重重报答的感恩之心。"},
  {"name": "分道扬镳", "cid": 303878, "pid": 12287349, "num": 47, "meaning": "分道而行，形容各走各的路。＃语本《魏书．卷一四．神元平文诸帝子孙列传．河间公齐》。后用「分道扬镳」比喻人依其志向，各奔前程。_x000D_\n△「各奔前程」", "source": "＃《魏书．卷一四．神元平文诸帝子孙列传．河间公齐》", "example": "从此我跟你分道扬镳，各走各的路。", "story": "「分道扬镳」原作「分路扬镳」。北魏时，有个名叫元志的人，不但是皇亲国戚，还是当时首都洛阳的行政长官。他个性强悍，任何事都不轻易退让。有一天，他乘座车走在路上，御史中尉李彪的座车也迎面而来。由于两方都人马众多，一定要有一方退让才能通过。照理说，官小的人要让官大的人先走。而以官职来论，李彪是中央官员，元志只是地方首长，应该要礼让。但元志个性强硬，加上是皇亲国戚，硬是不肯让步。双方因此闹得不可开交，决定去找皇上评理。李彪见了孝文帝说：「我是御史中尉，官比他大，区区一个洛阳市长怎么可以这样和我对抗呢？」元志反驳说：「我是国都所在的洛阳市长，洛阳城里每个人都归我管，哪有比照其他地方官，让中央官员先走的道理？」孝文帝听了很无奈，也不去评断谁是谁非，就笑著说：「好啦！好啦！你们别吵！洛阳是我的地方，我说了就算，把路分成两半，你们两人以后各走各的就好啦！」元志和李彪两人听到皇上这么说后，就拿著尺到外面，量了道路的宽度，然后分成两半，各走自己的那一半。后来「分道扬镳」这句成语就从这里演变而出，比喻人依其志向，各奔前程。"},
  {"name": "狐假虎威", "cid": 303878, "pid": 12287348, "num": 48, "meaning": "假，借。「狐假虎威」指狐狸借老虎的威风吓走其他野兽。＃典出《尹文子》逸文。后用「狐假虎威」比喻藉著有权者的威势欺压他人、作威作福。_x000D_\n△「狗仗人势」", "source": "＃《尹文子》逸文（据《太平御览．卷四九四．人事部．诡诈》引）", "example": "他只是董事长身边的司机，却常狐假虎威地发号施令。", "story": "「狐假虎威」最早的典源出自于《尹文子》，后来有多本文献引及，其中最能表示「狐假虎威」意思的是《战国策》。《战国策》所记载的故事是这样的：战国时，昭奚恤是楚国有名的大将，威震四方。楚宣王便问群臣：「我听说北方国家都很怕昭奚恤，是这样吗？」群臣都无言以对，只有江一打了个比方说：「老虎专门捕猎各种动物为食，有一天抓到一只狐狸，狐狸说：『你敢吃我吗？天帝已命我治理百兽，你若吃我就是违逆天帝的命令。如果不相信，可以走在我后面，看看其他动物见到我有什么反应。』于是老虎便半信半疑的跟在狐狸后面，所有动物看到都吓得逃走。老虎以为牠们真的是怕狐狸，而不知道其实野兽们怕的是牠自己。今天大王您有五千里的领地，有超过百万的大军，但统御军队的是昭奚恤，所以北方诸国其实怕的不是昭奚恤本人，而是您的军队啊！犹如野兽们怕的是老虎，而不是狐狸一样。」后来这个故事被浓缩成「狐假虎威」，用来比喻藉著有权者的威势欺压他人、作威作福。"},
  {"name": "妄自尊大", "cid": 303878, "pid": 12287347, "num": 49, "meaning": "狂妄地自尊自大。语出《后汉书．卷二四．马援列传》。\n△「不修边幅」、「夜郎自大」", "source": "《后汉书．卷二四．马援列传》", "example": "稍有成就就妄自尊大的人，难成大器。", "story": "王莽末年，群雄四起，经过几次的争战后，就属隗（ㄨㄟˇ）嚣、公孙述、刘秀三人的势力最大。据《后汉书．卷二四．马援列传》载，隗嚣派马援前往蜀地探探公孙述的实力，马援和公孙述原是旧识，所以马援本以为他俩这次见面，一定可以像从前一样无所不谈。没想到马援抵达蜀地后，公孙述却摆出帝王的大场面，还要以皇帝的名义，给马援封爵。马援很不高兴，私底下跟公孙述左右的人说：「现在是谁的天下都还未底定，公孙述不趁现在去求取贤士，帮自己争天下，反而在这里讲排场，自以为是皇帝，天下英才如何会久留？」于是就告辞走了。马援回去对隗嚣说：「公孙述只是井底之蛙而已，却狂妄自大。你根本不用担心他这股势力，只要专心全力对付刘秀就够了！」后来原文中的「妄自尊大 」就用来指毫无根据的自尊自大。"},
  {"name": "小心翼翼", "cid": 303878, "pid": 12287346, "num": 50, "meaning": "形容举止十分谨慎，不敢懈怠疏忽。◎语出《诗经．大雅．大明》。", "source": "《诗经．大雅．大明》\n《诗经．大雅．烝民》", "example": "护士小心翼翼地把药水涂抹在病人受伤的皮肤上。", "story": "《诗经》是现存最早的诗歌总集，非一时一地一人之作，主要是采集从周初至春秋中叶的歌谣作品和宗庙乐章而成，共三百零五篇，分为风、雅、颂三大类，为文学诗歌总集之祖。〈大雅．大明〉篇是在歌颂周文王，他非常的恭敬谨慎，以虔敬的心和美好的德行来事奉上帝，因此得到了许多的福禄。行动举止中，不违背应有的德行，他的美德因此彰显，四方的诸侯国都来归附。典源又见《诗经．大雅．烝民》。内容则是表述仲山甫的德行，小心恭谨，效法古训，具有良好的仪容风度。因此天子赋予他重责大任，颁布命令于四方。后来诗中的「小心翼翼」演变为成语，用来形容举止十分谨慎，不敢懈怠疏忽。"},
  {"name": "有志者事竟成", "cid": 303878, "pid": 12287345, "num": 51, "meaning": "只要有决心，有毅力，事情终究会成功。", "source": "《后汉书·耿弇传》", "example": "只要坚持练习，有志者事竟成，你一定能学会。", "story": "东汉大将耿弇讨伐割据势力，屡建奇功。光武帝刘秀称赞他说：'将军前在南阳，建此大策，常以为落落难合，有志者事竟成也！'意思是说，当初觉得难以实现，但有志气的人终究能把事情做成。"},
  {"name": "安然无恙", "cid": 303878, "pid": 12287344, "num": 52, "meaning": "恙，祸患、疾病。「安然无恙」指平安没有疾病、祸患等事故。语本《战国策．齐策四》。", "source": "《战国策．齐策四》", "example": "看到他安然无恙地回到家里，我们都松了一口气。", "story": "「恙」是传说中的一种啮虫。《风俗通义》上记载：「恙，噬人虫也，食人心。人每患苦之，故俗相劳问者云『无恙』，非为病也。」由于古人居住环境卫生较差，容易被恙咬伤，引发疾病，所以「恙」就成了疾病、灾祸的代名词。有小病的话，就称为「微恙」、「小恙」，没有病就是「无恙」。在《战国策．齐策四》记载了一个故事：有一次赵威后接见齐王派来的使者，还没有将国书拆开，赵威后就问齐国使者道︰「齐国今年的收成好吗？百姓们都好吗？齐王也好吗？」使者听了，很不高兴地说︰「我奉大王的命令出使贵国，威后您却先问收成和百姓，然后才问大王好不好，岂非尊卑颠倒了吗？」赵威后就回答说︰「你说的不对。如果没有好的收成，那百姓怎么能过好日子？如果没有百姓，哪里来的国君？难道你要我舍本问末吗？」此处《战国策》原文就用了「无恙」，可见「无恙」一语通行甚早。后来演变成「安然无恙」这个成语，用来表示平安没有疾病、祸患等事故。"},
  {"name": "邯郸学步", "cid": 303878, "pid": 12287343, "num": 53, "meaning": "学习邯郸人走路的姿势。比喻模仿不成，反而失去自我。语本《庄子．秋水》。_x000D_\n△「井底之蛙」、「以管窥天」", "source": "《庄子．秋水》", "example": "引进新科技时，最忌讳硬生生地模仿，此种邯郸学步，注定要失败。", "story": "《庄子．秋水》有一段战国时名家公孙龙和魏国公子魏牟的对话。公孙龙认为自己通达事理，博闻善辩。但当他听到庄子的言论却觉得困惑，无法理解，于是问魏牟是否是因自己的学识不足？魏牟则以为公孙龙像井底之蛙，见识浅薄，眼界狭小，所以无法通晓庄子言论玄妙之处。就算花工夫去学习，也只能学得皮毛。因此劝公孙龙别再试图理解，免得到了最后不但不能学得庄子的学问，反而丧失了自己原有的学问，就像战国时燕国有位年轻人，因为羡慕赵国首都邯郸人走路的姿态，所以前往学习。结果不但没学成邯郸人走路的美姿，连自己原来的步法都忘了，最后只有爬著回去。后来「邯郸学步」这句成语就从这里演变而出，用来比喻模仿不成，反而失去自我。"},
  {"name": "刻舟求剑", "cid": 303878, "pid": 12287342, "num": 54, "meaning": "剑掉入水中，在船舷刻上记号，待船停止后仍从记号处下水寻剑。比喻拘泥固执，不知变通。典出《吕氏春秋．慎大览．察今》。\n△「守株待兔」、「胶柱鼓瑟」", "source": "《吕氏春秋．慎大览．察今》", "example": "因应各种状况，我们不宜刻舟求剑，不知变通。", "story": "战国时，秦国丞相吕不韦在《吕氏春秋》一书中，阐述君王治理国政的道理。他认为君王治国应要符合时宜，不能一味沿袭旧法，因为环境会随著时间改变。他举了一个例子：楚国有人渡江时，剑掉到水里，他便很快地在船身上刻了记号，说：「我的剑就是从这里掉下去的。」等到船停了，他就从记号处下水找剑。可是船已经走动了，但落水的剑却不会动，这样找剑，不是很奇怪吗？如果用旧法治理国家，而不考虑时空的转变，就像这个求剑者的行为一样令人困惑。后来这个典源被浓缩成「刻舟求剑」，用来比喻拘泥固执，不知变通。"},
  {"name": "论功行赏", "cid": 303878, "pid": 12287341, "num": 55, "meaning": "按功劳的大小给于奖赏。", "source": "晋・陈寿《三国志・吴志・顾谭传》：“时论功行赏，以为驻敌之功大，退敌之功小。”", "example": "时～，以为驻敌之功大，退敌之功小。（《三国志・吴书・顾潭传》）", "story": "汉朝建立后，刘邦评定功臣。众人争功不休，刘邦认为萧何功劳最大，先封他为酂侯，食邑最多，再按功劳大小依次封赏众人。这种按照功劳给予奖赏的做法，就叫'论功行赏'。"},
  {"name": "一日千里", "cid": 303878, "pid": 12287340, "num": 56, "meaning": "一日能行千里之远。形容良马跑得很快。＃语本《庄子．秋水》。后亦用「一日千里」形容速度极快。亦用于比喻进步极快或进展迅速。或比喻人才出众。", "source": "＃《庄子．秋水》*1*", "example": "《水浒传》有位神行太保，走路速度一日千里。", "story": "大哲学家庄子曾经写了一篇〈秋水〉来说明万物齐一的道理，里头举了许多例子：同样是禅让天下，尧舜就能称帝，而之、哙（ㄎㄨㄞˋ）就被灭亡；同样是用兵争天下，汤武就能称王，而白公就失败。可见「禅让而称帝」、「兵争而称王」，因时而变，不能作为常态来看。又例如：大屋的梁柱可以取来冲撞城门，但却无法用来填充小孔穴，这是因为不同的器物有不同的功用。骐骥（ㄑㄧˊ　ㄐㄧˋ）和骅骝（ㄏㄨㄚˊ　ㄌㄧㄡˊ）都是千里马，一日可跑千里之远，但要他们捕捉老鼠却就不如野猫，这是因为千里马与野猫专长不同的技艺。猫头鹰在黑夜里可以抓到微小的跳蚤，看到细小的毫毛，但一到白天，即使张大眼睛也看不到庞大的山丘，这是因为他特有的性能。从这些例子可以得知，万物从其各自拥有的特长去看，当然都具有「有用的能力」，但是换个角度，就可以发现每样事物也都有它「无用的地方」。所以观察事情，不能只守住一个立场，那只会得到一偏的结论。要试著超越「有无」、「治乱」等这些观念，试用齐一的眼光来看万物，才能渐渐突破原有坚持的偏见。后来这里的「一日驰千里」，演变成「一日千里」这句成语，用来形容马跑得很快，亦用于形容速度极快或比喻进步极快或进展迅速。另外还可用来比喻人才出众，如《后汉书．卷六六．陈王列传．王允》中便记载了东汉时的王允，才智出众，卓越超群，同郡的名士郭泰见到他时，曾赞叹道：「王生一日千里，王佐才也。」就是说：王允像是千里马一样的与众不同，绝对是个辅佐君王的人材！"},
  {"name": "画饼充饥", "cid": 303878, "pid": 12287339, "num": 57, "meaning": "即「画饼充饥」。「饥」通「饥」。见「画饼充饥」条。01.唐．冯用之〈权论〉：「圣人知道德有不可为之时，礼义有不可施之时，刑名有不可威之时，由是济之以权也。其或不可为而为，则礼义如画饼充饥矣。」02.《警世通言．卷三四．王娇鸾百年长恨》：「鸾拆书看了，虽然不曾定个来期，也当画饼充饥，望梅止渴。」", "source": "", "example": "", "story": "此处所列为「画饼充饥」之典故说明，提供参考。画饼，画成的饼。比喻徒具形式而无实用价值。根据《三国志》记载，三国魏卢毓为人正直不阿，敢于上谏直言，颇得魏明帝赏识，任命为吏部尚书，担任推举人才的工作。魏明帝向来厌恶那些声名显扬，却无才学的人，这时刚好中书郎一职出缺，于是下诏要求卢毓推举人才时要注重真才实学，不要选那些徒具名声的人，否则便像在地上画饼一般，只能看而不能吃。后来「画饼充饥」这句成语就从这里演变而出，用来比喻徒具虚名而无益于实际。亦用来比喻徒事空想无益于事。"},
  {"name": "画蛇添足", "cid": 303878, "pid": 12287338, "num": 58, "meaning": "画好蛇后，多事为它添上蛇足，结果反而失去本已赢得的酒。比喻多此一举，反将事情弄糟。典出《战国策．齐策二》。", "source": "《战国策．齐策二》", "example": "写文章意足即可，不要画蛇添足。", "story": "据《战国策．齐策二》载，战国时，昭阳为楚国大将，当时昭阳已攻下魏国的八座城池，接著又计划讨伐齐国，于是齐王派陈轸前来游说昭阳，请他不要攻打齐国，陈轸就引用了「画蛇添足」的故事作比方来说明，故事的内容是说：在楚国有个专管庙堂祭祀的人，把一壶酒赏给办事的人们去喝。但是人多酒少，不够大家分喝，于是大家商量了一下，想出在地上画蛇比赛的方式，谁先画好一条蛇，谁就可以喝那壶酒。比赛开始之后，其中有一个人画得很快，不一会儿就画好蛇，于是拿起酒准备要喝，看著别人还在慢慢的画著，就左手拿著酒壶，右手握著笔又在地上画了起来，并且还得意地说：「我还能有时间给蛇画上脚呢！」蛇脚还没画好，另一个人已经画好了蛇，就把酒抢过去，说：「蛇本来就没有脚，你怎能再给蛇添上脚呢！」说完，就把酒给喝了。那个替蛇画上脚的人，最后就失去了原本是属于他的那壶酒。后来这个故事被浓缩成「画蛇添足」，用来比喻多此一举，反将事情弄糟。"},
  {"name": "买椟还珠", "cid": 303878, "pid": 12287337, "num": 59, "meaning": "买了装珍珠的盒子，而把珍珠退还。典出《韩非子．外储说左上》。后用「买椟还珠」比喻舍本逐末，取舍失当。", "source": "《韩非子．外储说左上》", "example": "先把采购资讯和标的掌握好，免得受买椟还珠的讥讽。", "story": "《韩非子．外储说左上》记载，有一天楚王对田鸠说：「墨子之学是当代非常著名的学说，它的内容很好，但文词却多不美妙，是什么原因呢？」田鸠就说了两个故事，其一是：「有一个楚国人到郑国卖珍珠，他用木兰木作了一个装珍珠的盒子，用香木薰得香香的，盒子外面用翡翠和玫瑰来装饰。结果郑国人买了他的盒子，却将珍珠退还。那楚人可说是擅于卖盒子，却不擅于卖珍珠了！现在发表言论的人，都用巧妙的言辞；作君王的，只喜欢看这些美妙的言辞，却忽略了这些言论是有功用的。墨子的学说，是传授先王的道术，阐述圣人的言论，普遍告知世人。所以并不加以修饰，以免人们只喜爱他美妙的言辞，而忽略了其中的功用。」后来韩非子所谓的楚人卖珠这个故事，被浓缩成「买椟还珠」，用来比喻舍本逐末，取舍失当。"},
  {"name": "弄巧成拙", "cid": 303878, "pid": 12287336, "num": 60, "meaning": "本想卖弄才能、聪明，却反而做了蠢事。比喻枉费心机。※语或出《五灯会元．卷三．江西马祖道一禅师》。", "source": "※《五灯会元．卷三．江西马祖道一禅师》", "example": "读书没有捷径，投机取巧，必然弄巧成拙。", "story": "马祖道一，俗姓马，世人称为马祖，是中国禅宗史上最有声望的人物之一。马祖的禅法主要围绕著人达到觉悟解脱的心性依据和应当如何对待修行的问题。马祖以「平常心是道」、「即心是佛」大力弘扬禅风。马祖除了上堂示众的普说之外，对众多弟子采取灵活多样的教诲引导方法。在《五灯会元》中有一段记载马祖和庞居士的对话，大意是说马祖对庞居士自认为已经领悟本来面目，没有表示认可，只是眼睛往下看；对于说自己善弹无弦之琴表示默许，所以将眼睛往上看。马祖以动作回答，让庞居士自己省悟。庞居士觉得自己本想卖弄聪明，结果反而做了蠢事，实在是弄巧成拙。后来「弄巧成拙」被用来比喻枉费心机。"},
  {"name": "夸父逐日", "cid": 303878, "pid": 12221599, "num": 61, "meaning": "比喻人有大志，也比喻不自量力。", "source": "战国・郑・列御寇《列子・汤问》：“夸父不量力，欲追日影，逐之于隅谷之际。渴欲得饮，赴饮河渭。河渭不足，将走北饮大泽。未至，道渴而死。”", "example": "他想一个人造一座大桥，真有点夸父逐日的劲头。", "story": "远古时巨人夸父想追上太阳。他一路奔跑，追到禺谷，口渴难忍，喝干了黄河、渭水仍不够，又向北方大泽奔去，途中渴死。他丢下的手杖化作一片桃林。故事出自《山海经》，既赞其壮志，也叹其不自量力。"},
  {"name": "水中捞月", "cid": 303878, "pid": 12221598, "num": 62, "meaning": "到水中去捞月亮。比喻去做根本做不到的事情，只能白费力气。", "source": "元・杨景贤《刘行道》三：“恰便似沙里淘金，石中取火，水中捞月。”", "example": "恰便似沙里淘金，石中取火，～。（元・杨景贤《刘行首》第三折）", "story": "一群猴子见井里有月亮的倒影，以为月亮掉进井里，便一个接一个倒挂着下井去捞，结果什么也没捞着。这个故事比喻去做根本做不到的事，白白浪费力气。它出自佛教故事，劝人不要被虚幻的现象迷惑。"},
  {"name": "天衣无缝", "cid": 303878, "pid": 12221597, "num": 63, "meaning": "古代传说天神的衣服，不用针线缝制，故没有缝痕。＃典出《神异经》。后用「天衣无缝」比喻诗文浑然天成，没有斧凿痕迹；亦用于比喻事物或计划周密完美，没有一丝破绽或缺点。", "source": "＃《神异经》（据《太平御览．卷六八五．服章部二．委貌冠》引）*1*", "example": "这篇推理小说的结构，简直是天衣无缝、无懈可击。", "story": "《神异经》大约是一本汉代的小说。此书是在《山海经》的影响下产生的，不论是在内容、笔法等各方面都有意模仿《山海经》，只是作者另外添加了神仙方术和儒家思想的观念在其中。《神异经》记载了一段故事：西方边远的地方有一些人，他们不必阅读传统的典籍巨著，但行为思想，却能合乎礼仪规范。天神赐给他们衣服，男的穿著红色衣服，白色腰带，戴著帽子；女的穿著绿色衣服，戴著华丽的首饰。这些天衣不是用一般凡间针线缝制，所以都没有缝痕。后来这个故事被浓缩成「天衣无缝」，用来比喻诗文浑然天成，没有斧凿痕迹；亦用于比喻事物或计划周密完美，没有一丝破绽或缺点。"},
  {"name": "草船借箭", "cid": 303878, "pid": 12221596, "num": 64, "meaning": "运用智谋，凭借他人的人力或财力来达到自己的目的。", "source": "《三国演义》", "example": "他像草船借箭一样，借别人的力量完成了任务。", "story": "三国时周瑜要诸葛亮十天内造十万支箭，诸葛亮说只需三天。他趁大雾，用扎满草人的船驶近曹营，曹操看不清，放箭如雨，全射在草人上。诸葛亮轻松'借'得十万余箭。比喻善于利用条件、机智取胜。"},
  {"name": "画龙点睛", "cid": 303878, "pid": 12221595, "num": 65, "meaning": "画了龙后，为其点上眼睛，龙便乘云飞去。比喻绘画、作文时在最重要之处加上一笔，使全体更加生动传神。＃典出晋．王嘉《拾遗记．卷四．秦始皇》。后亦用「画龙点睛」比喻做事能握要点，让整件事更加圆满。", "source": "＃晋．王嘉《拾遗记．卷四．秦始皇》*1*", "example": "好对联得配上好字，才能收画龙点睛之妙。", "story": "晋代王嘉所编的《拾遗记》中，搜集了许多古代的奇闻异事，其中有一篇记载著秦始皇时发生的一件怪事。传说在始皇元年，有个小国献给秦始皇一位手艺精湛的工匠，无论是画画、雕刻都相当拿手。他雕出来的动物每只都栩栩如生，绘画工夫更是了得，随便一出手便是一幅壮丽的图画。他曾画了几只龙凤，每只都像真的在飞一样，十分传神。但是都没有点上眼睛，因为听说点了眼睛就会真地飞走了。在唐代张彦远的《历代名画记》中，也提到张僧繇曾在金陵安乐寺的墙壁上，画了四条龙，其中两条一经点睛后，雷电大作，龙具有了生命，破壁飞上天去。后来「画龙点睛」一语，就用来比喻绘画、作文时在最重要之处加上一笔，使得全体更加生动传神；后亦用来比喻做事能把握要点，让整件事更加圆满。"},
  {"name": "毛遂自荐", "cid": 303878, "pid": 12221594, "num": 66, "meaning": "战国时，平原君之门下食客毛遂自荐跟随前往楚国游说。典出《史记．卷七六．平原君虞卿列传．平原君》。后用「毛遂自荐」比喻自告奋勇，自我推荐。\n△「自告奋勇」、「脱颖而出」", "source": "《史记．卷七六．平原君虞卿列传．平原君》", "example": "我进公司是毛遂自荐的。", "story": "据《史记．卷七六．平原君虞卿列传．平原君》载，战国时，秦国出兵攻打赵国，包围了赵都邯郸，情况十分危急，于是赵王派平原君前往楚国，请求援救。平原君打算在其门下食客挑选出二十个文武人才一同前往，但只选出十九个，剩下的都不符合条件。这时，有一个名叫毛遂的人，主动向平原君自我推荐，请求加入前往楚国的行列。平原君问：「你在我门下多久了？」毛遂回答：「三年了。」平原君说：「一个真正有才能的人，就好像一把放在袋子里的锥子一样，立刻就会显露出锋利的锥尖。而你在我门下三年了，我却没听说过你有什么表现，你还是留下吧！」毛遂说：「我现在自我推荐，就是请求你把我放进袋子里，如果早点有这样的机会，那我就不只是露出锥尖而已，而是早就显露出才能，锋芒毕露了！」平原君觉得毛遂说得有道理，就答应让他一同前往。到了楚国，平原君和楚王会谈，从早上到中午，都还没有结果。毛遂于是持剑走到楚王面前，极力说明赵、楚联合抗秦的利害关系。楚王终于被说服，答应赵国愿意出兵援救。于是两国当场歃血为盟，誓守联合抗秦的盟约。毛遂这次不仅帮平原君完成任务，也为国家立下了功劳，让大家对他刮目相看，平原君因此待他为上宾。后来这个故事被浓缩成「毛遂自荐」这个成语，比喻自告奋勇，自我推荐。"},
  {"name": "三顾茅庐", "cid": 303878, "pid": 12221593, "num": 67, "meaning": "指汉末刘备往访诸葛亮，凡三次，才得见。◎语本三国蜀．诸葛亮〈前出师表〉。后用「三顾茅庐」比喻对贤才真心诚意的邀请、拜访。\n△「初出茅庐」", "source": "三国蜀．诸葛亮〈前出师表〉（据《三国志．卷三五．蜀书．诸葛亮传》引）\n《三国志．卷三五．蜀书．诸葛亮传》", "example": "董事长以三顾茅庐的诚心，到处延揽人才。", "story": "东汉末年天下纷乱，打著「复兴汉室」名号起兵的刘备，在屯田新野时，从徐庶口中得知避居在南阳隆中的诸葛亮是个能人，于是前去拜访，一连去了三次，才见到人。诸葛亮在〈前出师表〉中提到了这件事：「先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中。」刘备不顾身分，一连三次专程拜访的诚心，终于感动诸葛亮答应出山替他奔波效力。后来「三顾茅庐」这句成语就从这里演变而出，用来比喻对贤才真心诚意的邀请、拜访。"},
  {"name": "闻鸡起舞", "cid": 303878, "pid": 12221592, "num": 68, "meaning": "一听到鸡啼声，立即起床操练武艺。典出《晋书．卷六二．祖逖列传》。后用「闻鸡起舞」比喻把握时机，及时奋起行动。", "source": "《晋书．卷六二．祖逖列传》", "example": "古人是闻鸡起舞，他们是日上三竿，仍在床上。", "story": "据《晋书．卷六二．祖逖列传》载，晋代的祖逖，性格豪迈，为人侠义。当时国家情势内忧外患，祖逖立志要为国家尽力，平定动乱。他与好朋友刘琨一起在司州任职，志向相同，两人便住在一起，相互砥砺。有一回，祖逖在半夜时听到鸡啼声，虽然天还没亮，但他惊觉时间相当宝贵，应该好好把握，就踢醒睡在一旁刘琨说：「听到鸡叫声了吗？我们得赶快起床，把握时间练武吧！」于是两人无惧夜里的凉意，到院子里舞剑锻炼身体，每天都不间断，练就了一身好武艺。后来祖逖受到皇帝的赏识，被任命为大将军，带兵平定动乱，收复许多失土，一偿报效国家的心愿。后来这个故事被浓缩成「闻鸡起舞」，用来比喻把握时机，及时奋起行动。"},
  {"name": "半途而废", "cid": 303878, "pid": 12221591, "num": 69, "meaning": "「半途而废」之「途」，典源作「涂」。事情没做成功就停止。比喻做事情有始无终。语本《礼记．中庸》。\n△「中道而废」", "source": "《礼记．中庸》", "example": "一个人做事情老是半途而废，怎能有成？", "story": "「半途而废」原作「半涂而废」。「半途」是半路的意思，即「中道」、「中途」，「半途而废」是指半路就停下来而不再前进，整句成语引申为事情没能持续下去就停止的意思。这个成语出自《礼记．中庸》，孔子认为君子遵循正道而行，假如半途而废，而他是绝不能中途停止的。充分显露出对圣人德行的向慕。「半途而废」就用来比喻做事情有始无终。"},
  {"name": "不自量力", "cid": 303878, "pid": 12221590, "num": 70, "meaning": "自己不估量自己的能力。指过高地估计自己的实力。", "source": "唐・玄奘《大唐西域记・摩揭陀国上》：“今诸外道不自量力，结党连群，敢声论鼓，惟愿大师摧诸异道。”", "example": "就说我们殿试都是侥幸名列上等，并非～，何敢自不量力，妄自谈文。（清・李汝珍《镜花缘》第八十七回）", "story": "春秋时弱小的息国与郑国不和，息侯不听大臣劝阻，贸然出兵攻打郑国，结果大败而归。君子评论说息国'不度德，不量力'。后来'不自量力'比喻不能正确估计自己的力量，去做根本办不到的事。"},
  {"name": "囫囵吞枣", "cid": 303878, "pid": 12221589, "num": 71, "meaning": "「囫囵吞枣」之「囫囵」，典源作「浑仑」。「浑仑」同「囫囵」。囫囵，整个。「囫囵吞枣」指吃枣子时不加咀嚼，把整个都吞下去。＃语本《佛果圜悟禅师碧岩录．卷三．赵州大萝卜头》。后用「囫囵吞枣」比喻理解事物笼统含糊，或为学不求甚解。\n△「生吞活剥」", "source": "＃《佛果圜悟禅师碧岩录．卷三．赵州大萝卜头》*1*", "example": "许多基本概念的学习是不能囫囵吞枣的。", "story": "「囫囵吞枣」原作「浑仑吞枣」。《碧岩录》卷三记载了一段故事：有位僧人问赵州和尚是否曾亲见过南泉大师？赵州打了个比喻，回答说：「镇州出产大萝卜头。」本来这位僧人问赵州时是别有用心的，想不到赵州不直接回答他的问题，打了比方。这番对答，表面上看来真是无味，直堵人口，害得这位僧人才一开口，却只换得瞪大眼睛，不知如何接下去。赵州此番回答若是听在有智慧人的耳内，恰如电光石火，一闻便透彻心灵。否则，想破头了也不知所云。有人以为镇州出产大萝卜头，天下人皆知，赵州去参见南泉，也是天下人皆知。这位僧人明知故问，所以赵州才会如此回答，不跟他啰嗦。恰如曾经有僧人问九峰和尚：「是否见过延寿和尚？」九峰回答说：「山前的麦子成熟没？」这个回答和赵州的回答刚好呼应。就像是两枝无孔的大铁槌，一敲就定。赵州和尚本无机心，想不到僧人轻轻一问，得了个瞪大眼睛的讶异。此番对答，若是有智慧的人，可以细嚼慢咽，意趣无穷；没有智慧的人，可能会像一口把枣子吞下肚，索然无味，不知所云。后来「囫囵吞枣」就从《碧岩录》原文中的「浑仑吞个枣」演变而出，用来比喻理解事物笼统含糊，或为学不求甚解。"},
  {"name": "南辕北辙", "cid": 303878, "pid": 12221588, "num": 72, "meaning": "辕，大车前部套在牲口左右两边的木头，用以拖车。辙，车辆驶过留下的痕迹。「南辕北辙」指本要向南，但却驾车往北行，离目的地越来越远。比喻行动和想要达到的目的相反。典出《战国策．魏策四》。后亦用「南辕北辙」比喻二者彼此背道而驰，或比喻遥隔两地。_x000D_\n△「背道而驰」", "source": "《战国策．魏策四》", "example": "想成功却又不努力，岂非南辕北辙？", "story": "据《战国策．魏策四》载，战国时，魏国安厘王想要出兵攻打赵国首都邯郸。臣子季梁得知了这个消息，立即从旅途中折返，想回去劝阻。一回到魏国，季梁顾不得衣服的脏乱和满身的尘埃，便匆匆忙忙地赶去见安厘王，告诉他说：「我在路上遇到一个人，他要去楚国，却驾车往北方走。我问他说你要去南方的楚国，怎么会往北方走呢？他回答说他有很快的马、很多的旅费、很好的马伕，所以绝对可以到达目的地。但实际上因为他是往相反的方向走，马愈快、旅费愈多、马伕愈好，反而使他离楚国愈远。今天大王您想成就霸王之业，取信于天下诸侯，依仗著强大的军力去攻打赵国，想借此扩充领地，提高声望，其实这样的举动愈多，愈失信于天下，离成就霸王事业的心愿也就愈远，这不正如想到楚国却往北方走一样，永远达不到目的！」后来这个故事被浓缩成「南辕北辙」，用来比喻志向和行为背道而驰，现在凡是做「背道而驰」的事，都可以称为「南辕北辙」。另外，这句成语还可引申用来比喻遥隔两地。"},
  {"name": "自相矛盾", "cid": 303878, "pid": 12221587, "num": 73, "meaning": "比喻言语或行事前后无法呼应，互相抵触。◎典出《韩非子．难一》。", "source": "《韩非子．难一》\n《韩非子．难势》", "example": "你的论点根本自相矛盾，如何说服他人？", "story": "矛是攻击的兵器，而盾是用来防御兵器攻击的器具。在《韩非子．难一》中，举了一个故事说：有个楚国人在市集上卖矛和盾。刚开始时先是夸赞他的盾说：「我这面盾非常坚固，任何锋利的东西都刺不破它。」过了一会儿，又夸赞他的矛说：「我这只矛是最锋利的，没有什么东西是它不能刺破的。」这时，有人紧接著问说：「如果用你的矛刺你的盾，那结果会是怎样呢？」这一问，让卖矛与盾的人无言以对。典源又见《韩非子．难势》。后来这个故事被浓缩成「自相矛盾」，用来比喻言语或行事前后无法呼应，互相抵触。"},
  {"name": "脚踏实地", "cid": 303878, "pid": 12221586, "num": 74, "meaning": "比喻做事切实稳健。语出宋．邵伯温《邵氏闻见录》卷一八。", "source": "宋．邵伯温《邵氏闻见录》卷一八", "example": "他就这样脚踏实地，创立了他的超市王国。", "story": "司马光是宋朝重要的史学家。宋英宗时，他与范祖禹、刘攽、刘恕等人奉命编撰《资治通鉴》，由他主编。编写这部史书时，司马光每天凌晨就开始工作，直到半夜才休息，丝毫不敢懈怠。为了怕睡得太久，耽误了工作，还特地制作了一个「警枕」，好让自己睡得不安稳而警醒。而司马光对于书稿的要求更是严格，他先广泛的收集资料，然后串连、剪裁，加以润色，反复修改，直到满意为止。例如其中唐代部分的稿子，原有六百多卷，等到最后定稿时只剩下八十卷，可见其要求之精简。等到编成后，全书共有二百九十四卷，全都用正楷工整地写好，一笔不苟。这种认真踏实的治学态度，受到了当时人们的赞赏。宋神宗更为这本史书取名为《资治通鉴》，表示这部史书能作为历代治乱兴亡的借镜。司马光做事认真勤恳的态度，可以从这儿看出。所以有一次司马光问他的好友邵雍，说：「你认为我是一个怎么样的人？」邵雍便回答：「你是一个脚踏实地的人。」正是对于司马光最贴切的赞美。后来「脚踏实地」被用来比喻做事切实稳健。"},
  {"name": "勤能补拙", "cid": 303878, "pid": 12221585, "num": 75, "meaning": "勤奋能够弥补不足。", "source": "宋・邵雍《弄笔吟》：“弄假像真终是假，将勤补拙总输勤。”", "example": "我不聪明，但相信勤能补拙，多练就会进步。", "story": "唐代诗人白居易说自己天资并不聪明，靠的是勤学苦练。他说：'勤能补拙是良训，一分辛苦一分才。'意思是勤奋可以弥补天生的笨拙。只要肯下功夫，笨人也能把事情做好，这是古人留给我们的宝贵训诫。"},
  {"name": "日积月累", "cid": 303878, "pid": 12221584, "num": 76, "meaning": "一天一天地、一月一月地不断积累。指长时间不断地积累。", "source": "《宋史・乔行简传》：“借纳忠效勤之意，而售其阴险巧佞之奸，日积月累，气势盖张；人主之威权，将为所窃弄而不自知矣。”", "example": "自是以后，～，千百成群，其为国之蠹害甚矣。（清・顾炎武《日知录》卷九）", "story": "学习就像积土成山、积水成渊，一天一点，慢慢就会很多。宋代人说'日积月累，气势益张'，指时间长了力量就壮大。这个成语比喻学问、财富、成绩都是一天天积累起来的，不可急于求成。"},
  {"name": "孺子可教", "cid": 303878, "pid": 12221583, "num": 77, "meaning": "孺子，小孩子。「孺子可教」指年轻人可以教诲栽培。用于称许之意。语出《史记．卷五五．留侯世家》。", "source": "《史记．卷五五．留侯世家》", "example": "才吩咐过一次，他就永志不忘，真是孺子可教。", "story": "「孺子」原是幼童的通称，也可以用于指年轻人，「孺子可教」就是说这个年轻人值得教诲。《史记．卷五五．留侯世家》中记载，张良原是战国时韩国贵族，韩国被秦国灭了之后，他想为国家报仇，于是请了一位大力士与他一起刺杀秦始皇，但是没有成功，因此而被通缉，只好隐姓埋名到下邳避难。有一天，张良到桥上散步，有一位穿著褐衣的老人，到张良面前就故意把鞋子掉到桥下，并且很不客气地对张良说：「小伙子，下去替我捡鞋！」张良非常惊讶，想上前揍他一顿。但看他年纪大，就勉强忍耐下来，到桥下替他捡鞋。捡上来后，老人又说：「帮我穿上！」张良百般不情愿，但心想好人就做到底吧，便跪著帮他穿鞋。老人伸脚穿鞋后，笑著离开，张良大吃一惊，目送他远去。老人走了一里路又回来说：「孺子可教啊！五日后天亮时来这里和我踫面。」老人后来又连续测验张良多次，确定他能忍人所不能忍，是个不可多得的人才后，便送给他一本《太公兵法》，相传是姜太公辅佐周武王伐纣后所著的兵书，要他仔细研读，将来可为王者师。后来，张良果真利用这本书中的兵法，帮助汉高祖刘邦打天下，建立了汉朝。「孺子可教」后来就被用来称许可以教诲栽培的年轻人。"},
  {"name": "水滴石穿", "cid": 303878, "pid": 12221582, "num": 78, "meaning": "滴水久了可使石穿。比喻持之以恒，事必有成。语本《尸子》。后亦用「水滴石穿」比喻小问题日积月累也会成为大问题。\n△「绳锯木断」", "source": "《尸子》（据《太平御览．卷七六三．器物部．锯》引）", "example": "各位看簷下这块石板都被雨水滴出洞来了，真是水滴石穿的最佳印证。", "story": "尸子，名佼，春秋末年时候的思想家。曾为商鞅的门下客，后来商鞅遭车裂，尸子避祸入蜀，终老一生。《尸子》一书原有二十篇，学说综合儒、墨、名、法四家，后来全书散佚，今本只剩十二篇。《尸子》书中提到：「水，虽然不是钻石头的钻子，但是可以把石头滴穿；绳子，虽然不是用来锯木头的锯子，但是只要不停的在木头上来回磨擦，同样可以把木头切断。」这是长时间累积下来的结果。后来「水滴石穿」这句成语就从这里演变而出，用来比喻持之以恒，事必有成。但也可用来比喻小问题日积月累也会成为大问题。例如在宋．罗大经《鹤林玉露》中记载一个故事：张乖崖当崇阳令时，因为发现管理府库的官吏夹带一文钱出来，于是判处杖刑，但是他不服，张乖崖就提笔写下判例：「虽然每天只偷一文钱，但一千天之后就有一千文钱，日积月累就会变成为数可观的一笔钱，就像用绳子磨擦木头久了也会断，水不间断的滴在石头上也会有穿透的一天。」"},
  {"name": "温故知新", "cid": 303878, "pid": 12221581, "num": 79, "meaning": "复习学过的课业，而能领悟出新的道理。语出《论语．为政》。", "source": "《论语．为政》", "example": "做学问应该反复熟读，才能温故知新，日益精进。", "story": "温，温习；故，旧的。「温故知新」就是温习过去所学，从中获得新的知识和体会。在《论语．为政》中记载了孔子说的一句话：「温故而知新，可以为师矣。」意思是说：「如果能常常复习以往学过的课业，而能从中领悟出新的道理，这样就可以为人师表了。」后来「温故知新」这句成语就从这里演变而出，用来说明反复学习的功效。"},
  {"name": "循序渐进", "cid": 303878, "pid": 12221580, "num": 80, "meaning": "按照一定的次序与步骤逐渐推进。语本唐．韩愈〈答窦秀才书〉。\n△「按部就班」", "source": "唐．韩愈〈答窦秀才书〉（据《全唐文．卷五五一．韩愈》引）", "example": "学习数学一定要由浅而深，循序渐进，千万不可躁进。", "story": "「循序渐进」原作「循次而进」，见于唐代文人韩愈的〈答窦秀才书〉。韩愈在给窦秀才的信中说道：你是个青年才俊，文采丰富，意气风发。凭著如此优越的条件，当朝廷广招人才时，应该可以获得一官半职，即使未遇良好机缘，「循次而进，亦不失万一于甲科」。也就是说，即使这样平平稳稳，一步一步地来，至少登进士第是没问题的。后来「循序渐进」这个成语就从这里演变而出，用来指按照一定的次序与步骤逐渐推进。宋代大儒朱熹〈答邵叔义书〉一文中谈到作学问的方法时便曾说道：「读书穷理，积其精诚，循序渐进，然后可得，决非一旦慨然永叹，而躐等坐驰之所能至也。」意思就是说：作学问必须靠诚心诚意，一点一滴地累积，逐渐地深入推进，绝对不能想要一下子就成功。"},
  {"name": "一鸣惊人", "cid": 303878, "pid": 12221579, "num": 81, "meaning": "一出声就令人吃惊。比喻平时默默无闻，而后却突然有惊人的表现。＃典出《韩非子．喻老》。", "source": "＃《韩非子．喻老》", "example": "他果然具有实力，首次公演便一鸣惊人。", "story": "据《韩非子．喻老》载，春秋时楚庄王虽然已经即位三年，但是却看不到他积极处理国事，因此大臣们都非常担忧。有一天右司马打了个比方对庄王说：「有一只大鸟，栖息在南面的山丘上，三年之中，不但没有拍动翅膀，甚至不飞也不叫，静得连一点声音都没有，这是什么鸟啊？」楚庄王说：「那可不是只平凡的鸟，他虽然不飞，要飞一定冲上高空；目前虽然没叫，要叫一定震惊天下，你宽心吧，我明白你的意思。」过了半年，楚庄王亲自处理政事，对于不合理的事项加以废除，另外又制定出法令规章，同时诛杀了五个大臣，提拔六个处士，把楚国治理得非常强盛，而楚庄王也成为春秋五霸之一。后来这个故事被浓缩成「一鸣惊人」，用来比喻平时没没无闻，突然有惊人的表现。"},
  {"name": "百发百中", "cid": 303878, "pid": 12221578, "num": 82, "meaning": "每发一箭，都能射中。形容射击技术高超，绝无虚发。＃语出《战国策．西周策》。后亦用「百发百中」形容技术高妙，能命中目标。或形容料事、用计、施药等相当准确。\n△「百步穿杨」、「前功尽弃」", "source": "＃《战国策．西周策》", "example": "只见他反身跳投，又进了，真是百发百中！", "story": "据《战国策．西周策》载，苏厉是战国时谋士。有一次，他听说秦国大将白起即将带兵攻打魏国都城大梁，就对周王说：「白起曾经打败了韩、魏、赵等国，并且杀害魏国将领，攻占了许多土地。现在他又要出兵攻打大梁，大梁一旦被攻下，周王室就会面临危险，您应该想办法阻止。」于是建议周王派人前往秦国去对白起说：「以前楚国有一个名叫养由基的人，善于射箭。在距离柳树一百步的地方射击，射出一百支箭，每一箭都能射中柳叶，一旁观看的人都夸赞射得很好。但是有一个路过的人，却说：『的确射得很好，但是可以再教导他射箭的方法。』养由基听了，就说：『大家都说我射得很好，你却说可以教导我，那你为何不代替我射那柳叶呢？』那个人说：『我不能教导你伸左臂、屈右臂的射箭本领，但是你今天射柳叶百发百中，却不善于休息，等一下疲倦了，一箭也射不中，就会前功尽弃。』就像你现在打败了许多国家，取得许多土地，功劳很大。又即将要出兵经过周王室的所在地去攻打魏国，如果这一仗不能取得胜利，就会前功尽弃了。所以你还是假装生病，不要出兵的好。」后来《战国策》原文的「百发百中」成为一句成语，用来形容射击技术高超，绝无虚发；或形容料事、用计、施药等相当准确。"},
  {"name": "马首是瞻", "cid": 303878, "pid": 12221577, "num": 83, "meaning": "瞻，看。「马首是瞻」指士兵依据主将的马头来决定前进的方向，比喻服从指挥或跟随他人进退。语出《左传．襄公十四年》。\n△「塞井夷灶」", "source": "《左传．襄公十四年》", "example": "这个企划案是你提出，我们就以你马首是瞻，全力配合。", "story": "《左传》里记载鲁襄公十四年时，晋国会同鲁、齐、宋、郑等国军队伐秦，要报三年前栎地一战之仇。联军到了泾水边就停住了，不肯渡河。晋国大夫叔向去找鲁将叔孙穆子商量该怎么办，叔孙穆子便引了《诗经》的话：「匏有苦叶，济有深涉，深则厉，浅则揭。」意思是匏瓜也有苦叶，渡河也会遇到深的地方。水深的话就直接下水渡河，水浅的话就撩起衣服过去。要联军渡过泾水，继续朝秦国进攻。叔向听了，就回去准备船只渡河。秦国看联军集中在泾水边，派人在泾水上游下毒，因此而毒死了不少联军士兵。郑国军队的首领子𫊸非常生气，率先出兵和秦军交战，各国军队也跟著开打，但开战好一段时间都攻不下来。这时，晋国中军将领荀偃下令说：「我们等天一亮，鸡一叫就出征，做好填井毁灶的善后工作，然后跟著我的马行动，我的马头朝向哪里，你们就跟著哪个方向走。」下军的将领栾黡一向和荀偃处不来，听了荀偃的话不服气地说：「晋国从没有人下这种命令，我偏要把马头向东回国。」栾黡说完把马头一调就走，他的部下也跟著撤兵。荀偃看到这种情况，很后悔下了这道命令，造成自家军队的分裂，心想这样非但不能打胜仗，还可能会败北，只好下令撤军回国，结束了这场战争。荀偃这道命令中，有「马首是瞻」四个字，就是要晋军跟著他的马头方向前进。后来「马首是瞻」被用来比喻服从指挥或跟随他人进退。"},
  {"name": "下笔成章", "cid": 303878, "pid": 12221576, "num": 84, "meaning": "一挥笔即写成文章。比喻才思敏捷，且具文采。语出《三国志．卷一九．魏书．任城陈萧王传．陈思王植》△「一气呵成」、「一挥而就」、「援笔立成」", "source": "《三国志．卷一九．魏书．任城陈萧王传．陈思王植》", "example": "你要能多记些佳句成语，自然下笔成章。", "story": "据《三国志．卷一九．魏书．任城陈萧王传．陈思王植》载：曹植是曹操的第三个儿子，从小聪颖好学，十多岁时，就已经读了数十万字的诗辞歌赋等各类文章，培养出极丰富的文采。有一次太祖曹操看了曹植的文章，曾怀疑地问：「你是找谁帮忙写的啊？」曹植跪下而恭敬地回答：「我自己能出口成论，下笔成章，何须找人代笔？您不信的话，可以当面测试啊！」那时恰巧曹操兴建的铜爵台刚完工，他就带著几个儿子登上高台，并要他们各作一篇赋。曹植拿起笔来，瞬间就完成了一篇令人激赏的佳作，让曹操惊讶不已，不得不相信他这个儿子确实有「下笔成章」的奇能。后来「下笔成章」就用来比喻才思敏捷，且具文采。"},
  {"name": "偃旗息鼓", "cid": 303878, "pid": 12221575, "num": 85, "meaning": "军队放倒旌旗，停止战鼓。形容不露行踪。语出《云别传》。后亦用「偃旗息鼓」比喻事情中断或声势减弱。_x000D_\n△「偃兵息甲」、「鸣金收兵」", "source": "《云别传》（据《三国志．卷三六．蜀书．关张马黄赵传．赵云》裴松之注引）", "example": "此行既是偷袭，当然得偃旗息鼓，隐密行踪。", "story": "赵云是三国蜀汉的一员大将，不但骁勇善战，也擅长用计取胜。据《云别传》（《三国志》赵云本传裴松之注引）载，有一次刘备和曹操争战，曹操将军队屯驻在汉水的北山之下，黄忠和赵云前往劫粮草。黄忠的部队在途中被曹军包围，赵云便率兵来支援，打退了曹操的军队。曹操心有不甘，重整军队继续追击。赵云回到营地后，沔阳长张翼看见曹军逐渐逼近，想要关上营寨的大门，坚守阵地。赵云却下令敞开营门，放倒军旗，停止战鼓，故布疑阵。曹操看到蜀军阵地一片死寂，毫无动静，怀疑赵云已经设下埋伏，不敢轻举妄动，于是急忙退兵。这时赵云下令战鼓齐鸣，万箭齐放。曹军遭到这突来的伏击，顿时大乱，纷纷逃命，混乱中自相践踏和跌入汉水而死的士兵不计其数。后来这段故事中的「偃旗息鼓」演变成一句成语，除了原有意思外，也用来比喻事情中断或声势减弱。"},
  {"name": "管鲍之交", "cid": 303878, "pid": 12221574, "num": 86, "meaning": "春秋时，齐人管仲和鲍叔牙相知最深。后常比喻交情深厚的朋友。", "source": "西汉・司马迁《史记・管仲传》：“生我者父母，知我者鲍子也。”", "example": "他俩从小一起长大，真是管鲍之交。", "story": "春秋时管仲与鲍叔牙是好友。管仲家贫，两人做生意他多分利润，鲍叔牙不以为他贪；管仲三次做官被罢免，鲍叔牙不以为他愚。后来管仲感叹：'生我者父母，知我者鲍子也。'后用'管鲍之交'比喻深厚知心的友谊。"},
  {"name": "百尺竿头", "cid": 303878, "pid": 12221573, "num": 87, "meaning": "桅杆或杂技长竿的顶端。比喻极高的官位和功名，或学问、事业有很高的成就", "source": "唐・吴融《商人》诗：“百尺竿头五两斜，此生何处不为家。”", "example": "", "story": "宋朝时，长沙有位高僧名叫景岑，号招贤大师。这位太师佛学造诣高深，时常到各地去传道讲经。一天，招贤大师应邀到一座佛寺的法堂上讲经。前来听讲的僧人很多，大师讲得深入浅出，娓娓动听，听的人深受感染。法堂内除了大师的声音外，一片寂静。招贤大师讲经完毕后，一名僧人站立起来，问他行了一个礼，然后提了几个问题，请求大师解答。大师还了礼，慢慢地作答起来。 那僧人听到不懂处，又向大师提问，于是两人一问一答，气氛亲切自然。 听讲的人发现，他俩谈论的是有关佛教的最高境界----十方世界的内容。"},
  {"name": "劳而无功", "cid": 303878, "pid": 12221572, "num": 88, "meaning": "花费了力气，却没有收到成效。", "source": "先秦・管仲《管子・形势》：“与不可，强不能，告不知，谓之劳而无功。”", "example": "不注意科学，一味地蛮干，结果必定是～。", "story": "庄子讲，有人用尽力气去推磨盘、汲井水，却不得其法，白白辛苦。他又说有些事方向错了，越是努力越糟，这便是'劳而无功'。这个成语比喻花费力气却得不到成效，提醒我们做事要讲究方法。"},
  {"name": "分崩离析", "cid": 303878, "pid": 12221571, "num": 89, "meaning": "形容国家或集团的分裂瓦解。语出《论语．季氏》。_x000D_\n△「土崩瓦解」、「祸起萧墙」", "source": "《论语．季氏》", "example": "人民用民主力量让专权体制分崩离析。", "story": "孔子是春秋的贤人，于鲁国从政时，鲁国大治。后因政治理念与国君不合，周游列国十三年，却未受到其他国君的重用。晚年返回鲁国，致力于古代典籍的整理。孔子秉持「有教无类」的精神，开平民教育的先河，门下有弟子三千人。孔门后学记录孔子应答弟子、时人以及弟子间的问答之语，而成《论语》一书，其中可见孔子思想的脉络，以及他的治学方式。在〈季氏〉篇中记载，由于季氏要攻打颛臾，所以辅佐季氏的子路和冉求来请教孔子的意见。孔子回答：「一个国家如果财富平均，人民就不虞匮乏；如果上下和睦，人民就能安居乐业；国家之内没有祸乱，就不会倾覆。如果他国的人民不服，那就以德行感化他们，使他们来归。他们来归之后，就要使他们安定。如今你们两人辅佐季氏，不能德化他国的人民，邦国分裂瓦解，无法保全，反而要在国内动兵征伐。我怕季氏的忧患，不是远在颛臾，而是近在朝中啊！」后来「分崩离析」这句成语从原文中摘出，就用来形容国家或集团的分裂瓦解。"},
  {"name": "合浦还珠", "cid": 303878, "pid": 12221570, "num": 90, "meaning": "即「合浦珠还」。见「合浦珠还」条。01.元．王举之〈折桂令．簿书中暂驻行车曲〉：「赋温润荆山进玉，吐宫商合浦还珠。」02.明．谢觉《四喜记》第三六出：「合浦还珠喜不胜，小星恰合古人情。」", "source": "", "example": "", "story": "此处所列为「合浦珠还」之典故说明，提供参考。东汉时合浦郡内产珍珠，居民从海港中采集珍珠，以换取生活所需的米食为生。之前在此任职的官吏，大多贪污不法，将人民采集的珍珠，几乎据为己有，也因为滥采，珠蚌后来都迁移到别处。导致合浦郡再也没有生产珍珠，人民因此无法维持生活，于是，路上到处都可看见因为饥饿而死的人。后来孟尝到此任职，一改之前的弊端，推行教化，端正风俗，一年之后，珠蚌再度回来，合浦郡又恢复盛产珍珠了。后来这个故事被浓缩成「合浦珠还」，比喻物品失而复得，亦用于比喻人离开而复返。"},
  {"name": "爱屋及乌", "cid": 296891, "pid": 11701856, "num": 91, "meaning": "因爱一个人，连带地也爱护停留在他屋上的乌鸦。比喻爱一个人也连带地关爱与他有关的一切。＃语本《尚书大传．卷三．大战篇》。", "source": "＃《尚书大传．卷三．大战篇》", "example": "因为哥哥是杰出校友，老师爱屋及乌，对我也特别好。", "story": "商朝末年，武王讨伐暴虐的纣王，与纣王的军队大战于牧野（地约当今河南省淇县南），赢得胜利。纣王后来自杀，结束了商朝，而开启了周朝的天下。武王不知该如何对待殷商的遗民，就召集众大臣们商议。姜太公说：「我听说爱一个人，连他屋顶上的乌鸦都爱；而讨厌一个人，就连他家的围栏都讨厌。您觉得这样如何？」武王认为不好。召公说：「我觉得可以杀掉有罪的人，让无罪的人活下来，这样如何？」武王还是觉得不好。周公又说：「让他们继续过原本的生活，仍然住在原本的房子里，从事原本的工作，不要有太大的变化，并且多举用贤德之人，您觉得这样如何？」武王听了赞叹不已，认为只有这样广阔的胸襟才能平定天下，于是决定采用周公的意见。后来「爱屋及乌」这句成语，就从这里演变而出，比喻爱一个人也连带地关爱与他有关的一切。"},
  {"name": "安步当车", "cid": 296891, "pid": 11701857, "num": 92, "meaning": "悠闲安稳地走路，当作是乘车。比喻安贫乐贱。语出《战国策．齐策四》。后用「安步当车」形容态度悠闲从容。", "source": "《战国策．齐策四》", "example": "我收入虽然不多，但晚食当肉，安步当车，也不需要什么花费。", "story": "据《战国策．齐策四》载，战国时，齐宣王接见处士颜斶（ㄔㄨˋ），叫颜斶上前，颜斶却说：「大王您自个儿过来！」齐宣王听了很不高兴，底下的人赶紧跟他说：「大王是国君耶！你怎么叫大王过来？」颜斶说：「如果我上前去的话，不等于是巴结国君？但大王过来的话，就是接近、尊重士人，这样不是比较好吗？」齐宣王听了很生气地说：「到底是君王尊贵？还是士人尊贵？」颜斶说：「当然是士人尊贵！」齐宣王便问：「怎么说呢？举个例子。」颜斶便说：「从前秦国伐齐经过鲁国，下令不得毁坏贤士柳下惠墓方圆五十步内的一草一木，否则一律杀无赦。又下令说：能砍下齐王人头者，就能封万户侯赐给重赏。可见一国之君的人头，还不如死去贤士的坟墓。」齐宣王很不高兴，但又无法反驳，只好沉默不语。这时旁边的大臣都很紧张，对颜斶说：「你赶快上前去吧！大王是大国之君，天下的士人都来投效，四方的诸侯都莫敢不服，是多么尊贵！而世间的高士，都是住在乡野的『匹夫』而已，怎么可以跟君王比？」颜斶又反驳说：「当然不是！古代圣王都是有贤士的帮助才能建立功业，就是因为他们能尊重士人，不耻下问，诸侯还用『孤』、『寡』等自称，表示自己得不到臣民爱戴。之所以被称为明主，就是因为他们明白士人的尊贵，能够礼贤下士。」齐宣王听了他这番话，觉得很有道理，便表示要请他当国师，让他以后每天有美食可享用、有华车可以乘坐，连妻子都有漂亮的衣服穿，荣华富贵享用不尽。但是，颜斶却推辞了，宁愿回归乡里，过平淡的生活，并说自己可以「晚食以当肉，安步以当车」，意思就是没有肉吃的话，就把吃饭时间挪晚，等饿一点再吃，吃起饭来就会更香，当作是吃肉；没有车子坐，就悠闲安稳地走路，当作是乘车。他认为已经向君王进过忠言，就尽了人臣的义务，不需要再留在宫中，便向宣王拜别而去。古代贵族出行必乘车，故用「安步当车」来称人安贫乐贱，后亦用于形容人态度悠闲从容。"},
  {"name": "安然无恙", "cid": 296891, "pid": 11701858, "num": 93, "meaning": "恙，祸患、疾病。「安然无恙」指平安没有疾病、祸患等事故。语本《战国策．齐策四》。", "source": "《战国策．齐策四》", "example": "看到他安然无恙地回到家里，我们都松了一口气。", "story": "「恙」是传说中的一种啮虫。《风俗通义》上记载：「恙，噬人虫也，食人心。人每患苦之，故俗相劳问者云『无恙』，非为病也。」由于古人居住环境卫生较差，容易被恙咬伤，引发疾病，所以「恙」就成了疾病、灾祸的代名词。有小病的话，就称为「微恙」、「小恙」，没有病就是「无恙」。在《战国策．齐策四》记载了一个故事：有一次赵威后接见齐王派来的使者，还没有将国书拆开，赵威后就问齐国使者道︰「齐国今年的收成好吗？百姓们都好吗？齐王也好吗？」使者听了，很不高兴地说︰「我奉大王的命令出使贵国，威后您却先问收成和百姓，然后才问大王好不好，岂非尊卑颠倒了吗？」赵威后就回答说︰「你说的不对。如果没有好的收成，那百姓怎么能过好日子？如果没有百姓，哪里来的国君？难道你要我舍本问末吗？」此处《战国策》原文就用了「无恙」，可见「无恙」一语通行甚早。后来演变成「安然无恙」这个成语，用来表示平安没有疾病、祸患等事故。"},
  {"name": "按兵不动", "cid": 296891, "pid": 11701859, "num": 94, "meaning": "暂时停止军事行动，有观望形势的意思。＃语本《荀子．王制》。后用「按兵不动」形容暂时不采取行动。", "source": "＃《荀子．王制》*1*", "example": "上级早已把任务交下，为何过了几个月，你们还是按兵不动？", "story": "荀子，名况，战国时赵人。学说本于孔子，主张礼治而倡性恶之说。在〈王制〉篇中，主要阐述成就圣王的制度、管理天下的方法，以及导致国家兴亡的缘由，以供君王作为借镜。典源节录的这一段，荀子主张：国家富足强盛时，要采取中立的态度，不要为了合纵连横这类的外交事宜而有所偏私，并停止军事行动，在一旁等候观看那些残暴不仁的国家彼此争斗即可。后来「按兵不动」这句成语就从这里演变而出，用来形容暂时不采取行动。"},
  {"name": "八面威风", "cid": 296891, "pid": 11701860, "num": 95, "meaning": "各个方面都很威风。形容神气足，声势盛。", "source": "元・郑德辉《三战吕布》第三折：“托赖着真天子百灵咸助，大将军八面威风。”", "example": "年龄不到五十许，体态虽十分端丽，神情却八面威风。（清・曾朴《孽海花》第十二回）", "story": "元朝戏曲中有人写诗送别朋友：'风流况是文章手，八面威风气象雄。'形容人气度不凡、神气十足。也常见于描写大将出征，仪仗威武，四面八方都显出雄壮的气势。今天多形容人神气、有派头。"},
  {"name": "拔苗助长", "cid": 296891, "pid": 11701861, "num": 96, "meaning": "比喻违反事物发展的客观规律，急于求成，反而坏事。", "source": "郭沫若《雄鸡集・关于发展学术与文艺的问题》：“命令主义就合乎中国古代的一个寓言，叫做‘拔苗助长’。结果被拔起的苗不仅不能成长，反而枯槁了。”", "example": "那种不顾学生能否接受的填鸭式的教学方法，无异于～。", "story": "宋国有个农夫嫌禾苗长得太慢，就把每棵苗都往上拔高一点，累得满头大汗回家说'今天我帮助禾苗长高了'。他儿子跑去一看，禾苗全都枯死了。比喻违反规律、急于求成，反而把事情弄糟。"},
  {"name": "拔山举鼎", "cid": 296891, "pid": 11701862, "num": 97, "meaning": "形容力量超人或气势雄伟。", "source": "《秦并六国平话》卷下：“籍是时年方二十四，力敌万夫，有拔山举鼎之威。”", "example": "这位举重冠军力大如牛，真有拔山举鼎的气概。", "story": "西楚霸王项羽身高力大，能举起沉重的铜鼎。他在兵败前的《垓下歌》中唱道：'力拔山兮气盖世。'后来用'拔山举鼎'形容人力大无穷、气概豪迈，也泛指勇武过人。"},
  {"name": "拔帜易帜", "cid": 296891, "pid": 11701863, "num": 98, "meaning": "帜：旗帜；易：换。比喻推翻别人，自己占有。", "source": "西汉・司马迁《史记・淮阴候列传》：“赵见我走，必空壁逐我，若疾入赵壁，拔赵帜，立汉赤帜。”", "example": "如今这里已～，另换新主了。", "story": "汉将韩信攻赵，半夜派二千轻骑埋伏。天明佯败诱敌，赵军倾巢追击，汉军轻骑趁机冲入赵营，拔掉赵旗、换上汉旗。赵军回头见满营汉旗，以为老巢已失，顿时大乱。比喻取而代之。"},
  {"name": "白头如新", "cid": 296891, "pid": 11701864, "num": 99, "meaning": "白头：头发白了；新：新交。指交朋友彼此不能了解，时间虽久，仍跟刚认识一样。", "source": "西汉・司马迁《史记・鲁仲连邹阳列传》：“谚曰：‘有白头如新，倾盖如故。’何则？知与不知也。”", "example": "而八年之间，语言不接，吉凶不相问吊，反有～之嫌。（宋・陈亮《与应仲书》）", "story": "西汉时期，邹阳有一次因为受人诬陷，被梁孝王关进监牢，准备处死。邹阳十分激愤，他在狱中给梁孝王写了一封信，信中列举事实说明：“待人真诚就不会被人怀疑，纯粹是一句空话。”"},
  {"name": "百川归海", "cid": 296891, "pid": 11701865, "num": 100, "meaning": "川：江河。许多江河流入大海。比喻大势所趋或众望所归。也比喻许多分散的事物汇集到一个地方。", "source": "《淮南子·汜论训》", "example": "各地的游客像百川归海，涌向这座古城。", "story": "《淮南子》说：大大小小的河流，源头各不相同，最后都汇流入大海。这个成语比喻许多分散的事物最终归于同一处，也比喻人心所向、众望所归，提醒我们积少成多、殊途同归的道理。"},
  {"name": "百发百中", "cid": 296891, "pid": 11701866, "num": 101, "meaning": "每发一箭，都能射中。形容射击技术高超，绝无虚发。＃语出《战国策．西周策》。后亦用「百发百中」形容技术高妙，能命中目标。或形容料事、用计、施药等相当准确。\n△「百步穿杨」、「前功尽弃」", "source": "＃《战国策．西周策》", "example": "只见他反身跳投，又进了，真是百发百中！", "story": "据《战国策．西周策》载，苏厉是战国时谋士。有一次，他听说秦国大将白起即将带兵攻打魏国都城大梁，就对周王说：「白起曾经打败了韩、魏、赵等国，并且杀害魏国将领，攻占了许多土地。现在他又要出兵攻打大梁，大梁一旦被攻下，周王室就会面临危险，您应该想办法阻止。」于是建议周王派人前往秦国去对白起说：「以前楚国有一个名叫养由基的人，善于射箭。在距离柳树一百步的地方射击，射出一百支箭，每一箭都能射中柳叶，一旁观看的人都夸赞射得很好。但是有一个路过的人，却说：『的确射得很好，但是可以再教导他射箭的方法。』养由基听了，就说：『大家都说我射得很好，你却说可以教导我，那你为何不代替我射那柳叶呢？』那个人说：『我不能教导你伸左臂、屈右臂的射箭本领，但是你今天射柳叶百发百中，却不善于休息，等一下疲倦了，一箭也射不中，就会前功尽弃。』就像你现在打败了许多国家，取得许多土地，功劳很大。又即将要出兵经过周王室的所在地去攻打魏国，如果这一仗不能取得胜利，就会前功尽弃了。所以你还是假装生病，不要出兵的好。」后来《战国策》原文的「百发百中」成为一句成语，用来形容射击技术高超，绝无虚发；或形容料事、用计、施药等相当准确。"},
  {"name": "百感交集", "cid": 296891, "pid": 11701867, "num": 102, "meaning": "感：感想；交：同时发生。各种感触交织在一起。形容感触很多，心情复杂。", "source": "宋・陈亮《龙川集・祭喻夏卿文》：“泪涕横腮，非以邂逅。百感交集，微我有咎。”", "example": "我是上一个世纪出生的人，能参加这样的盛会，～，思绪万千。（郭沫若《科学的春天》）", "story": "西晋时期，统治集团内部矛盾重重。持续十六年之久的“八王之乱”给国家和人民造成了深重的灾难。北方的匈奴贵族刘裕乘机起兵入侵。晋怀帝永嘉三年（公元309年），匈奴军队两次长驱直入，一直打到西晋都城洛阳，但都被西晋军队击退。"},
  {"name": "百闻不如一见", "cid": 296891, "pid": 11701868, "num": 103, "meaning": "听别人述说千百遍，不如亲眼看一次来得真确。语出《汉书．卷六九．赵充国辛庆忌传．赵充国》。\n△「闻之不若见之」", "source": "《汉书．卷六九．赵充国辛庆忌传．赵充国》", "example": "早就听说大峡谷的美景，百闻不如一见，这次美西之行使我开了眼界。", "story": "「百闻不如一见」这句成语的意思是听别人述说千百遍，不如亲眼看一次来得真确。典源出自《汉书．卷六九．赵充国辛庆忌传．赵充国》。赵充国是武帝时破匈奴的大将军。宣帝时羌人入侵边疆，攻城夺地，杀害吏民。宣帝召集群臣计议，赵充国自告奋勇，表示愿意带兵抗敌。宣帝问他需要带多少兵马，赵充国说：「百闻不如一见。军情在遥远的地方是很难揣测的，我愿意亲自到西北边境去看看，然后拟好作战计划，再向陛下报告。」赵充国到了边境仔细考察后，拟定了驻兵屯守，整治边境，分化羌人的策略，不久西北边境终于安定。"},
  {"name": "百丈竿头", "cid": 296891, "pid": 11701869, "num": 104, "meaning": "佛教语，百丈高的竿子，比喻道行达到很高境界", "source": "宋・释道原《景德传灯录・景岑禅师》：“百丈竿头须进步，十方世界是全身。”", "example": "", "story": "宋朝时，长沙有位高僧名叫景岑，号招贤大师。这位太师佛学造诣高深，时常到各地去传道讲经。"},
  {"name": "百折不挠", "cid": 296891, "pid": 11701870, "num": 105, "meaning": "意志刚强，即使受到很多挫折，仍不屈服。语出汉．蔡邕〈太尉桥公碑〉。_x000D_\n△「不屈不挠」", "source": "汉．蔡邕〈太尉乔玄碑〉（据《汉魏六朝百三家集》卷一九引）", "example": "要登世界高峰，得有百折不挠的毅力。", "story": "东汉的桥玄是一位性情刚正，嫉恶如仇的人。他曾揭发陈国相羊昌的恶行，将贪赃枉法的部属上邽令皇甫祯处死，并上书灵帝弹劾太中大夫盖升搜刮民财的罪行。有一次他的小儿子被一群强盗绑架，借此勒索。守备阳球得到消息立刻派出官兵救援，虽然他们将强盗团团围住，但是因为害怕强盗伤害桥玄的儿子，不敢有进一步的行动。桥玄知道了，非常生气地说：「强盗目无法纪，怎么可以为了我的儿子而纵放呢？」于是催促官兵赶快动手。后来强盗被逮捕了，但他的小儿子也被强盗杀害。由于桥玄敢于挺身与恶势力对抗，极受当时的人敬重，后来蔡邕为他写碑，称赞他「有百折不挠、临大节而不可夺之风」。这里的「百折不挠」，演变成一句成语，用来比喻人的意志刚强，即使受到许多挫折，仍不屈服。"},
  {"name": "班门弄斧", "cid": 296891, "pid": 11701871, "num": 106, "meaning": "班，鲁班，古代巧匠。「班门弄斧」指在巧匠鲁班门前玩弄大斧。比喻在行家面前卖弄本事，不自量力。\n＃语本唐．柳宗元〈王氏伯仲唱和诗序〉。", "source": "＃唐．柳宗元〈王氏伯仲唱和诗序〉（据《全唐文．卷五七七．柳宗元》引）*1*", "example": "他可是大名家，你别班门弄斧了。", "story": "唐代大文学家柳宗元的朋友王纬兄弟，出身于书香世家，富有文采。两人前来京师为文，柳宗元为他们的唱和诗作写序，赞美他们有如三国时的应璩、应玚及南朝时陆机、陆云两对兄弟，写出音律玄妙、内容精美的诗句，并自认所写的序文是在行家面前献丑，有如在善于工艺的鲁班、郢匠前耍弄斧头。后来「班门弄斧」这句成语就从这里演变而出，用来比喻在行家面前卖弄本事，不自量力。"},
  {"name": "半部论语", "cid": 296891, "pid": 11701872, "num": 107, "meaning": "旧时对儒学经典之一《论语》的夸赞之辞，掌握半部《论语》，人的能力就会提高，就能治理国家。", "source": "宋・罗大经《鹤林玉露》第七卷：“臣平生所知，诚不出此，昔以其半辅太祖定天下，今欲以其半辅陛下致太平。’", "example": "况且从前古人以～治天下，就是半部亦何妨。（清・李宝嘉《官场现形记》第六十四回）", "story": "北宋宰相赵普自称靠半部《论语》帮宋太祖平定天下，另半部帮宋太宗把国家治理太平。他读书不多，却善于用《论语》中的道理来治国。后人用'半部论语'或'半部《论语》治天下'指儒家经典足以安邦。"},
  {"name": "半途而废", "cid": 296891, "pid": 11701873, "num": 108, "meaning": "「半途而废」之「途」，典源作「涂」。事情没做成功就停止。比喻做事情有始无终。语本《礼记．中庸》。\n△「中道而废」", "source": "《礼记．中庸》", "example": "一个人做事情老是半途而废，怎能有成？", "story": "「半途而废」原作「半涂而废」。「半途」是半路的意思，即「中道」、「中途」，「半途而废」是指半路就停下来而不再前进，整句成语引申为事情没能持续下去就停止的意思。这个成语出自《礼记．中庸》，孔子认为君子遵循正道而行，假如半途而废，而他是绝不能中途停止的。充分显露出对圣人德行的向慕。「半途而废」就用来比喻做事情有始无终。"},
  {"name": "包藏祸心", "cid": 296891, "pid": 11701874, "num": 109, "meaning": "怀藏诡计，图谋害人。语出《左传．昭公元年》。\n△「居心叵测」", "source": "《左传．昭公元年》", "example": "可恶的叛贼，竟包藏祸心，谋我江山！", "story": "据《左传．昭公元年》载，春秋时期，郑国是个小国，想和大国楚国保持良好关系，于是郑国大夫公孙段便将女儿许配给楚国公子围。但楚国其实想利用这个机会进入郑国首都，把郑国灭掉，所以当天公子围率领一大队楚国士兵前往。郑国大夫子产觉得情况不对，便派子羽前去阻止楚国进城，子羽说：「我们的城池太小了，容不下那么多人，就在城外举行婚礼吧！」但楚人以为如此不合礼法，坚持要进城。子羽只好直接了当地说：「我们国家狭小并不是罪过，但若依赖大国而一点防范之心都没有，那就是罪过了。我们本来希望联姻后，可以靠大国的力量安定自己，你们恐怕只是包藏祸心，前来算计我们吧！」楚人知道他们的诡计早被看穿，只好放弃原有的计划，但为了保持颜面，仍坚持进城迎娶，答应不携带武器，郑国这才放行。后来子羽话中的「包藏祸心」演变为成语，就用来比喻怀藏诡计，图谋害人。"},
  {"name": "抱薪救火", "cid": 296891, "pid": 11701875, "num": 110, "meaning": "抱著木柴去救火，比喻处理事情的方法错误，既无法达成目的，反而情势更为恶劣。比喻用错方法，而致祸害加深。＃语出《战国策．魏策三》。_x000D_\n△「泼油救火」", "source": "＃《战国策．魏策三》*1*", "example": "对方需索无度，如果一味应了他，那我们岂不是在抱薪救火？", "story": "据《战国策．魏策三》记载：战国时期，七雄各自称霸一方。后秦孝公因重用商鞅，变法图治，国势转为强大。秦王一直想将其他六国并吞，统一天下，所以不断地向各国出兵征伐。魏国在华阳之战被秦军打败，魏国派段干子为代表，打算割地与秦国讲和。但是孙臣认为不妥，对魏王说：「那些臣子怂恿您割地给秦国，是要用割地的方式讨好秦国，不要入侵魏国。但这个作法对贪婪的秦国是行不通的。拿土地去讨好秦国，就有如抱著木柴去救火，木柴没烧光前，火是不会熄灭的。您的土地有限，秦国的欲望却无限，总有一天魏国的土地会被秦国并吞的。」魏王虽然觉得孙臣说的很有道理，但还是担心秦国不悦，仍旧割地讨好秦国，最后终于还是被秦国并吞了。后来「抱薪救火」从原文中的「抱薪而救火也」演变而出，用来比喻用错方法，而致祸害加深。"},
  {"name": "杯弓蛇影", "cid": 296891, "pid": 11701876, "num": 111, "meaning": "将酒杯里的弓影，误以为是蛇，以致喝下后心生疑惧。＃典出汉．应劭《风俗通义．卷九．世间多有见怪惊怖以自伤者》。后用「杯弓蛇影」比喻为不存在的事情枉自惊扰。_x000D_\n△「风声鹤唳」、「草木皆兵」", "source": "＃汉．应劭《风俗通义．卷九．世间多有见怪惊怖以自伤者》*1*", "example": "你别吓他，小心他杯弓蛇影会真以为喝了脏水。", "story": "东汉时，有一年的夏至，应郴（ㄔㄣ）请下属杜宣喝酒。悬挂在北壁上的弓正好投映在酒杯里，看起来就像是酒杯里有条蛇。杜宣勉强喝下后，便感到肚子不适。回家后，食欲不振，身体日渐瘦弱，怎么都医治不好。后来应郴来探视，便问他身体不适的原因，杜宣说是那天喝下酒杯里的蛇所造成的结果。应郴回官府后，想了又想，一回头看见了壁上的弓，这才发现杜宣所说的蛇，原来是弓投映在酒杯里的影子。于是应郴再度请杜宣到府里喝酒，并让杜宣坐在当初的位子上，同时向他证明了杯里的蛇只是墙壁上的弓影，而杜宣的病也因此不药而愈。后来这个故事被浓缩成「杯弓蛇影」，用来比喻为不存在的事情枉自惊疑恐惧。"},
  {"name": "背水一战", "cid": 296891, "pid": 11701878, "num": 112, "meaning": "「背水一战」的「背水」，就是背对著河流，毫无退路的意思。「背水一战」比喻抱著必死的决心，奋战取胜。※语或本《尉缭子．天官》。\n△「孤注一掷」、「破釜沉舟」", "source": "※《尉缭子．天官》", "example": "同志们！我们已无退路，准备背水一战吧！", "story": "「背水一战」原作「背水陈」。战国时，梁惠王问尉缭子说：「我听说黄帝有刑德之说，靠它可以百战百胜，有这回事吗？」尉缭子说：「不是这样的，黄帝的刑德之说，是指用武力讨伐敌人，用文德治理天下，和国君所要追求的流年方位无关。假设今天有一座城池，用什么方法都攻不下来，如果按阴阳五行，难道没有任何吉时是适宜攻城的吗？其实这座城会无法攻破，完全是因为它的防护坚固，城内兵器完备，粮食物资充足，又有豪杰之人同心协力的固守。如果不是这样，城就很容易攻下了。这样看来，要找良辰吉日不如多花心思在行动策略上。《天官》中曾说：『背靠著水部阵，等于是把部队置于死地；面对著山坡摆阵，简直是自废兵力。』但想当初武王伐纣时，就是背著济水、面对牧野山坡列阵，以二万多人的兵力，去迎战纣王的数十万大军，那纣王不是得了《天官》书中的阵式之利，必胜无疑吗？但是后来武王仍然打赢这场仗，灭了商朝。所以能百战百胜并不在于选对良辰吉日，而完全是人的努力。」这里提到了「背水陈」，也就是「背水布阵」的意思，可能就是后来「背水一战」这句成语的出处，用来比喻抱著必死的决心，奋战取胜。"},
  {"name": "毕恭毕敬", "cid": 296891, "pid": 11701879, "num": 113, "meaning": "形容十分恭敬的样子", "source": "郭沫若《洪波曲》第十章五：“军长为李玉堂，一山东大汉，抵军部时，在门外相迎，毕恭毕敬。”", "example": "他～地将书递给了老师，请求解答两个疑难问题。", "story": "西周周幽王十分昏庸暴虐，十分宠爱褒国进献的美女褒姒，想尽千方百计并不惜一切代价地让褒姒一笑，对外得罪各路诸侯，废除原太子宜臼立褒姒的儿子伯服为太子。尽管如此，宜臼写《小弁》诗抒发对父母必恭必敬的心情。"},
  {"name": "标新立异", "cid": 296891, "pid": 11701880, "num": 114, "meaning": "新的独到见解，与诸家立论不同。◎语本南朝宋．刘义庆《世说新语．文学》。后用「标新立异」形容创立新奇的名目或主张，以表示与众不同。\n△「立奇造异」、「独树一帜」", "source": "南朝宋．刘义庆《世说新语．文学》\n南朝宋．刘义庆《世说新语．文学》", "example": "设计海报就是要讲究另类，标新立异。", "story": "《庄子》一书是战国时庄周所撰。晋代的向秀曾经替《庄子》作注，可惜还没完成就死了，郭象接替他完成注释的工作。同时期也有很多著名学者研究〈逍遥游〉，但没有人的见解可以超越他们，直到支道林的出现。根据《世说新语．文学》记载，支道林曾经和冯怀在白马寺谈天，席中聊到《庄子．逍遥游》。支道林对〈逍遥游〉这篇的见解新奇独到，不但「标新理」而且「立异义」，不仅超越了向秀和郭象两人，更是那些著名学者探索追求不及的。同样在《世说新语．文学》中另有一篇则载，孙兴公对王羲之称赞支道林说：「支道林拔新领异，胸怀所及，乃自佳。」王羲之刚开始不以为，待亲耳听闻支道林论〈逍遥游〉，果然一听就不想离开。《世说新语》这两篇原文中的「标新理」、「立异义」，及「拔新领异」，后来演变成「标新立异」这句成语，用来形容创立新奇的名目或主张，以表示与众不同。"},
  {"name": "别开生面", "cid": 296891, "pid": 11701881, "num": 115, "meaning": "原指重新描绘旧画像，而使原已褪色的面貌变得鲜明、生动。语本唐．杜甫〈丹青引赠曹将军霸〉诗。后用「别开生面」比喻另外开创新的局面、风格、形式。", "source": "唐．杜甫〈丹青引赠曹将军霸〉诗（据《全唐诗．卷二二〇．杜甫》引）", "example": "这幅画真是别开生面，另有一番新意。", "story": "丹青，原指绘画时所用的颜料，在这里代指绘画。引，一种乐府诗的体裁。这首〈丹青引赠曹将军霸〉诗，写的是盛唐时期著名画家曹霸的一生传记。曹霸善于画马，亦工肖像，所作神采栩栩如生。开元年间，他受到唐玄宗的赏识，奉命重新描绘凌烟阁里的功臣肖像，果真一下笔便使原本已经褪色的面貌变得鲜明、生动。后来「别开生面」这句成语，就从诗中「下笔开生面」演变而出，用来比喻另外开创新的局面、风格、形式。"},
  {"name": "别无长物", "cid": 296891, "pid": 11701882, "num": 116, "meaning": "没有其他多余物品。见「身无长物」条。01.《二刻拍案惊奇》卷三九：「其家乃是个贫人，房内止有一张大几，四下一看，别无长物。」02.《老残游记．二编．第五回》：「德夫人走到他屋里看看，原来不过一张炕。一个书桌，一架书而已，别无长物。」", "source": "", "example": "", "story": "此处所列为「身无长物」之典故说明，提供参考。南朝宋．刘义庆的《世说新语．德行》中记载东晋大将军王恭的清廉俭朴。有一天王恭从会稽回来，王忱前去探望他。见他坐在一片竹席上，心想他刚从东方回来，一定有很多这种当地的特产，因此跟他要一条。王恭当下不置可否，等王忱走了以后，才将自己坐的这条竹席拿起来派人送去。没有竹席可坐了，王恭只好坐在草垫上。王忱后来听到这件事十分惊讶，对王恭说：「我是以为你有多的，所以才向你要。」王恭说：「您不了解我，我是作人无长物。」「长物」是指没有多余的物品，王恭一生清廉俭朴，即使做到大将军仍然没有多余的物品可用。后世便用「身无长物」表示身边没有任何多余的物品，比喻节俭或贫困。"},
  {"name": "别有天地", "cid": 296891, "pid": 11701883, "num": 117, "meaning": "形容风景秀丽，引人入胜。＃语出唐．李白〈山中问答〉诗。 后亦用「别有天地」指另有一番境界。\n△「别有洞天」", "source": "＃唐．李白〈山中问答〉诗（据《全唐诗．卷一七八．李白》引）*1*", "example": "沿溪而下，尽头竟有一个美丽的湖泊，湖面碧波粼粼，别有天地。", "story": "「天地」，指境界、境地。在诗中，诗人被问到为什么在碧山伫足停留，诗人笑了笑没有回答，只觉得心中安静闲适，看著凋零的桃花顺著流水无声无息幽静逝去，这样秀丽的景象，引人入胜。后来「别有天地」被用来形容风景秀丽，引人入胜，亦用来指另有一番境界。如唐代牛僧孺《玄怪录．卷三．张左》记载：一日君曹觉得耳中有车马声，才躺到床上，就看到两个童子驾著牛车从他的耳中驶出，并自称来自兜玄国。君曹就问兜玄国在那？童子回答在他的耳内。君曹不信，于是童子让君曹看他的耳朵。一看，「乃别有天地」，另有一番境界。"},
  {"name": "博士买驴", "cid": 296891, "pid": 11701887, "num": 118, "meaning": "博士：古时官名。博士买了一头驴子，写了三纸契约，没有一个“驴”字。讥讽写文章长篇累牍而说不到点子上。", "source": "北齐・颜之推《颜氏家训・勉学》：“问一言辄酬数百，责其指归，或无要会。邺下谚云：‘博士买驴，书券三纸，未有驴字。’”", "example": "你写个通知啰嗦半天，真是博士买驴。", "story": "北齐时有个博士（学官）写买驴的契约，写了三大张纸，却还没写到一个'驴'字，尽是废话。颜之推记下此事，讽刺写文章啰嗦不得要领。后用'博士买驴'讥讽人写文章或说话离题万里、抓不住重点。"},
  {"name": "不逞之徒", "cid": 296891, "pid": 11701889, "num": 119, "meaning": "不逞：不得志，不如意；徒：人（含贬义）。因心怀不满而闹事捣乱的人。", "source": "先秦・左丘明《左传・襄公十年》：“司氏、堵氏、侯氏、子师氏皆丧田焉，故五族聚群不逞之人，因公子之徒以作乱。”", "example": "如有～假托民军，借端扰害治安，即为人民公敌。（蔡东藩、许廑父《民国通俗演义》第六十八回）", "story": "春秋时郑国大夫子西准备让不稳妥的人掌管城门钥匙，子产劝阻说：这样会聚集一批'不逞之徒'——就是那些心怀不满、胡作非为的人——来危害国家。后来'不逞之徒'就指那些心怀怨愤、违法捣乱的人。"},
  {"name": "不合时宜", "cid": 296891, "pid": 11701891, "num": 120, "meaning": "不符合时势趋尚。语出《汉书．卷一一．哀帝纪》。", "source": "《汉书．卷一一．哀帝纪》", "example": "填鸭式的教育方法，如今已不合时宜了。", "story": "西汉末年，由于国势衰弱、社会紊乱，加上成帝喜好鬼神之说，又无子嗣，因此宠信方士。其中一名方士甘忠可，揉合黄老道学与儒家谶纬之说，诈造《天官历》、《包元太平经》。因汉帝自认属火德，甘忠可便假托道教真人赤精子，说汉家逢天地之大终，当更受命于天，以致天下太平，永固汉室之统治。甘忠可后因干预朝政遭弹劾而被诛杀，但他的弟子夏贺良等人仍密传其道，他的方术仍然盛行于贵族间。成帝崩后，继位的哀帝也好此道。夏贺良等人仍以赤精子的名义，说汉室国运中衰，建议哀帝改元易号，并增加漏箭上的刻度，可永保国家的安定。哀帝接受了他的建议，下诏以建平二年为太初元将元年，改号为陈圣刘太平皇帝，漏刻以百二十为度。但二个月后，哀帝见毫无成效，又发了一道诏令，自承误信方士之言，做了些不符时势所宜的事，因此收回成命，并将夏贺良等人发监问斩。「不合时宜」就是直接摘自典源的一个成语，用于表示不符合时势趋尚。"},
  {"name": "不可多得", "cid": 296891, "pid": 11701893, "num": 121, "meaning": "形容非常稀少，很难得到（多指人才或稀有物品）。", "source": "东汉・孔融《荐祢衡表》：“若衡等辈，不可多得。”", "example": "这颗钻石真可以说是～的稀世珍宝。", "story": "东汉名士孔融向朝廷推荐才子祢衡，在推荐表中写道：像祢衡这样杰出的人才，世上'不可多得'。意思是极其稀少、很难找到。后人用这个成语形容人才或物品十分珍贵，很难再得到第二个。"},
  {"name": "不可救药", "cid": 296891, "pid": 11701895, "num": 122, "meaning": "病重无药可医治。比喻到了无法挽救的地步。语出《诗经．大雅．板》。", "source": "《诗经．大雅．板》", "example": "他这病来得好猛，一下子就被宣布不可救药了。", "story": "《诗经》是最早的诗歌总集。采集从周初至春秋中叶五百年间的歌谣作品和宗庙乐章，分为风、雅、颂三大类。雅又分大雅、小雅，〈大雅〉收诗三十一篇，多为王室贵族雅正的乐歌。〈大雅．板〉这首诗内容是假借劝告同事，事实上是用来劝戒君王。其中一段：「上天正为害无道，不要还沉迷在快乐中而不自知。我是很诚恳的，并不是因为年老头脑不清楚才对你们说这些话，而你们这些年轻小伙子却摆出一副骄傲的样子，还用戏弄调笑的态度来看待这件事。歹毒的坏事做多了，就像病得很重的人没有药可以救治。后来诗中的「不可救药」演变为成语，就用来比喻到了无法挽救的地步。"},
  {"name": "不可同日而语", "cid": 296891, "pid": 11701896, "num": 123, "meaning": "不能放在同一时间谈论。形容不能相提并论，不能相比。", "source": "西汉・刘向《战国策・赵策二》：“夫破人之与破于人也，岂可同日而言之哉？”", "example": "我们现在的生活和改革开放前相比，真是～。", "story": "战国时苏秦游说赵王，说赵国现在兵力强盛，与当初弱小的时候相比，'岂可同日而言之哉'——不能放在同一天来谈论。后来缩为'不可同日而语'，指两者差别极大，根本不能相提并论。"},
  {"name": "不伦不类", "cid": 296891, "pid": 11701898, "num": 124, "meaning": "「不伦不类」有两种解，一是不合道理、法式，二是不像样。语本唐．刘知几《史通．卷一六．杂说上》。后用「不伦不类」形容事物不成体统。_x000D_\n△「不三不四」", "source": "唐．刘知几《史通．卷一六．杂说上》", "example": "他听对方话说得不伦不类，就借口离开了。", "story": "《公羊传》是春秋三传之一，旧题为子夏弟子公羊高所撰，是专为解释孔子的《春秋》所作的，后世有许多学者为之注疏训诂，其中所记载的内容亦经常被文人加以引用讨论。在《春秋．昭公十九年》中有「许世子止弑其君实」这样的记载，当时许悼公得了疟疾，喝了太子许止所进的药之后就死了。关于这个「弑」字的解释，各家说法不一，有的人认为进药本是医官的职责，太子亲自进药必别有居心；另一派人则认为疟疾不是绝症，治疟疾的药也不会致人于死，太子所进的药必有问题，所以才说是太子弑父。而《公羊传》解释这段经文时，却认为孔子用「弑」字，是要讥讽太子许止没有尽到孝道，并且举出乐正子春事奉生病父亲的例子做为佐证。刘知几对此十分不以为然，他认为乐正子春的孝行足为楷模，许悼公死于政治谋杀也是事实，怎么会是因为太子许止没有乐正子春孝顺，就被冠以「弑君」的罪名呢？刘知几认为公羊高是为了彰显同是孔子门人的乐正子春的德行，所以扭曲事实加以解说，例子举得不对，罪名也定得太过牵强，没有达到原本彰显乐正子春孝行的用意，反而变得十分可笑。后来「不伦不类」这句成语，就从刘知几《史通》中的「编次不伦，比喻非类」演变成，用来形容事物不成体统。"},
  {"name": "残杯冷炙", "cid": 296891, "pid": 11701900, "num": 125, "meaning": "残：剩余；杯：指酒；炙：烤肉。指吃剩的饭菜。也比喻别人施舍的东西。", "source": "北齐・颜之推《颜氏家训・杂艺》：“唯不可令有称誉，见役勋贵，处之下坐，以取残杯冷炙之辱。”", "example": "做人不可攀结权贵，靠人施舍，以受～之辱。", "story": "北齐的文学家颜之推，学识渊博，他有一部《颜氏家训》传世，内容是以儒家的传统思想作为立身治家之道。这部著作，对后世不少学者为人处世也有很大的影响。"},
  {"name": "草船借箭", "cid": 296891, "pid": 11701902, "num": 126, "meaning": "运用智谋，凭借他人的人力或财力来达到自己的目的。", "source": "《三国演义》", "example": "他像草船借箭一样，借别人的力量完成了任务。", "story": "三国时周瑜要诸葛亮十天内造十万支箭，诸葛亮说只需三天。他趁大雾，用扎满草人的船驶近曹营，曹操看不清，放箭如雨，全射在草人上。诸葛亮轻松'借'得十万余箭。比喻善于利用条件、机智取胜。"},
  {"name": "草菅人命", "cid": 296891, "pid": 11701934, "num": 127, "meaning": "菅，一种多年生的野草。「草菅人命」比喻轻视人命，任意加以残害。＃语本《大戴礼记．保傅》。", "source": "＃《大戴礼记．保傅》", "example": "民主时代一切依法行事，岂可草菅人命？", "story": "贾谊是汉文帝时著名的文人，曾被派往长沙做长沙王的老师，后来又被召回京师，任命为梁怀王的老师。梁怀王刘揖是汉文帝的小儿子，汉文帝非常宠爱他，希望他能多读书，所以请贾谊来教导他。但是贾谊认为，除了教皇子读书外，最重要的是要教他做人的道理。他认为商朝、周朝之所以能长久立国，是因为所用来辅佐天子的，是相承的传统与制度，然而秦朝就不是这样了，他们所崇尚的是诡诈和刑罚，毫不注重谦虚和礼让。假使像赵高那样，教导胡亥的全是一些严刑酷法，那么所学到的不是砍头、割鼻子，就是诛杀三族的事情。所以胡亥今天才继位，明天就射杀人。对于尽忠进谏的臣子，认为他们是蓄意毁谤；对于有深谋远虑的臣子，认为他们在妖言惑众。所以把杀人的事当作像割野草一样。这难道是因为胡亥的天性本就邪恶吗？其实不然，而是当初教导他的人，没有教他走上正道，没有教导他处世为人的道理，才会导致这样的结果。后来「草菅人命」这句成语就从这段故事中「视杀人如艾草菅然」（把杀人看成割野草一样）演变而出，用来比喻轻视人命，任意加以残害。"},
  {"name": "城狐社鼠", "cid": 296891, "pid": 11701935, "num": 128, "meaning": "社：土地庙。城墙上的狐狸，社庙里的老鼠。比喻依仗权势作恶，一时难以驱除的小人。", "source": "《晋书・谢鲲传》：“对曰：‘隗诚始祸，然城狐社鼠也。’”", "example": "以事论，则现在的教育界中实无豺虎，但有些～之流，那是当然不能免的。（鲁迅《华盖集・“公理”的把戏》）", "story": "晋代将军王敦想除掉皇帝宠信的奸臣，谢鲲劝阻说：那人像'城狐社鼠'——狐狸藏在城墙里、老鼠躲在土地庙中，要打它们会损坏城墙和庙宇，投鼠忌器，难以清除。比喻依仗权势作恶、难以铲除的小人。"},
  {"name": "乘风破浪", "cid": 296891, "pid": 11701941, "num": 129, "meaning": "顺著风，破浪前进。＃语本《宋书．卷七六．列传．宗悫》。后亦用「乘风破浪」比喻人志向远大，不畏艰难，奋勇前进。_x000D_\n△「披荆斩棘」", "source": "＃《宋书．卷七六．列传．宗悫》", "example": "我矗立船首，张开双臂，体会一下乘风破浪的感觉。", "story": "根据《宋书．卷七六．宗悫（ㄑㄩㄝˋ）列传》中记载，南朝宋的振武将军宗悫，年轻时勇敢有胆识，练就一身好武艺，但因个性不受拘束，有时会意气用事。他的叔父宗炳曾问他将来的志向，他回答说：「愿乘长风破万里浪。」充分表示他胸怀大志，有不畏艰难、奋勇前进的精神。宗炳是个高尚清流的人，长年隐居，专务读书、作画，皇帝曾请他作官，都被婉拒。由于他深知姪儿的个性，听了这番话，不免有些担心，认为这个姪儿将来不是扬眉吐气，就是会连累家族。后来宗悫受人提拔，又因攻打林邑国有功，替国家立下了汗马功劳，受到皇帝赞赏，并封他为「洮阳侯」。「乘风破浪」这句成语就从这里演变而出，本义为顺著风、破浪前进，后亦用于比喻人志向远大，不畏艰难，奋勇前进。"},
  {"name": "程门立雪", "cid": 296891, "pid": 11701942, "num": 130, "meaning": "旧指学生恭敬受教。比喻尊师。", "source": "《宋史・道学传二・杨时》：“一日见颐，颐偶瞑坐，时与游酢侍立不去。颐既觉，则门外雪深一尺矣。”", "example": "为了请教问题，他程门立雪，耐心等候老师。", "story": "北宋学者杨时和游酢去拜见老师程颐，正遇上程颐闭目养神。二人不忍心打扰，就恭敬地站在门外等候。这时天降大雪，等程颐醒来，门外的积雪已经深达一尺。后用'程门立雪'形容尊师重道、虚心求教。"},
  {"name": "惩前毖后", "cid": 296891, "pid": 11701943, "num": 131, "meaning": "以从前的过失为教训，戒慎自己不再犯错。语本《诗经．周颂．小毖》。", "source": "《诗经．周颂．小毖》", "example": "做事时总要惩前毖后，才不会重蹈覆辙。", "story": "《诗经》是最早的诗歌总集，采集从周初至春秋中叶五百年间的歌谣作品和宗庙乐章。〈小毖〉一诗写周成王在管蔡、武庚之乱后，痛改前非，自我警惕的决心。成王为武王之子。周武王在弟弟周公的协助下打败商纣，建立周朝，死后由年幼的成王即位，周公则继续辅政。而武王的两个堂兄弟管叔和蔡叔忌恨周公，并且觊觎王位，于是暗中勾结商纣的儿子武庚，到处散布消息，说周公意图夺取王位。周成王听到这个流言后，逐渐地对周公失去信任，周公为了避嫌，便主动求去。周公走后，管、蔡等人如鱼得水般地进行种种叛乱，这时成王知道自己上了当，才赶紧又把周公召回。周公回来平息了叛乱，也对管、蔡等人做出惩处。事后，成王深切反省，并对众臣说：「我一定会有所警惕，谨言慎行，避免再犯过错。希望诸位臣子不要像管、蔡一样，引我误入歧途，否则我必然将施予严惩。」成王话中以「予其惩而毖后患」表示自己改过的决心，后来「惩前毖后」这句成语就从这里演变而出，用来指以从前的过失为教训，戒慎自己不再犯错。"},
  {"name": "惩一戒百", "cid": 296891, "pid": 11701944, "num": 132, "meaning": "见“惩一警百”。", "source": "《汉书·尹翁归传》", "example": "老师严肃处理作弊，是为了惩一戒百。", "story": "汉代尹翁归做官，对待豪强恶霸，抓住为首的严厉惩办，以儆效尤，这叫'以一警百'。意思是惩罚一个人，让许多人引以为戒。后来写作'惩一戒百'，指用惩处个别人来警告、教育众人。"},
  {"name": "赤膊上阵", "cid": 296891, "pid": 11701945, "num": 133, "meaning": "光着膀子上阵。比喻亲身上场，不加掩饰地进行活动。", "source": "明・罗贯中《三国演义》：“许褚性起，飞回阵中，卸下盔甲，浑身筋突，赤体提刀，翻身上马，来与马超决战。”", "example": "他终于～，亲自出马了。", "story": "三国时曹操部将许褚与马超交战，战到兴起，他卸去盔甲、赤膊上阵，挥刀死战，威风凛凛。后来用'赤膊上阵'形容不顾一切、亲自上场拼搏，也指不加掩饰、毫无策略地蛮干。"},
  {"name": "出尔反尔", "cid": 296891, "pid": 11701946, "num": 134, "meaning": "你怎么对待别人，别人也会怎么待你。语本《孟子．梁惠王下》。后用「出尔反尔」比喻人的言行前后反复，自相矛盾。_x000D_\n△「反复无常」、「朝三暮四」、「朝秦暮楚」", "source": "《孟子．梁惠王下》", "example": "你放心，我说了算数，绝不会出尔反尔。", "story": "据《孟子．梁惠王下》载，春秋时，邹国与鲁国争战，邹国人民皆不愿为国家效死，让邹穆公非常的生气与无奈。孟子告诉他说：「你的人民之所以如此，那是因为当他们遭遇饥荒时，官吏们对朝廷隐瞒灾情，任由灾民流离失所，曝尸山沟，现在他们当然会用同样的态度回应。曾子曾警惕人说：『你现在怎么对待人，人家也会同样地对待你。』若是您从此施行仁政，未来人民一定也会有相对的回报。」后来「出尔反尔」这句成语就从这里演变而出，用来比喻你怎么对待别人，别人也会怎么待你。今则多用以比喻人的言行前后反复，自相矛盾。"},
  {"name": "出类拔萃", "cid": 296891, "pid": 11701947, "num": 135, "meaning": "远超出同类之上，高出同群。形容才能特出，超越众人。语本《孟子．公孙丑上》。\n△「出人头地」、「超群绝伦」", "source": "《孟子．公孙丑上》", "example": "他的能力绝对是同行中出类拔萃的！", "story": "宰我、子贡、有若都是孔子的弟子，在他们眼中，孔子是个伟大的圣人。宰我认为孔子的贤能远超过尧舜。而子贡则认为没有任何的人、事可以逃过孔子的细微观察，孔子从先王所创作的制度中，就知道他们所推行的政事；听闻先王所制定的礼乐，就可以知道他们所传承的道德。有若认为孔子之于一般人类，就如麒麟对于一般走兽，凤凰对于一般飞鸟，泰山对于低矮的小土堆，河海对于路上的流水，虽然都是同类，却远远的超越他们而大有差别。换言之，孔子与一般的人民，虽也是同类，但在才学、德行各方面却都远远的超出其同类，而特立挺拔于同群之中，自有人类以来，再也没有比孔子更伟大的了。后来「出类拔萃」这句成语，就从《孟子．公孙丑上》中的「出于其类，拔乎其萃」演变而出，用来形容才能特出，超越众人。"},
  {"name": "出人头地", "cid": 296891, "pid": 11701948, "num": 136, "meaning": "高出一个头。后指超越他人，独露头角。＃语本宋．欧阳修〈与梅圣俞书〉其三〇。\n△「出类拔萃」", "source": "＃宋．欧阳修〈与梅圣俞书〉其三〇（据《欧阳修全集》卷一四九引）", "example": "一心想出人头地，使他不愿意向命运屈服。", "story": "北宋仁宗嘉祐年间，当时著名的史学家、文学家欧阳修担任科举考试的主考官。当他阅卷时，看到了苏轼的文章，十分惊喜，认为这苏轼是个难得的人才，想将他名列第一。因为当时考卷是密封的，并不知是何人所作。欧阳修虽然非常赞赏这篇文章，但又觉得看起来很像是他朋友曾巩的文笔，为了避嫌，就把这份考卷定为第二名。放榜后，苏轼去拜见欧阳修时，才知是误会一场。欧阳修很欣赏苏轼的才气，他写给好友文学家梅尧臣的信中说：「读轼书，不觉汗出，快哉快哉！老夫当避路，放他出一头地也。」就是说欧阳修觉得苏轼实在很有才气，应该给苏轼让路，不要阻挡他的前程，让他能超出自己的成就。后来苏轼在欧阳修的提拔下，成为北宋著名的政治家和文学家。「出人头地」这句成语就从这里演变而出，用来指超越他人，独露头角。"},
  {"name": "打草惊蛇", "cid": 296891, "pid": 11701949, "num": 137, "meaning": "击打草丛以吓走蛇。比喻某甲受到惩戒，而使某乙、丙等知所警惕。※＃语或本宋．郑文宝《南唐近事》卷二。后用「打草惊蛇」比喻对付敌人时，行事不密，致使对方有所警觉，而预先防备。", "source": "※＃宋．郑文宝《南唐近事》卷二*1*", "example": "在野外要进入草丛时，切记要先打草惊蛇。", "story": "在宋朝郑文宝所著的《南唐近事》一书中，曾记载这么一个故事：王鲁，南唐人，生卒年不详，曾任当涂县的县令。他在任上时，贪污收受钱财。有一天，他在府里批示案件，其中有一个案件是地方百姓联名控告主簿贪收贿赂。王鲁看了吓一跳，事实上收贿的不只主簿一人，他也有份，于是在卷宗上批示：「你们虽然只是用棍子打草丛，但是我就像藏身在草丛中的蛇，已经有所警惕。」这件事一经传扬出去，成为好事的人取笑批评的话柄。后来「打草惊蛇」这句成语就从这里演变而出，用来比喻行事不密，致使对方有所警觉，而预先防备。"},
  {"name": "大笔如椽", "cid": 296891, "pid": 11701950, "num": 138, "meaning": "椽：放在檩子上架着屋顶的木条。象椽子那样大的笔。形容著名的文章。也指有名的作家。", "source": "《晋书·王珣传》", "example": "这篇社论气势磅礴，真可谓大笔如椽。", "story": "东晋大臣王珣梦见有人送他一支像房椽般粗大的笔。醒来后他对人说：这预示我将有重要的文章要写。不久皇帝驾崩，丧事上的重要文书果然都由他执笔。后用'大笔如椽'称赞文笔雄健或重要的大手笔。"},
  {"name": "大腹便便", "cid": 296891, "pid": 11701951, "num": 139, "meaning": "大肚子显得肥胖而凸出的样子。＃语本晋．司马彪《续汉书》。\n△「脑满肠肥」", "source": "＃晋．司马彪《续汉书》（据《艺文类聚．卷二五．人部九．嘲戏》引）", "example": "妇女怀胎几个月后，就会显得大腹便便，行动极不方便。", "story": "汉代边韶，字孝先，陈留浚仪人。头脑灵活敏捷，口才流利，以擅长文学出名，收过不少学生。有一回，大白天他躺在床上闭目养神，门下弟子看到了，就在背地里嘲笑他肚子大，懒得读书，只想睡觉。结果被他听到了，立刻回答说：「肚子大是因为饱读书籍，装满了五经。即使在睡觉时，想的也是经书上的学问。当学生的连老师都可以嘲笑，这是典出何处啊？」这番话使得嘲笑他的那些弟子，心里感到羞愧。后来「大腹便便」这个成语就从这里演变而出，用于表示大肚子显得肥胖而凸出的样子。"},
  {"name": "大公无私", "cid": 296891, "pid": 11701952, "num": 140, "meaning": "谓秉公处理，毫无偏私。语本《管子．形势解》。\n△「铁面无私」、「铁面御史」", "source": "《管子．形势解》", "example": "这样的判决大公无私，可令大家都信服。", "story": "「大公无私」原作「至公无私」。管子，字仲，春秋齐国颍上人，为法家始祖。《管子．形势解》中提到，风、雨对人都是一视同仁，不会因为贵贱美恶，而有大小强弱的分别，所以说风雨没有固定的方向或特定的喜好，因此是「至公无私」的。后来「大公无私」这句成语就从这里演变而出，用来指秉公处理，毫无偏私。出现「大公无私」的书证如《二十年目睹之怪现状》第六一回：「这种赌法，倒是大公无私，不能作弊的。」"},
  {"name": "大逆不道", "cid": 296891, "pid": 11701953, "num": 141, "meaning": "指谋反背叛，罪大恶极。＃语本《史记．卷八．高祖本纪》。后亦用「大逆不道」指违反伦常，罪恶深重。_x000D_\n△「大逆不忠」", "source": "＃《史记．卷八．高祖本纪》*1*", "example": "这种大逆不道之徒，天理难容！", "story": "「大逆不道」原作「大逆无道」。秦朝末年，各地纷纷举兵抗秦，最后则形成刘邦和项羽互相争霸的局面。当初项羽和项梁在起兵之初，为了号召反秦的需要，拥立一个傀儡皇帝楚怀王，各处抗秦的义军也都尊怀王为义帝。项羽表面上是尊崇怀王，但实际上却不听从怀王的命令。不但自己称号为西楚霸王，并且强迫义帝迁徙到长沙，后来更加以杀害。汉王听闻义帝被杀，心里非常难过，于是为义帝举办丧事，同时公开指责项羽「大逆无道」，意思就是说罪行重大，严重违反应有的君臣伦理。后来「大逆不道」这句成语就从这里演变而出，用来指违反伦常，罪恶深重。"},
  {"name": "箪食瓢饮", "cid": 296891, "pid": 11701955, "num": 142, "meaning": "只吃一碗饭，只喝一瓢水。形容生活简单、清苦。语本《论语．雍也》。\n△「陋巷箪瓢」", "source": "《论语．雍也》", "example": "我的生活很简单，箪食瓢饮就够了。", "story": "「箪食瓢饮」原作「一箪食，一瓢饮」。颜回名列孔门德行科，他的个性好学，不会迁怒到别人身上，不再犯同样的过错，在所有弟子中，最为孔子器重。颜回家贫，经常三餐不继，却没有动摇他行仁的信念。因此孔子在《论语．雍也》篇中称赞颜回，说：「贤德啊，颜回！只吃一碗饭，只喝一瓢水，住在简陋的巷子之中，别人都难以忍受这种愁苦，但颜回仍旧没有改变他的快乐。颜回真是贤德啊！」颜回英年早逝，对孔子来说是一个沉重的打击，孔子悲叹颜回之死「是上天要毁灭我啊」！由此可知孔子痛失英才那种深沉的惋惜与失落。「箪食瓢饮」这句成语，就从《论语》原文「一箪食，一瓢饮」演变而出，用来形容生活简单、清苦。出现「箪食瓢饮」的书证如三国魏．桓范〈荐管宁表〉：「以箪食瓢饮，过于颜子，漏屋蔽衣，逾于原宪。」"},
  {"name": "得过且过", "cid": 296891, "pid": 11701956, "num": 143, "meaning": "能够过得去就暂且这样过下去。※语或本宋．陆游〈杂咏〉诗。后用「得过且过」形容苟且偷安，不求上进。", "source": "※宋．陆游〈杂咏〉诗四首之二（据《陆放翁全集．剑南诗稿．卷七四》引）", "example": "你这种得过且过的做事态度，如何能让上司信任。", "story": "「得过且过」说的是一种能够过得去就暂且过下去的生活态度。在宋代大诗人陆游的〈杂咏〉诗中，有一首写到自己：「得过一日且一日，安知今吾非故吾？袖手明窗读《周易》，不辜香饭一斋盂。」意思是说自己闲散下来，就这样一天天过著，不过这样的生活也不错，能够在明窗下静读《周易》，倒也不辜负那还能吃到口的香喷喷的饭。这里的「得过一日且一日」，一般以为可能就是「得过且过」一语的典源。关于这句成语有个有趣的传说：元．陶宗仪《南村辍耕录．卷一五．寒号虫》中记载：在五台山上有一种鸟，每当春夏，全身羽毛绚丽丰满，相当美丽。这时牠的叫声听起来好像得意地说：「凤凰不如我！凤凰不如我！」可是到了秋冬时，牠的羽毛全部脱落，变得十分难看。这时牠的叫声听起来就变成了：「得过且过！得过且过！」所以人们称牠作「寒号虫」或「寒号鸟」。"},
  {"name": "得心应手", "cid": 296891, "pid": 11701957, "num": 144, "meaning": "心里怎么想，手便能怎么做。比喻技艺熟练，运用自如。＃语本《庄子．天道》。  后亦用「得心应手」比喻做事顺利。", "source": "＃《庄子．天道》*1*", "example": "这把菜刀虽旧，但使来得心应手。", "story": "「得心应手」原作「得手应心」。先秦大哲学家庄子是道家思想的代表人物。他曾经说过一个故事：有一天齐桓公在堂上读书，有个工匠轮扁在堂下做车轮。轮扁看到桓公读书十分专心，就放下工具，走上堂去，向桓公问道：「您读什么书呢？」桓公就生气地说道：「国君读书，你一个小小的工匠也敢过问！」轮扁回答道：「臣不敢，臣只是从臣工作的角度来看，臣要将轮子装上车轴时，如果车轮太松车轴就不牢，太紧的话就装不进去。只有不松不紧，才能制作出一个好轮子，这完全依靠熟练的技巧，心里怎么想，手便能怎么做，这其中的技术，都是经验的累积，无法用言语文字说得很明白。我无法传授给我的儿子，我的儿子也无法从我身上领会。古人的经验和智慧也是如此，不可能完全藉著书本传授给后人。大王，您所读的，不过是古人的糟粕而已啊！」后来「得心应手」这句成语就从工匠轮扁所说的「得之于手而应于心」演变而出，用来比喻人技艺熟练，运用自如，或用来比喻做事顺利。"},
  {"name": "得意忘形", "cid": 296891, "pid": 11701958, "num": 145, "meaning": "（一）形，形体。「得意忘形」指因心意志趣获得满足而物我两忘。语本《晋书．卷四九．阮籍列传》。形容人高兴过头，举止失去常态。_x000D_\n△「得意洋洋」_x000D_\n（二）形，形式。「得意忘形」指文学艺术创作上，取其精神而舍其形式。语本宋．欧阳修〈李邕书〉。", "source": "《晋书．卷四九．阮籍列传》_x000D_\n宋．欧阳修〈李邕书〉（据《欧阳文忠公集．卷一三〇．试笔》引）", "example": "他才升了一个小组长，就得意忘形到这副德性！", "story": "《晋书．卷四九．阮籍列传》载，晋代的文学家阮籍，是个性格豪放、不拘礼教的人。他博学多闻，也有为国效力的壮志。但因生活在改朝换代的动乱时代，无法一展抱负，对统治者的作法也相当不满。于是隐居山林，不参与任何事务，平常不是闭门读书，就是游山玩水，也常和嵇康、王戎等几个好友在竹林里喝酒、弹琴、吟诗、喧闹，而有「竹林七贤」之称。兴致高昂之时，常常手舞足蹈，大叫大笑，忘了自己。后来「得意忘形」这句成语就从这里演变而出，形容人高兴过头，举止失去常态。\n\n＋\n\n李邕是唐代知名的书法家，他学习晋代王羲之、钟繇等大书法家的笔法，笔力雄健劲拔，善写行楷，自成一格。宋代文学家欧阳修刚开始接触李邕的字时，并不十分欣赏他的风格，但后来愈看愈喜欢，还从中习得不少笔法，因此写下〈李邕书〉这篇文章，描述自己对李邕书法的感受。他从李邕的书法中，看到了王羲之、钟繇等大书法家的风格，领悟到书法的传承性，可以透过一个人的笔法学到其他人的精华，对技艺的增长十分有帮助。但他也强调，自己虽然受到李邕的影响，但书写形式并不完全相同，而是取其精髓。后来「得意忘形」这句成语，就从原文中「得其意而忘其形」演变而出，指文学艺术创作上，取其精神而舍其形式。"},
  {"name": "德高望重", "cid": 296891, "pid": 11701959, "num": 146, "meaning": "形容人品德高尚，极有声望。语本《晋书．卷六四．简文三子列传．会稽文孝王道子》。\n△「年高德劭」", "source": "《晋书．卷六四．简文三子列传．会稽文孝王道子》", "example": "他在政界德高望重，一言九鼎，很受大家的爱戴。", "story": "「德高望重」原作「德隆望重」。自从东晋大臣谢安病死后，晋孝武帝便将大权交给他的弟弟会稽文孝王司马道子，由司马道子与其子司马元显把持朝政。司马元显是司马道子的长子，因家世显赫，周围的人对司马元显极尽奉承巴结之能事，让司马元显自以为是一代英杰，无人可比。孝武帝也因他有辅政之功，加上他的生母刘氏是会稽王夫人，所以让他享有高官厚禄，使司马元显更是目中无人。太皇太后驾崩时，孝武帝召司马道子入宫，司马元显认为自己「德隆望重」（德行高，声望隆），所以命令百官要向他跪拜。群臣慑于司马元显的淫威，也只好跪拜。后来「德高望重」这句成语就从原文「德隆望重」演变而出，用来指品德高尚，极有声望。"},
  {"name": "滴水穿石", "cid": 296891, "pid": 11701960, "num": 147, "meaning": "犹「水滴石穿」。见「水滴石穿」条。01.唐．周昙〈吴隐之〉诗：「徒言滴水能穿石，其那坚贞匪石心。」", "source": "", "example": "", "story": "此处所列为「水滴石穿」之典故说明，提供参考。尸子，名佼，春秋末年时候的思想家。曾为商鞅的门下客，后来商鞅遭车裂，尸子避祸入蜀，终老一生。《尸子》一书原有二十篇，学说综合儒、墨、名、法四家，后来全书散佚，今本只剩十二篇。《尸子》书中提到：「水，虽然不是钻石头的钻子，但是可以把石头滴穿；绳子，虽然不是用来锯木头的锯子，但是只要不停的在木头上来回磨擦，同样可以把木头切断。」这是长时间累积下来的结果。后来「水滴石穿」这句成语就从这里演变而出，用来比喻持之以恒，事必有成。但也可用来比喻小问题日积月累也会成为大问题。例如在宋．罗大经《鹤林玉露》中记载一个故事：张乖崖当崇阳令时，因为发现管理府库的官吏夹带一文钱出来，于是判处杖刑，但是他不服，张乖崖就提笔写下判例：「虽然每天只偷一文钱，但一千天之后就有一千文钱，日积月累就会变成为数可观的一笔钱，就像用绳子磨擦木头久了也会断，水不间断的滴在石头上也会有穿透的一天。」"},
  {"name": "恶贯满盈", "cid": 296891, "pid": 11701961, "num": 148, "meaning": "贯，本指以线穿钱，钱满一贯，就不能增加，称为满贯。此处指恶行「累积」，《广雅．释诂一》︰「贯，累也。」罪恶累积，已达满溢的程度。比喻罪大恶极，末日已到。＃语本《书经．泰誓上》。\n△「罪大恶极」", "source": "＃《书经．泰誓上》*1*", "example": "这帮歹徒恶贯满盈，终于受到法律制裁。", "story": "《尚书》之名原意为上古之书，属于泛称，后来才成专名。「尚书」一名的原意，即指古代的公文。〈泰誓〉这一篇是周武王起兵讨伐商纣王时，大会诸侯于孟津，对将士们的誓师的宣言。商朝末年，商纣王暴虐无道，百姓生活痛苦，诸侯也怀有异心。当时有一个叫姬昌的诸侯（即后来的周文王），在他的封地上施行仁政，广得民心和诸侯的支持。姬昌死后，其子姬发继位（即周武王），便率领诸侯起兵伐纣。军队在孟津渡过黄河，准备进发商都朝歌。此时周武王聚集军队，发表誓师宣言说：「商朝的罪恶就像用绳子贯穿钱币，已经完全穿满了！现在不是我要去讨伐商朝，而是天命要我去做，我如果不遵守天命，那我就有大罪了！」将士听了周武王的宣言后士气大增，终于在牧野一战大败商朝军队，推翻了纣王，建立周朝。后来「恶贯满盈」这句成语就从这里演变而出，用来比喻罪大恶极，末日已到。"},
  {"name": "二桃杀三士", "cid": 296891, "pid": 11701963, "num": 149, "meaning": "将两个桃子赐给三个壮士，三壮士因相争而死。比喻借刀杀人。", "source": "三国・蜀・诸葛亮《梁甫吟》：“一朝被谗言，二桃杀三士。”", "example": "～，讵假剑如霜。（唐・李白《惧谗》诗）", "story": "春秋时齐景公手下有三名猛士，骄横不法。宰相晏婴献计：赏赐两个桃子，让三人论功分食。三人都自认功劳最大，互不相让，先后羞愤自杀。两个桃子便除去了三个勇士，比喻用计谋借刀杀人。"},
  {"name": "发奸擿伏", "cid": 296891, "pid": 11701964, "num": 150, "meaning": "揭露隐藏的坏人坏事，查出暗中作恶的人。形容官吏精明，善于发现隐蔽的罪行。", "source": "《汉书·赵广汉传》", "example": "这位细心的警察叔叔发奸擿伏，终于找到了小偷藏起来的东西。", "story": "西汉时，京兆尹赵广汉办案非常精明。他常设铜箱让人匿名举报，又派手下明察暗访，许多隐藏的盗贼和贪官都被他查了出来。百姓拍手称快，坏人却十分害怕，再也不敢偷偷做坏事了。"},
  {"name": "发蒙振落", "cid": 296891, "pid": 11701965, "num": 151, "meaning": "蒙：遮盖，指物品上的罩物；振：摇动。把蒙在物体上的东西揭掉，把将要落的树叶摘下来。比喻事情很容易做到。", "source": "西汉・司马迁《史记・汲郑列传》：“好直谏，守节死义，难惑以非。至如说丞相弘，如发蒙振落耳。”", "example": "这道题对他来说，就像发蒙振落一样简单。", "story": "西汉时，武安侯田蚡想排挤窦婴和灌夫。汲黯为人刚直，对田蚡说：您想除掉他们，就像揭开盖布、摇下落叶一样容易，何必耍手段？田蚡听了很尴尬。后来人们用这个词形容做事轻而易举。"},
  {"name": "幡然改途", "cid": 296891, "pid": 11701966, "num": 152, "meaning": "幡：通“翻”；幡然：很快而彻底；途：途径。指迅速地完全改变原来的道路。", "source": "《孟子·万章上》", "example": "小明认识到错误后幡然改途，成了一个爱学习的好孩子。", "story": "古时候有一位读书人，原本走错了路，常做糊涂事。后来他听了贤人的劝导，忽然醒悟，立刻改变原来的做法，重新走正道。人们称赞他能及时回头，用“幡然改途”来赞美知错就改的人。"},
  {"name": "返老还童", "cid": 296891, "pid": 11701967, "num": 153, "meaning": "由衰老恢复年轻。＃语本南朝梁．何逊〈神仙〉。后亦用「返老还童」形容年纪虽大，却像年轻人一样精力充沛。", "source": "＃南朝梁．何逊〈神仙〉（据《何水部集》卷七引）*1*", "example": "一看到她喜欢的宠物，她像是返老还童般，露出小女孩的神态。", "story": "「返老还童」原作「反老为少」。何逊（？∼西元５１８），南朝梁诗人，东海郯（今山东郯城）人，字仲言，官至庐陵王记室。能诗文，文章与刘孝绰并称，世号「何刘」。在〈神仙〉一文中，何逊叙述神仙的生活，认为他们能够把丑陋的相貌变美丽，又可以从衰老变回年轻。后来「返老还童」这句成语就从这里演变而出，用来形容年纪虽大，却像年轻人一样精力充沛。「返老还童」较早的书证是出自于《云笈七签．卷六〇．诸家气法》：「日服千咽，不足为多，返老还童，渐从此矣。」在晋朝葛洪所著的《神仙传》里，另外记载了一个关于「返老还童」的故事。淮南王刘安是汉朝的贵族，他虽然享尽荣华富贵，可是仍想要长生不老，得道成仙。有一天，有八个老人前来拜访他，说自己是仙人。刘安见他们老态龙钟的，心想仙人不是都应该长生不老，青春永驻吗？于是认为他们在骗人，就叫守门人打发他们离开。老人们就说：「你既然嫌我们老，那我们就变得年轻一点吧！」于是一个转身，这八个老人就变成八个童子了。"},
  {"name": "防微杜渐", "cid": 296891, "pid": 11701968, "num": 154, "meaning": "在错误或坏事萌芽的时候及时制止，杜绝它发展。※语或本汉．丁鸿〈日食上封事〉。\n△「未雨绸缪」、「防患未然」", "source": "※汉．丁鸿〈日食上封事〉（据《后汉书．卷三七．桓荣丁鸿列传．丁鸿》引）", "example": "为政要防微杜渐，消弭乱源，才能安定政局。", "story": "东汉和帝即位时只有十岁，由窦太后临朝听政。因为和帝并非窦太后亲生的儿子，所以太后处心积虑地架空和帝，培养娘家的势力。她让自己的哥哥窦宪当上大将军，掌握军权，其他的三个兄弟窦笃、窦景、窦环也都封侯进爵，朝政几乎都由窦氏的亲人、姻亲所把持，甚至连地方的官员都是由窦家所安排的，权倾一时。当时的司徒丁鸿，对窦氏专权祸国十分不满，是少数没有向窦氏低头的大臣。那时刚好发生了日蚀，丁鸿借机向和帝上书，希望和帝能够压抑窦氏。他引《诗经》的话说：「现在上天已经用灾异之象来警告我们，我们不能游戏豫乐，不当回事。」希望和帝能亲揽政权，从小处防范弊病，并制止它逐渐扩大，这样才可以除去祸患，聚集福慧。后来和帝命丁鸿为太尉兼卫尉，驻守宫廷，并收回窦宪的兵权，削夺窦氏的权力，终于化解了一场政治危机。后来「防微杜渐」这句成语可能就这里演变而出，在错误或坏事萌芽的时候及时制止，杜绝它发展。"},
  {"name": "改过自新", "cid": 296891, "pid": 11701969, "num": 155, "meaning": "改正过失，重新作人。◎语出《史记．卷一〇．孝文本纪》。", "source": "《史记．卷一〇．孝文本纪》\n《史记．卷一〇六．吴王濞列传》", "example": "她既然知错了，你应该给她一个改过自新的机会。", "story": "西汉时，有一个名医叫淳于意，他被人诬告，要把他押解到长安审判。淳于意的女儿缇萦一路跟著父亲的囚车来到长安。到了长安，缇萦上书给文帝，内容叙述她父亲是个廉明正直的人，如今被判有罪，将被处刑。人死不能复生，若被处了「肉刑」，斩掉的肢体肌肤，就再也接不回去了。将来想要改过，却永远带著伤口而无法重新作人。缇萦希望能代父赎罪，让父亲有改过自新的机会。汉文帝被缇萦的孝心深深感动，就赦免了淳于意的罪。典源又见《史记．卷一〇六．吴王濞传》。内容则是叙述汉文帝时，对吴王濞的种种恶行不忍处罚，但吴王濞并未因此改正过失，重新作人，所以鼌错建议景帝应该削减吴王的势力，以免造成更大的祸乱。其中也用到「改过自新」一语。后来「改过自新」用来指改正过失，重新作人。"},
  {"name": "肝脑涂地", "cid": 296891, "pid": 11701970, "num": 156, "meaning": "肝脑溅洒在地上。形容死状极惨。语本《战国策．燕策一》。后亦用于比喻尽忠竭力，不惜牺牲生命之意。", "source": "《战国策．燕策一》", "example": "恐怖分子的炸弹攻击，不知使多少无辜民众肝脑涂地。", "story": "在《战国策．燕策一》中记载了张仪为秦国破除合纵而行连横之计，向燕王游说道：「大王现在最亲信的是赵国。但是赵国可信吗？代王是赵王的姊夫，但是赵王为了兼并代国，于是设计邀请代王在句注要塞相见。事先暗中命令工匠制作了一枝尾柄很长的金斗，嘱咐厨师趁酒酣乐，要上热羹的时候反持金斗，击杀代王。结果代王在宴会上惨死，脑浆溅得一地都是。代王的妻子，也就是赵王的姊姊，听到了这个消息后也自杀了。这件事天下皆知，大王一定也不会陌生。……」后来「肝脑涂地」这句成语就从这里的原文「脑涂地」演变而出，说明死状极惨。后来用以比喻人尽忠竭力，不惜牺牲生命之意。"},
  {"name": "感激涕零", "cid": 296891, "pid": 11701971, "num": 157, "meaning": "感激落泪，形容非常感谢。语本唐．刘禹锡〈平蔡州〉诗三首之二。", "source": "唐．刘禹锡〈平蔡州〉诗三首之二（据《全唐诗．卷三五六．刘禹锡》引）", "example": "社会大众的温情及帮助，使他感激涕零。", "story": "唐自安史之乱后，内有宦官、朋党之祸，外有藩镇割据，盛唐繁华气象已不复存在。宪宗即位后，在边疆形势趋缓，国力较为丰厚下，开始展开削藩的战争。元和九年，淮西节度使吴少阳死，其子吴元济自领军务，随即发动叛乱。宪宗发宣武等十六道兵讨伐，经过长期的战争，最后李愬于元和十二年攻破蔡州城，生擒吴元济，平定了淮西，结束了长达四年的战争。至此，割据藩镇相继归顺，朝廷的威信为之一振。刘禹锡写的〈平蔡州〉诗即是描写这场战争的情景。长达四年的战争结束后，城里到处响著和平的音乐，大家回忆起战争时的旧事，都对「汉家飞将」李愬救众人于水火，让大家免于再受战争之苦而感激落泪。后来「感激涕零」这句成语，就从文中「相与感激皆涕零」一语演变而出，用来形容非常感谢。"},
  {"name": "高山流水", "cid": 296891, "pid": 11701972, "num": 158, "meaning": "形容乐曲高妙。＃语本《列子．汤问》。后亦用「高山流水」比喻知音才懂的音乐。", "source": "＃《列子．汤问》", "example": "这种高山流水之乐，真是人间难得几回闻。", "story": "「高山流水」原形容乐曲的高妙，出自于《列子．汤问》里的一段故事：春秋时楚国的伯牙善于弹琴，每回弹琴时，好友钟子期都能听出他琴音里要表达的心意。有一回他在弹琴时，想要展现的是高山的壮阔，钟子期听了后说：「弹得真好！像泰山般高耸。」又有一次想表达盛大的流水，钟子期就说：「嗯！这琴声有如江河般地壮阔。」每次不论弹什么，钟子期都能听出伯牙想借由琴声表达的意念，伯牙十分感动。钟子期死后，伯牙认为此生再也没有人能这样懂得他的音乐了，于是将琴摔坏，终生不再弹琴。伯牙与钟子期的故事流传后世甚广，因此「知音」一词就用来比喻知心的朋友。而文中「志在登高山」、「志在流水」二语，就被浓缩成「高山流水」，用来形容乐曲的高妙，后来也因这段故事，而用它来比喻知音。"},
  {"name": "高屋建瓴", "cid": 296891, "pid": 11701973, "num": 159, "meaning": "建：倒水，泼水；瓴：盛水的瓶子。把瓶子里的水从高层顶上倾倒。比喻居高临下，不可阻遏。", "source": "西汉・司马迁《史记・高祖本纪》：“地势便利，其以下兵于诸侯，譬犹居高屋之上建瓴水也。”", "example": "革命的豪情和革命的气魄，使他的史剧气势恢阔，振摆超腾，～，雄浑奔放。（《郭沫若剧作全集编后记》）", "story": "西汉初年，田肯对刘邦说：陛下建都关中，地势险要，从那里出兵攻打诸侯，就像在高屋顶上往下倒水一样，谁也挡不住。刘邦听了很高兴，重赏了他。后来人们用“高屋建瓴”形容占有优势、气势逼人。"},
  {"name": "高阳酒徒", "cid": 296891, "pid": 11701974, "num": 160, "meaning": "高阳：古乡名，在今河南杞县西南。秦末郦其食即此乡人，对刘邦自称“高阳酒徒”。用以指嗜酒而放荡不羁的人。", "source": "西汉・司马迁《史记・郦生陆贾列传》：“走！复入言沛公，吾高阳酒徒也，非儒人也。”", "example": "那位大叔是个高阳酒徒，爱喝酒，说话也直来直去。", "story": "秦朝末年，郦食其去见刘邦。卫兵说他是读书人，刘邦不愿见。郦食其瞪眼按剑说：我是高阳酒徒，不是什么书呆子！刘邦听他豪爽，连忙请进。后来郦食其靠计谋帮刘邦拿下陈留，立了大功。"},
  {"name": "各得其所", "cid": 296891, "pid": 11701975, "num": 161, "meaning": "原指各人都得到满足。后指每个人或事物都得到恰当的位置或安排。", "source": "《周易・系辞下》：“日中为市，致天下之民，聚天下之货，交易而退，各得其所。”", "example": "全国人民都要有说话的机会，都要有衣穿，有饭吃，有事做，有书读，总之是要～。（《毛泽东选集・在陕甘宁边区参议会的演说》）", "story": "西汉时，东方朔劝汉武帝说：天下的人才就像各种器具，用对了地方就有用，用错了就没用。希望陛下让每个人都能发挥长处，各得其所。汉武帝觉得有理。后来这个词指安排妥当，人人满意。"},
  {"name": "孤注一掷", "cid": 296891, "pid": 11701976, "num": 162, "meaning": "「孤注」，赌博时将所有资本下注。＃语出宋．司马光《涑水记闻》卷六。「一掷」，掷一次骰子来决定胜负。※语或出《晋书．卷八五．何无忌列传》。后以「孤注一掷」指赌博时，倾其所有而下注，并以一掷决定胜负。比喻危急时，投入全部力量，作最后的冒险。_x000D_\n△「背水一战」", "source": "「孤注」：＃宋．司马光《涑水记闻》卷六_x000D_\n「一掷」：※《晋书．卷八五．何无忌列传》", "example": "他这种孤注一掷的做法，太冒险了。", "story": "「孤注一掷」原是一种赌博的行为。赌徒输钱后，将身上所剩的财物通通拿出来，赌最后一把的输赢，就叫作「孤注一掷」。文献上，「孤注」一语可以在宋代司马光《涑水记闻》卷六记载的一段话中看到。这段记载提到了宋真宗时，因为契丹人入侵，宰相寇准建议真宗御驾亲征。双方会战于距首都汴京三百里外之澶（ㄔㄢˊ）渊，宋战胜辽国，并于澶渊定盟和解。真宗为此事更加器重寇准，却引起大臣王钦若的嫉妒。王钦若有一次趁机向真宗说：「澶渊一战，寇准是拿皇上当作孤注，和契丹人赌最后一把。万一赌输了，皇上岂不是就危险了？」这里就用了「孤注」。至于「一掷」，出现得更早。在《晋书．卷八五．何无忌列传》中，提到何无忌联合刘裕等人，起兵征伐桓玄。有人向桓玄说这些人只是乌合之众，不用害怕。哪知桓玄说：「刘裕这个人，家中可能连一石（ㄉㄢˋ）米的存粮都没有，赌摴蒲（ㄕㄨ　ㄆㄨˊ）的时候，却可以不计生活是否过得下去，照样一掷百万。这等豪气，怎可以小看？」这里就用了「一掷」。可见「一掷」原是指赌博下注的行为。把这两个词语合起来用的文献，可以在《元史．卷一二七．伯颜列传》中看到。伯颜率军攻打阳罗堡，守城宋军拒不投降，大家说：「我辈受宋厚恩，戮力战死，此其时也，安有叛逆归降之理？被吾甲兵，决之今日，我宋天下，犹赌博孤注，输赢在此一掷尔！」意思就是说：大家准备决一死战，大宋天下的存亡，就在此孤注一掷了。后来「孤注一掷」演变成一句成语，除赌博下注的原义外，常用来比喻危急时，投入全部力量，作最后的冒险。"},
  {"name": "鼓盆之戚", "cid": 296891, "pid": 11701977, "num": 163, "meaning": "旧指死了妻子。", "source": "先秦・庄周《庄子・至乐》：“庄子妻死，惠子吊之，庄子则方箕踞鼓盆而歌。”", "example": "家綦贫，又有～。（清・蒲松龄《聊斋志异・小谢》）", "story": "战国时，庄子的妻子去世了。朋友惠子来吊唁，却见庄子敲着瓦盆唱歌。惠子责怪他无情。庄子说：她本来就没有生命，现在回归自然，我若大哭反而不明道理。后来人们用“鼓盆之戚”指丧妻之痛。"},
  {"name": "挂羊头卖狗肉", "cid": 296891, "pid": 11701978, "num": 164, "meaning": "比喻以好的名义做幌子，实际上名不副实或做坏事", "source": "宋・释惟白《续传灯录》第31卷：“悬羊头，卖狗肉，知它有甚凭据。”", "example": "有些商家挂羊头卖狗肉，标着便宜实际却骗人。", "story": "春秋时，齐景公让都城卖肉的挂羊头，却偷偷卖狗肉骗人。晏子劝景公：您挂羊头卖狗肉，百姓不服，国家也会乱。景公听后下令改正。后来人们用它批评名不副实、弄虚作假的行为。"},
  {"name": "管鲍之交", "cid": 296891, "pid": 11701979, "num": 165, "meaning": "春秋时，齐人管仲和鲍叔牙相知最深。后常比喻交情深厚的朋友。", "source": "西汉・司马迁《史记・管仲传》：“生我者父母，知我者鲍子也。”", "example": "他俩从小一起长大，真是管鲍之交。", "story": "春秋时管仲与鲍叔牙是好友。管仲家贫，两人做生意他多分利润，鲍叔牙不以为他贪；管仲三次做官被罢免，鲍叔牙不以为他愚。后来管仲感叹：'生我者父母，知我者鲍子也。'后用'管鲍之交'比喻深厚知心的友谊。"},
  {"name": "管中窥豹", "cid": 296891, "pid": 11701981, "num": 166, "meaning": "从管中只看见豹的一小部分。比喻所见甚小，未得全貌。※＃语或本南朝宋．刘义庆《世说新语．方正》。\n△「以管窥天」、「管窥蠡测」", "source": "※＃南朝宋．刘义庆《世说新语．方正》", "example": "他这是管中窥豹之见，不足为凭。", "story": "「管中窥豹」是指从管中看豹，只能看到一小部分，不能得到事物的全貌。这句成语见于南朝宋．刘义庆《世说新语．方正》，记载了一段王献之幼时的事。东晋大书法家王献之小时候，有一次在看父亲的门生玩赌博游戏，居然能看得出胜负，在一旁叫道：「南风不竞。」那些门生轻视他是小孩子，便笑著说：「这小鬼有如用管子看豹，只看到牠身上的一块斑点。」嘲笑他年纪小，见识少。王献之人小气傲，听到这句话，气得瞪大了眼睛，怒冲冲地说：「我只比荀粲和刘真长差一点而已，比你们强多了！」说完便拂袖而去。后来「管中窥豹」被用来比喻所见甚小，未得全貌。"},
  {"name": "狐假虎威", "cid": 296891, "pid": 11701982, "num": 167, "meaning": "假，借。「狐假虎威」指狐狸借老虎的威风吓走其他野兽。＃典出《尹文子》逸文。后用「狐假虎威」比喻藉著有权者的威势欺压他人、作威作福。_x000D_\n△「狗仗人势」", "source": "＃《尹文子》逸文（据《太平御览．卷四九四．人事部．诡诈》引）", "example": "他只是董事长身边的司机，却常狐假虎威地发号施令。", "story": "「狐假虎威」最早的典源出自于《尹文子》，后来有多本文献引及，其中最能表示「狐假虎威」意思的是《战国策》。《战国策》所记载的故事是这样的：战国时，昭奚恤是楚国有名的大将，威震四方。楚宣王便问群臣：「我听说北方国家都很怕昭奚恤，是这样吗？」群臣都无言以对，只有江一打了个比方说：「老虎专门捕猎各种动物为食，有一天抓到一只狐狸，狐狸说：『你敢吃我吗？天帝已命我治理百兽，你若吃我就是违逆天帝的命令。如果不相信，可以走在我后面，看看其他动物见到我有什么反应。』于是老虎便半信半疑的跟在狐狸后面，所有动物看到都吓得逃走。老虎以为牠们真的是怕狐狸，而不知道其实野兽们怕的是牠自己。今天大王您有五千里的领地，有超过百万的大军，但统御军队的是昭奚恤，所以北方诸国其实怕的不是昭奚恤本人，而是您的军队啊！犹如野兽们怕的是老虎，而不是狐狸一样。」后来这个故事被浓缩成「狐假虎威」，用来比喻藉著有权者的威势欺压他人、作威作福。"},
  {"name": "挥汗成雨", "cid": 296891, "pid": 11701983, "num": 168, "meaning": "挥：洒，泼。用手抹汗，汗洒下去就跟下雨一样。形容人多。", "source": "春秋・齐・晏婴《晏子春秋・杂下九》：“齐之临淄三百闾，张袂成阴，挥汗成雨，比肩继踵而在，何为无人？”", "example": "正是摩肩如云，～的时候，烦渴的了不得。（清・曾朴《孽海花》第十回）", "story": "战国时，苏秦到齐国游说。他形容齐都临淄多么繁华：路上行人肩膀挨着肩膀，抬起袖子能遮成阴天，大家挥一把汗就像下了雨。这就是“挥汗成雨”的来历，用来形容人多得不得了。"},
  {"name": "疾风知劲草", "cid": 296891, "pid": 11701984, "num": 169, "meaning": "犹「疾风劲草」。见「疾风劲草」条。01.《东观汉记．卷一〇．王霸列传》：「颍川从我者皆逝，而子独留，始验疾风知劲草。」（源）02.《后七国志乐田演义》第一七回：「今燕城俱被齐兵复去，我若也随众归齐，何以见疾风知劲草，乱世识忠臣？」", "source": "", "example": "", "story": "此处所列为「疾风劲草」之典故说明，提供参考。「疾风劲草」原作「疾风知劲草」。据《东观汉记．卷一〇．王霸列传》载，新朝王莽末年，刘秀起兵反抗暴政，王霸在他经过颍川时，和几个朋友一起加入他的麾下。开始的几次战役都进行得很顺利，可是在军队进入河北后遭到挫败，当时和王霸一起加入的朋友纷纷离去，于是刘秀对王霸说：「从颍川开始跟随我的人都离去了，只有你还在，这证明了『经过猛烈大风的吹袭，才知道坚韧的草挺立不倒』的道理。」后来「疾风劲草」这句成语就从这里演变而出，用来比喻在艰难困苦的环境下，才能考验出人的坚强意志和节操。出现「疾风劲草」的书证如《周书．卷三四．裴宽列传》：「太祖顾谓诸公曰：『被坚执锐，或有其人，疾风劲草，岁寒方验。裴长宽为高澄如此厚遇，乃能冒死归我。』」"},
  {"name": "鞠躬尽瘁", "cid": 296891, "pid": 11701986, "num": 170, "meaning": "「鞠躬」，弯身以示敬慎。语出《论语．乡党》。「尽瘁」，竭尽辛劳。语出《诗经．小雅．北山》。「鞠躬尽瘁」意谓恭谨戒慎，不辞劳病地贡献心力。或以为典故出自三国蜀．诸葛亮〈后出师表〉。\n△「摩顶放踵」", "source": "「鞠躬」：《论语．乡党》*1*\n「尽瘁」：《诗经．小雅．北山》*1*", "example": "他可以为公事鞠躬尽瘁，牺牲所有假期。", "story": "「鞠躬尽瘁」系由「鞠躬」及「尽瘁」二语组合而成。\n「鞠躬」见于《论语．乡党》，文中叙述孔子在进入君门的时候，态度很恭谨，仿佛国君的门容不下他的样子。他不站在门的中央，走路时不踏上门槛。\n「尽瘁」则见于《诗经．小雅．北山》，诗歌内容是行役者对国君分配劳役不均所发出的感叹。文中说到有些人安逸地在家休息，有些人却因为尽力于国事乃至于生病；有些人每天过著高枕无忧的日子，但有些人却必须日夜不停地奔走四方。后来这两个典源被合用成「鞠躬尽瘁」，用来表达恭谨戒慎，不辞劳病地贡献心力。在三国蜀诸葛亮〈后出师表〉中，诸葛亮在考察了当时的局势环境后，认为以他的能力，以及许多未能预料的演变，都不足以能够抵抗强敌。尽管如此，他仍表明了自己的决心，只求竭尽所能。原文中的「臣鞠躬尽力，死而后已，至于成败利钝，非臣之明所能逆睹也」，其实就是现在常用的「鞠躬尽瘁」的意思。"},
  {"name": "举案齐眉", "cid": 296891, "pid": 11701987, "num": 171, "meaning": "将放置饭菜的木盘高举，与眉平齐，为东汉孟光对其夫梁鸿敬爱的表示。＃典出《东观汉记．卷一八．梁鸿列传》。后用「举案齐眉」比喻夫妻相敬如宾。", "source": "＃《东观汉记．卷一八．梁鸿列传》", "example": "夫妻之间能举案齐眉，更见一份亲密。", "story": "东汉有个读书人梁鸿，个性耿介。因为世道混乱，不愿侍奉权贵，所以放弃作官。娶了妻子孟光后，两人就移居吴地，依托在大户人家皋伯通家中，受雇为人舂米。每当梁鸿工作结束回到家中，妻子总是准备好了食物，用食盘端到他面前，并高举至与眉齐，不敢与丈夫平视，充分表现出对丈夫的敬爱。由于她这样的举动，也让皋伯通察觉到梁鸿的人品必有过人之处，绝非泛泛之辈，而对他另眼看待。后来这个故事被浓缩成「举案齐眉」，用来比喻夫妻相敬如宾。"},
  {"name": "举足轻重", "cid": 296891, "pid": 11701989, "num": 172, "meaning": "一举脚就会影响两边的轻重。形容所居地位极为重要，一举一动皆足以影响全局。语本《后汉书．卷二三．窦融列传》。", "source": "《后汉书．卷二三．窦融列传》", "example": "他是政坛的大老，一言九鼎，举足轻重。", "story": "据《后汉书．卷二三．窦融列传》载，更始年间，窦融据河西，后来刘玄兵败，得知东汉光武帝刘秀在洛阳即位，而天水的隗（ㄨㄟˇ）嚣这时也派人来游说他加入，于是他与河西五郡太守商议后决定归附汉朝，便派长史刘钧送信到洛阳。刘钧途中正巧遇到刘秀派出要送信到河西的使者，于是和他一起回去见刘秀。刘秀很高兴，不但宴请刘钧，还写了一封诏书给窦融说：「你将河西治理得物富民丰、兵强马壮，使百姓能安居乐业，这些功绩我都听说过，只可惜两地相隔太远！见到刘钧之后，我已经知道你的心意。现今益州被公孙述占领，天水则被隗嚣占据，如果和他们打起仗来，胜败关键就掌握在将军你的手上，只要一举脚，不管是放在左边或右边，就有轻重的分别，将会影响两边的情势。」后来「举足轻重」这句成语就从这里演变而出，用来形容所居地位极为重要，一举一动皆足以影响全局。另外《史记．卷九二．淮阴侯列传》记载，因为龙且被齐王韩信杀死，项王害怕，于是派武涉前去见韩信说：「当今二王之事，权在足下。足下右投则汉王胜，左投则项王胜。」此段文字虽也有「举足轻重」的意思，但就成语语型而言，仍以前引之《后汉书．卷二三．窦融列传》较为贴切。"},
  {"name": "卷土重来", "cid": 296891, "pid": 11701990, "num": 173, "meaning": "即「卷土重来」。见「卷土重来」条。01.唐．杜牧〈题乌江亭〉诗：「胜败兵家事不期，包羞忍耻是男儿。江东子弟多才俊，卷土重来未可知。  」（源）", "source": "", "example": "", "story": "此处所列为「卷土重来」之典故说明，提供参考。「卷土重来」原作「卷土重来」。杜牧为晚唐诗人。晚唐社会黑暗、政治腐败、藩镇割据、宦官专权，面对这样的环境，杜牧作了不少感时伤事或藉古讽今的诗。这首〈题乌江亭〉诗，为杜牧过乌江亭时所作。乌江亭据传为当年项羽自刎的地方。楚汉相争，项羽自立为「西楚霸王」，与刘邦争天下，战无不利。可是垓下一战，楚军瓦解，项羽突围至乌江岸边，本可渡江，但他自认愧对江东父老而羞愤自杀。后人多赞赏项羽的气节，但杜牧却不以为然。本诗首句即开门见山地点出，胜败乃兵家常事，能忍辱负重的才是「男儿」，所以，项羽这样一遭遇失败便以死作为了断，根本是一种怯懦的行为。其实他所率领的一批江东子弟，其中不乏才俊，若是能重振旗鼓，谁胜谁败都还说不定呢！可惜的是项羽偏偏选择了以死逃避，断送了一切的可能。后来「卷土重来」这个成语，就从「卷土重来未可知」这一诗句摘录而成，用来比喻事情失败后，重新整顿，再次来过。亦用于比喻恢复旧有的局面、局势。出现「卷土重来」的书证如《明史．卷二七九．吴贞毓列传》：「章下廷议，李定国等言：『行人议是。但前途尚宽，暂移跸，卷土重来，再图恢复，未晚也。』乃扈王入缅甸。」"},
  {"name": "开诚布公", "cid": 296891, "pid": 11701991, "num": 174, "meaning": "敞开胸怀，提出公正客观的见解。比喻诚意待人，坦白无私。语本《三国志．卷三五．蜀书．诸葛亮传》。\n△「开心见诚」", "source": "《三国志．卷三五．蜀书．诸葛亮传》", "example": "她这一番开诚布公的话，证实了她对他的心意。", "story": "诸葛亮是三国时蜀国的政治家兼军事家。东汉末年，他隐居耕读，刘备听说他的才能，于是三顾茅庐，登门请求诸葛亮出来从政。诸葛亮执政期间，路不拾遗，夜不闭户。陈寿在《三国志》的〈诸葛亮传〉中，对诸葛亮非常推崇，他赞扬诸葛亮在当丞相时，能够「开诚心，布公道」，以真心对待部属，处事大公无私，所以受到大家的爱戴。即便他「用法严峻」，但人民虽畏惧却没有怨言。军政大权都操在他的手中，但后主对他丝毫不疑。因此，陈寿认为他是跟管仲、萧何差不多的人物。后来「开诚布公」这句成语就从这里演变而出，用来比喻诚意待人，坦白无私。"},
  {"name": "开卷有益", "cid": 296891, "pid": 11701992, "num": 175, "meaning": "「开卷有益」之「益」，典源作「得」。打开书册阅读，必有所领悟获得。※＃语本《宋书．卷九三．隐逸列传．陶潜》。后用「开卷有益」指打开书本阅读，即能得到好处。", "source": "※＃《宋书．卷九三．隐逸列传．陶潜》*1*", "example": "趁年轻多读些书，开卷有益！", "story": "「开卷有益」原或作「开卷有得」。陶潜，东晋浔阳柴桑人，陶侃的曾孙，一名渊明。陶渊明出自显宦之家，书香门弟，虽然家道中落，但家中藏书丰富，家庭教育良好，养成他爱好读书的习惯。他曾说：「少年来好书，偶爱闲静，开卷有得，便欣然忘食。」陶渊明从小即喜爱阅读，当读到对书中文义有所领悟时，便高兴得忘了进食。由此可见他以阅读来丰富他的精神世界。后来「开卷有益」这句成语就从这里演变而出，用来指打开书本阅读，即能得到好处。在宋．王辟之的《渑水燕谈录》里记载了一则「开卷有益」的例子：宋太宗赵光义非常喜欢读书，但历代典籍文史资料实在太多，所以他命令当时的大文学家李昉主持编辑一套集历代图书资料精华的百科全书。李昉等学者历经七年的努力终于编成。宋太宗对这部书非常重视，同时为它取名为《太平御览》，规定自己要在一年内看完它，就算政务繁忙，也一定要找时间补读。大臣们怕他太劳累，常劝他多休息，但宋太宗却说：「『开卷有益』，经常看书，总是有好处的，我一点也不觉得累。」是目前最早出现「开卷有益」完整词形的书证，因此也有人认为典源当出于此。"},
  {"name": "开门揖盗", "cid": 296891, "pid": 11701993, "num": 176, "meaning": "揖，请。「开门揖盗」比喻引进坏人，自招祸患。语出《三国志．卷四七．吴书．吴主权传》。_x000D_\n△「引狼入室」", "source": "《三国志．卷四七．吴书．吴主权传》", "example": "这种恶人你竟请来担任要职，不是等于开门揖盗，自找麻烦吗？", "story": "据《三国志．卷四七．吴书．吴主权传》载，三国之时，孙策率军渡江，平定了江东之地，后来在一次战役中，不慎中箭，伤重不治，临死之前，他将军国大事全部交付其弟孙权。孙权因为兄长死去之事，非常地难过，忙于治丧之事，而忽略了军国大事。长史张昭看到了这种情形，就劝他说︰「当今世间战乱频仍，像豺狼般的乱贼满道，虽然你为了去世的兄长治丧是人之常情，但如果在这样的非常时刻，你仍只顾遵守礼制，不管国家大事，就好像把门打开，请盗贼进到家中，必然会招来祸患，实在不是明智之举啊！」孙权听从了张昭的建议，便脱掉丧服，换上军装，前往巡视军队。后来「开门揖盗」这句成语就从这里演变而出，用来比喻引进坏人，自招祸患。"},
  {"name": "开天辟地", "cid": 296891, "pid": 11701994, "num": 177, "meaning": "古代神话传说：盘古氏开辟天地，开始有人类历史。后常比喻空前的，自古以来没有过的。", "source": "《隋书・音乐志中》：“开天辟地，峻岳夷海。”", "example": "感谢那些～，披荆斩莽的英雄们！只有你们才配承受这最高的幸福，最大的快乐。（刘白羽《从富拉尔基到齐齐哈尔》）", "story": "传说远古时天地浑沌像个大鸡蛋，盘古在里面睡着。一万八千年后他醒来，用斧头劈开浑沌，轻的气上升成天，重的下沉成地。盘古顶天立地，死后身体变成山川草木。这就是开天辟地的故事。"},
  {"name": "刻舟求剑", "cid": 296891, "pid": 11701995, "num": 178, "meaning": "剑掉入水中，在船舷刻上记号，待船停止后仍从记号处下水寻剑。比喻拘泥固执，不知变通。典出《吕氏春秋．慎大览．察今》。\n△「守株待兔」、「胶柱鼓瑟」", "source": "《吕氏春秋．慎大览．察今》", "example": "因应各种状况，我们不宜刻舟求剑，不知变通。", "story": "战国时，秦国丞相吕不韦在《吕氏春秋》一书中，阐述君王治理国政的道理。他认为君王治国应要符合时宜，不能一味沿袭旧法，因为环境会随著时间改变。他举了一个例子：楚国有人渡江时，剑掉到水里，他便很快地在船身上刻了记号，说：「我的剑就是从这里掉下去的。」等到船停了，他就从记号处下水找剑。可是船已经走动了，但落水的剑却不会动，这样找剑，不是很奇怪吗？如果用旧法治理国家，而不考虑时空的转变，就像这个求剑者的行为一样令人困惑。后来这个典源被浓缩成「刻舟求剑」，用来比喻拘泥固执，不知变通。"},
  {"name": "空洞无物", "cid": 296891, "pid": 11701996, "num": 179, "meaning": "空空洞洞，没有什么内容。多指言谈、文章极其空泛。", "source": "南朝・宋・刘义庆《世说新语・排调》：“王丞相枕周伯仁膝，指其腹曰：‘卿此中何所有？’答曰：‘此中空洞无物，然容卿辈数百人。’”", "example": "出了口吻、技巧和声调之外，八股文里是～的。（朱自清《经典常谈・文第十三》）", "story": "东晋时，丞相王导问周𫖮为什么长胖了。周𫖮开玩笑说：我肚子里空洞无物，却能装下你们几百人呢！其实是说他自己大度能容人。后来“空洞无物”多用来形容讲话写文章没有实在内容。"},
  {"name": "空前绝后", "cid": 296891, "pid": 11701997, "num": 180, "meaning": "比喻超越古今，无与伦比。语本《晋起居注》。", "source": "《晋起居注》（据《文选．卷五九．碑文．齐故安陆昭王碑文》李善注引）", "example": "九一一大地震造成的损失，可谓空前绝后。", "story": "「空前绝后」原作「超前绝后」，意思是指成就超越古今，无人能比。此语较早见于《晋起居注》。晋安帝在诏书上写著：「这样伟大的功绩，真是超越古今，没有其他人能够比得上啊！」在唐人张怀瓘的《书断》中，在称赞草圣张芝时，也有同样的用法。唐朝人认为草书的笔法，始自东汉的张芝。张芝曾学书于崔瑗、杜度。他勤练书法，从不择纸笔，只要家中的日常用品都可作为模拟书写的工具；平常都对著铜镜执笔，来纠正自己的姿势。他为了方便练习书法，又在家门前挖了一个大池塘，习字后便将毛笔和砚台在池中清洗，年复一年，池塘的清水竟然全被染黑，称为「墨池」。张芝的天赋加上后天的努力，让他的成就青出于蓝，更胜于蓝，超越了两位老师，获得了「草圣」的美誉，当时的人珍惜张芝的墨宝到了寸纸不遗的地步。张怀瓘更在《书断》中称赞张芝的书法成就「超前绝后，独步无双」。  后来演变成「空前绝后」这句成语，「空前」就是超越前人，前人无可比拟的意思。「空前绝后」就是比喻超越古今，无与伦比。"},
  {"name": "空中楼阁", "cid": 296891, "pid": 11701998, "num": 181, "meaning": "空中显现的楼台观阁。※语或本唐．宋之问〈游法华寺〉诗。后用「空中楼阁」来比喻思想明澈通达。或比喻虚构的事物或不切实际的幻想。\n△「海市蜃楼」", "source": "※唐．宋之问〈游法华寺〉诗（据《全唐诗．卷五三．宋之问》引）", "example": "你提出来的构想就像空中楼阁，不切实际。", "story": "「空中楼阁」指的是在空中显现的楼台观阁。这句话可用来形容楼阁建筑的高耸入云，例如唐代宋之问〈游法华西寺〉诗所说的「空中结楼殿，意表出云霞」。法华山位于浙江西北，有晋代高僧法华的灵迹及法华泉，山下有法华寺，建筑极其雄伟。宋之问先形容高耸的法华山，就像当年佛陀说法所在的灵鹫山那样庄严圣洁，其次形容壮观的法华寺在云海间掩映，就好像是盖在半空中的殿宇一样，那样的虚幻、空灵。楼阁既高，自然可眺望四方，所以「空中楼阁」可以比喻思想明澈通达。又因为楼阁现于云端之上，像似虚幻、不著实际的建筑物，所以「空中楼阁」也可用来比喻虚构的事物或不切实际的幻想。"},
  {"name": "口蜜腹剑", "cid": 296891, "pid": 11701999, "num": 182, "meaning": "口中有蜜，肚子里却藏著剑。比喻一个人嘴上说得好听，事实上却内心险恶，处处想陷害别人。语本五代周．王仁裕《开元天宝遗事．肉腰刀》。_x000D_\n△「笑里藏刀」", "source": "五代周．王仁裕《开元天宝遗事．肉腰刀》", "example": "他是个口蜜腹剑的伪君子，不能深交。", "story": "唐玄宗一朝是唐代由盛转衰的关键时期。玄宗执政初期，因得姚崇、宋璟等贤相，所以缔造了开元盛世；后来又因为信任李林甫、杨国忠等奸臣，而导致了安史之乱。李林甫生性狡猾，对于他的政敌，经常以甜言蜜语引诱对方上当，再暗中陷害对方。天宝时，玄宗起用李适之为宰相，李林甫心生不满，便想了一个方法打算除掉李适之。由于当时国家财政困难，为了筹措财源，玄宗和李适之都忙得焦头烂额。有一天，李林甫对李适之说：「我刚刚得知一个消息，在华山发现了金矿，如果加以开采，就可以解决国家的财务困境。这个消息皇上还不知道，请李丞相赶紧上书向皇上建议开采，皇上知道了一定会很高兴的。」李适之不疑有他，立刻上书玄宗，奏请开采华山的金矿。玄宗看了李适之的奏章，本来想要立刻批准，没想到向李适之提出这个建议的李林甫却劝阻玄宗，他说：「皇上，华山有金矿的事情我早就知道了，可是我却迟迟没有上奏，实在是因为华山的风水是王气所在，如果随便加以开采，要是破坏了王气，那对皇上及国家都相当不利啊！」玄宗听信了李林甫的话，认为李适之治国欠周详，不久便罢免其相位。林李甫就靠类似方法，顺利地除掉了许多政敌，终于得到玄宗的完全信任，为相十九年，却将唐朝盛世带往衰败之路。由于李林甫为人阴险，妒贤嫉能，所以当时的人都称他为「肉腰刀」，又说他的嘴里有蜜，腹中藏剑。后来「口蜜腹剑」这句成语就从这里演变而出，比喻一个人嘴上说得好听，事实上内心险恶，处处想陷害别人。"},
  {"name": "口若悬河", "cid": 296891, "pid": 11702000, "num": 183, "meaning": "说起话来像瀑布一样滔滔不绝，比喻能言善辩。＃语本南朝宋．刘义庆《世说新语．赏誉》。", "source": "＃南朝宋．刘义庆《世说新语．赏誉》", "example": "没有口若悬河的本事，怎能成为演说家？", "story": "「口若悬河」原作「悬河写水」。晋朝的郭象是玄学的集大成者，喜好《老》、《庄》，十分有才学，能言善辩，口齿伶俐，曾为《庄子》作注，流传于后世。在《世说新语．赏誉》中，记载一段太尉王衍对郭象的评语，他说：「郭象说话议论时，就像山上直泻而下的瀑布，源源不绝的灌注而下，好像永远不会枯竭的样子。」后来「口若悬河」这句成语就从这里演变而出，比喻说话滔滔不绝，能言善辩。出现「口若悬河」的书证如宋．赵蕃〈赠耆英见过〉诗四首之一：「髯曾暇能过我，诵诗口若悬河。」"},
  {"name": "脍炙人口", "cid": 296891, "pid": 11702001, "num": 184, "meaning": "脍，细切肉；炙，烤肉。脍、炙皆人间美味，「脍炙人口」指美味的食物人人爱吃，或比喻美妙的诗文为人所赞赏、传诵。语出唐．林嵩〈周朴诗集序〉。后亦用「脍炙人口」比喻事物精妙而备受称诵。", "source": "唐．林嵩〈周朴诗集序〉（据《全唐文．卷八二九．林嵩》引）", "example": "桌上摆满了脍炙人口的佳肴，令人垂涎欲滴。", "story": "唐僖宗干符年间，周朴因遇黄巢之乱，不屈从黄巢而被杀。朴死后，僧人楼浩搜其诗百篇，编成《周朴诗集》二卷。唐人林嵩为《周朴诗集》写了一篇序文，文中说到周朴一生淡泊名利，放纵心灵于山林宇宙之中，视富贵如浮云。与当时的建州刺史李频、处士方干结为诗友，其间往来之诗作，都是「脍炙人口」，为人所称美传诵的好作品。文中「脍炙人口」原用于比喻美妙的诗文为人所赞赏、传诵，后则亦用来比喻事物精妙而备受称诵。"},
  {"name": "滥竽充数", "cid": 296891, "pid": 11702002, "num": 185, "meaning": "竽，古代一种吹奏乐器。「滥竽充数」意谓不会吹竽的人，混杂于众多乐工中凑数。典出《韩非子．内储说上》。后用「滥竽充数」比喻没有真才实学的人，混在行家中充数。亦用于比喻拿不好的东西充场面。亦用于自谦，比喻自己才德不足。_x000D_\n△「鱼目混珠」", "source": "《韩非子．内储说上》", "example": "不怕你笑，我们团里滥竽充数者大有人在。", "story": "《韩非子．内储说上》中有一则故事：战国时，齐宣王喜欢听竽的合奏，所以每次都要三百多个乐工一同演奏。有位南郭先生，虽然不会吹竽，但因为知道齐宣王的这个嗜好，便请求齐宣王让自己参加这个乐队，宣王也很高兴地答应了。每当众多乐工一起合奏的时候，南郭先生就混在数百人的吹竽队伍中，有模有样地装出吹奏的样子，没人发现真相，他也因此能获得很好的待遇。宣王死后，湣王继位，湣王虽然也喜欢竽的吹奏声，但他喜欢的却是独奏，所以命乐工一个个轮流表演。南郭先生得到了这个消息，知道再也无法蒙混过关，只好逃出宫去。后来这个故事被浓缩成「滥竽充数」一语，用来比喻没有真才实学的人，却混在行家中充数，或比喻拿不好的东西充场面。有时也用来当成自谦之辞，比喻自己才德不足。"},
  {"name": "狼狈为奸", "cid": 296891, "pid": 11702003, "num": 186, "meaning": "狼与狈相互搭配，伤害人命。语本唐．段成式《酉阳杂俎．卷一六．毛篇》。后用「狼狈为奸」比喻互相勾结做坏事。", "source": "唐．段成式《酉阳杂俎．卷一六．毛篇》", "example": "当地米商狼狈为奸，联手哄抬物价。", "story": "根据唐代段成式《酉阳杂俎》的记载，相传狼和狈是两种外形上很相似的野兽，只是狈的前脚非常的短，因此一定要骑在两只狼上面才能行走，没有了狼，根本就无法行动，所以世人常将行事无法顺利推展，处境困顿窘迫的情况称为「狼狈」。狼和狈会联手做坏事。听说，曾经有人独自经过一处人烟罕至的地方，遇见了几十只的狼，情急之下，就赶紧爬到草堆上。其中有两只狼就钻进了一个洞穴中，背出一只老狼来，老狼来到草堆下，用嘴拔除草堆上的草，其他的狼看了，也跟著学牠的动作去拔草，眼看著草堆就要垮下来了，正巧遇到一群猎人经过这里，把这个人救了出来。事后这些人一起挖掘这个洞穴，在里面抓到了一百多只的狼，就将牠们杀死，而大家都怀疑那只老狼可能就是狈。后来「狼狈为奸」这句成语就从这里演变而出，用来比喻彼此互相勾结做坏事。"},
  {"name": "劳苦功高", "cid": 296891, "pid": 11702004, "num": 187, "meaning": "出了很多力，吃了很多苦，立下了很大的功劳。", "source": "西汉・司马迁《史记・项羽本纪》：“劳苦而功高如此，未有封侯之赏，而听细说，欲诛有功之人，此亡秦之续身。”", "example": "这是决战的最后五分钟了！这一班～的“英雄”，手颤颤地举着“胜利之杯”，心头还不免有些怔忡不定。（茅盾《子夜》十五）", "story": "鸿门宴上，项羽的谋士想杀刘邦。刘邦手下樊哙闯进门，对项羽说：沛公先入咸阳，却把好处留给您，自己驻军霸上，劳苦功高，您怎可听小人之言杀他？项羽无言以对。后用它赞美有功劳的人。"},
  {"name": "老马识途", "cid": 296891, "pid": 11702005, "num": 188, "meaning": "老马认得走过的路。典出《韩非子．说林上》。后用「老马识途」比喻有经验的人对情况比较熟悉，容易把工作做好。", "source": "《韩非子．说林上》", "example": "放心吧！小王老马识途，不会迷路。", "story": "春秋时，周室衰微，齐桓公以管仲为相，对内提升国力，对外率诸侯尊崇周天子的地位，阻止蛮族入侵，成为春秋时期五位霸主中实力最为强大的一位。据《韩非子．说林上》载，有一次管仲、隰（ㄒㄧˊ）朋随著桓公去征伐孤竹国，由于去的时候是春天，而回来的时候却已经是冬天，景物变化很大，让他们迷失了回国的方向。正当众人无计可施时，管仲想起老马可以记得以前走过的路。于是挑选了几匹老马，让牠们在前面任意行走，军队跟在后面，果然找到了原路回国。后来这个故事被浓缩成「老马识途」，比喻有经验的人对情况比较熟悉，容易把工作做好。"},
  {"name": "乐不可支", "cid": 296891, "pid": 11702006, "num": 189, "meaning": "快乐到无法受得住，形容快乐到了极点。＃语出《东观汉记．卷一五．张堪列传》。_x000D_\n△「喜不自胜」、「乐不可言」", "source": "＃《东观汉记．卷一五．张堪列传》", "example": "老师宣布今天小考取消，全班同学都乐不可支！", "story": "张堪，字君游，东汉南阳宛人。六岁到长安读书，以研究梁丘《易》学为主，因为才学高，在京师人称「圣童」。光武帝初即位时，受命与大司马吴汉一起讨伐在蜀自立为王的公孙述，后来公孙述战死，蜀国投降。吴汉以张堪为先遣进入成都，安抚官吏百姓。他将公孙述所收藏的珍珠宝玉，全部登录在簿册里上呈朝廷，并未将之据为己有。他为官清廉，卸任离职时，只带著简单的布包袱，乘坐破旧的车子离开。之后和杜茂一起在高柳这个地方打败匈奴，官拜渔阳太守。任内将渔阳这个地方治理得很好，百姓都愿意听从他的指挥。开垦稻田八千余顷，教导百姓耕种的技术，使得百姓的生活变得富裕起来。于是民间就流传起这么一首童谣：「桑树没有附带小枝芽，禾麦都结两株穗。张堪当官执政，人民生活富有都快乐极了。」后来「乐不可支」被用来形容快乐到了极点。"},
  {"name": "乐此不疲", "cid": 296891, "pid": 11702007, "num": 190, "meaning": "特别喜好做某些事，而不觉得厌烦、疲倦。语本《后汉书．卷一．光武帝纪下》。", "source": "《后汉书．卷一．光武帝纪下》", "example": "他是一个爱唱歌的人，经常自编自唱，乐此不疲。", "story": "《后汉书．卷一．光武帝纪下》提到：光武帝刘秀历经长期征战，了解到战乱已久，天下疲乏。为了让百姓安居乐业，因此非常努力于朝政，每天清晨上朝处理国事，往往到太阳西斜时才结束。另外也经常将文武百官聚在一起，谈论经书义理，直到半夜才睡。皇太子见光武帝勤劳不懈，怕他伤了身子，于是趁他有空的时候劝说：「陛下您有夏禹、商汤的圣明，却没黄帝、老子的养生之道，希望您多多爱惜养护身体，悠闲自在地过著安宁的生活。」光武帝则回应：「我非常喜欢做这些事，并不觉得疲累。」后来「乐此不疲」这句成语就从这里演变而出，用来指特别喜好做某些事，而不觉得厌烦、疲倦。"},
  {"name": "乐极生悲", "cid": 296891, "pid": 11702008, "num": 191, "meaning": "欢乐到了极点，往往会转生悲哀。＃语本《淮南子．道应》。", "source": "＃《淮南子．道应》*1*", "example": "享乐应该有所节制，免得乐极生悲。", "story": "「乐极生悲」原作「乐极则悲」。《淮南子》一书中，记录了先秦时代孔子和弟子参观祠庙的情形：孔子和弟子参观鲁桓公庙，看到一种叫「宥卮」的盛酒器具。孔子说：「我之前就听说过『宥卮』这种酒器，今天终于看到了！」孔子要弟子拿水来，把水灌进「宥卮」。水灌到中间时，本来倾斜的「宥卮」就变正了，水一灌满，「宥卮」马上就翻倒了。孔子看了，脸色一变，借此对弟子们做机会教育说：「从这儿可以看到『持盈』的道理。」子贡听了便问孔子什么叫做「持盈」的道理，孔子说：「事物发展到了极盛，就会转而衰退；欢乐到了极点，就会产生悲哀；太阳到了正午，就会开始西下；月亮过了满月，就会开始缺损。这也就是所谓的物极必反，因此凡事应力求合于中庸之道，凡事适可而止，才能守成。」后来「乐极生悲」这句成语就从这里演变而出，用来指欢乐到了极点，转而发生悲哀。"},
  {"name": "罗雀掘鼠", "cid": 296891, "pid": 11702010, "num": 192, "meaning": "原指张网捉麻雀、挖洞捉老鼠来充饥的窘困情况，后比喻想尽办法筹措财物。", "source": "《新唐书・张巡传》：“至罗雀掘鼠，煮铠弩以食。”", "example": "快饿死者，～，粮食罄尽，转为沟瘠是也。（严复《有如三保》）", "story": "唐朝安史之乱，张巡守睢阳城，被敌人围困很久，城里粮食吃光了。士兵们先吃战马，又张网捉麻雀、挖洞找老鼠充饥，仍誓死不投降。后来“罗雀掘鼠”形容陷入绝境、饥饿难忍。"},
  {"name": "洛阳纸贵", "cid": 296891, "pid": 11702011, "num": 193, "meaning": "由于左思的〈三都赋〉，时人竞相传写，因而洛阳为之纸贵。典出《晋书．卷九二．文苑列传．左思》。后用「洛阳纸贵」形容著作风行一时，流传甚广。\n△「都城纸贵」", "source": "《晋书．卷九二．文苑列传．左思》", "example": "这部作品印行后，一时洛阳纸贵。", "story": "西晋的大文学家左思，是一个相貌木讷、口齿不清的人，因此没有什么朋友，尽管文笔出众，也不被当时的人们所重视。左思对于写作文章十分用心，他曾经花了一年的时间写成〈齐都赋〉，描写齐国首都临淄的风光。接著他又想写一篇关于三国时代魏、蜀、吴都城的文章，即〈三都赋〉。这时左思的妹妺左芬正好被选入宫，左思就藉这个机会搬到人文荟萃的京师洛阳居住。因为左思从未去过蜀国的成都，所以他就去拜访当时的大文人张载，请教有关成都的风土民情。为了写成〈三都赋〉，左思花了十年的时间构思，他的家中到处挂著纸笔，连厕所和篱笆上都不例外，只要一有灵感，他便立刻提笔写下。在创作的过程中，左思又觉得自己的学问不足，便向朝廷请求担任掌管图书的秘书郎一职，以便翻阅各种书籍，作为写作的材料。后来〈三都赋〉完成，却并未得到时人的重视。左思认为自己的文笔并不比班固、张衡差，恐怕是当时的人不喜欢他的形貌，所以也看不起他的文章。左思听说皇甫谧是位著名的学者，便拿自己的作品去向他请教。皇甫谧看了〈三都赋〉之后非常欣赏，并为左思写了一篇序。后来张载为魏都的部分作注，刘逵也为蜀都、吴都两部分作注，卫权又写了略解。连官至司空的大文人张华，都对左思的〈三都赋〉大加赞赏，认为左思的成就不输给班固、张衡等大文人。由于这些文人学者的推荐，左思的这篇杰作便很快地在京城洛阳流传开来，人们竞相抄录，以致洛阳的纸价上涨。后来这个故事被浓缩成「洛阳纸贵」，用来形容著作风行一时，流传甚广。"},
  {"name": "马革裹尸", "cid": 296891, "pid": 11702012, "num": 194, "meaning": "即「马革裹尸」。见「马革裹尸」条。01.《东观汉记．卷一二．马援列传》︰「男儿要当死于边野，以马革裹尸还葬耳，何能卧床上，在儿女子手中耶？」（源）02.《隋唐演义》第三七回：「若说疾病，大丈夫死当马革裹尸，怎宛转床席，在儿女子手中？」", "source": "", "example": "", "story": "此处所列为「马革裹尸」之典故说明，提供参考。「马革裹尸」原作「马革裹尸」。「尸」，同「尸」。这是和马援有关的一句成语。马援（西元前１４∼西元４９），字文渊，东汉茂陵（今陕西省兴平县东北）人。初依隗嚣，后归光武，拜伏波将军，平交趾，世称「马伏波」。马援在王莽统治的时候，曾经做过扶风郡的督邮，有一次他负责押解一批犯人，途中他因为同情这些犯人，就擅自释放了他们，自己也丢了官，逃到北地郡。马援在那边以农牧为生，因为经营得法，几年之后变得相当富裕。但他不愿成为一个守财奴，就把财产送给亲人朋友。后来马投靠光武帝，建立了许多的战功，拜伏波将军，封为新息侯。公元四四年，马援已经五十八岁了，有人劝他应该退休，好好在家安享天年，不要再奔波沙场。但是马援拒绝了，并且很豪迈地说：「现在北方还有匈奴、乌桓为患，我正要去肃清他们。身为男子汉大丈夫，就应该死在沙场上，用马革裹著尸体送回来埋葬，怎么可以躺在床上，死在儿女的手中呢？」平定了匈奴、乌桓之后，马援又前往贵州作战。当地气候炎热，环境恶劣，许多士兵都得了传染病死去，这位老将军也身染重疾。但他仍坚持守在前线，不肯离开，最后终于实现了他战死疆场、马革裹尸的壮志。后来「马革裹尸」被用来比喻英勇作战，效命沙场。"},
  {"name": "毛遂自荐", "cid": 296891, "pid": 11702014, "num": 195, "meaning": "战国时，平原君之门下食客毛遂自荐跟随前往楚国游说。典出《史记．卷七六．平原君虞卿列传．平原君》。后用「毛遂自荐」比喻自告奋勇，自我推荐。\n△「自告奋勇」、「脱颖而出」", "source": "《史记．卷七六．平原君虞卿列传．平原君》", "example": "我进公司是毛遂自荐的。", "story": "据《史记．卷七六．平原君虞卿列传．平原君》载，战国时，秦国出兵攻打赵国，包围了赵都邯郸，情况十分危急，于是赵王派平原君前往楚国，请求援救。平原君打算在其门下食客挑选出二十个文武人才一同前往，但只选出十九个，剩下的都不符合条件。这时，有一个名叫毛遂的人，主动向平原君自我推荐，请求加入前往楚国的行列。平原君问：「你在我门下多久了？」毛遂回答：「三年了。」平原君说：「一个真正有才能的人，就好像一把放在袋子里的锥子一样，立刻就会显露出锋利的锥尖。而你在我门下三年了，我却没听说过你有什么表现，你还是留下吧！」毛遂说：「我现在自我推荐，就是请求你把我放进袋子里，如果早点有这样的机会，那我就不只是露出锥尖而已，而是早就显露出才能，锋芒毕露了！」平原君觉得毛遂说得有道理，就答应让他一同前往。到了楚国，平原君和楚王会谈，从早上到中午，都还没有结果。毛遂于是持剑走到楚王面前，极力说明赵、楚联合抗秦的利害关系。楚王终于被说服，答应赵国愿意出兵援救。于是两国当场歃血为盟，誓守联合抗秦的盟约。毛遂这次不仅帮平原君完成任务，也为国家立下了功劳，让大家对他刮目相看，平原君因此待他为上宾。后来这个故事被浓缩成「毛遂自荐」这个成语，比喻自告奋勇，自我推荐。"},
  {"name": "名落孙山", "cid": 296891, "pid": 11702015, "num": 196, "meaning": "孙山，宋朝人，应试考中最后一名。「名落孙山」，名落于孙山之后，指参加考试或选拔没有被录取。_x000D_\n＃典出宋．范公偁《过庭录》。", "source": "＃宋．范公偁《过庭录》", "example": "你平时不努力，难怪几次考试都名落孙山。", "story": "宋朝时吴地有个读书人叫孙山，他很聪明，生性风趣幽默，又颇有才气，因此人家都叫他做「滑稽才子」。有一年，他要到别郡参加考试，因为同乡某人的儿子也要参加，于是就作伴前往。放榜的结果，同乡人的儿子并没有考取，而孙山则是名列榜单的最后一名。等孙山先起程回乡后，同乡人向他探问自己的儿子考得如何，孙山回答说：「榜上的最后一名是我孙山，而你的儿子更落在孙山的后面呢！」后来这个故事被浓缩成「名落孙山」，用来暗喻应考者落于榜单之外，指应考不中。"},
  {"name": "名正言顺", "cid": 296891, "pid": 11702016, "num": 197, "meaning": "形容名分正当，言词合理。语本《论语．子路》。后用「名正言顺」指所做的事正当而合理，不容置疑。_x000D_\n△「手足无措」", "source": "《论语．子路》", "example": "他所做的事总是名正言顺，所以不曾受到非议。", "story": "春秋卫灵公死后，卫人立蒯聩（ㄎㄨㄞˇ　ㄎㄨㄟˋ）之子辄，是为出公。这一年的六月，赵鞅将蒯聩纳于卫国的戚地，与辄对立。直到出公五年，卫君辄始终违抗父亲蒯聩，诸侯们屡次以这件事责备卫国。这时孔子门人子路等多在卫国任职，卫君辄想要请孔子主持政治。于是子路问孔子：「如果您去主政，要先从哪里下手？」因为卫国正处于一个君不君、臣不臣、父不父、子不子，名实错乱的局面，孔子根本无意辅佐出公，所以说：「如果非做不可的话，就从正名入手吧。」并且说出「名不正，则言不顺」，意思是说：名分不正，所说的话就不合道理。而孔子所讲的此一席话见于《论语．子路》。后来「名正言顺」这句成语就从这里演变而出，用来指所做的事正当而合理，不容置疑。"},
  {"name": "明察秋毫", "cid": 296891, "pid": 11702017, "num": 198, "meaning": "目光敏锐，可看见秋天鸟兽新长的毫毛。＃语本《孟子．梁惠王上》。后用「明察秋毫」比喻洞察一切，能看到极细微的地方。_x000D_\n△「洞若观火」", "source": "＃《孟子．梁惠王上》*1*", "example": "包公办案明察秋毫，宵小歹徒无所遁形。", "story": "传说中，黄帝时代有一位视力极佳的人，名叫离娄，相传他能够把百步之外的野兽细毛看得根根分明。孟子在劝谏齐宣王行仁义之道时，也曾举例说到：「如果有人说，他的力量可以举起百钧之物，却举不起一根羽毛；他的视力能够看见野兽初生的细毛，却看不见整车的木柴，请问大王您会相信他吗？」齐宣王回答：「当然不会。」孟子于是紧接著说：「举不起一根羽毛，或看不见整车的木柴，是因为不肯去做，而不是做不到。现在人民生活困苦，朝不保夕，是因为大王您不肯行仁义之道，让恩泽遍及百姓，而非大王您做不到啊！」后来「明察秋毫」这句成语就从这里演变而出，用来比喻人能洞察一切，能看到极细微的地方。"},
  {"name": "明目张胆", "cid": 296891, "pid": 11702018, "num": 199, "meaning": "张大眼，壮著胆。形容有胆识，无所畏惧。＃语本《史记．卷八九．张耳陈余列传》。后用「明目张胆」比喻肆无忌惮地公然做坏事。\n△「明火执仗」", "source": "＃《史记．卷八九．张耳陈余列传》", "example": "考试时，他竟然明目张胆作弊，一点羞耻心都没有。", "story": "「明目张胆」原作「瞋目张胆」。据《史记．卷八九．张耳陈余列传》载：秦朝末年天下大乱，群雄并起。张耳和陈余都是战国魏人。陈涉（即陈胜，秦阳城人）与吴广起兵反秦时，张、陈二人一起投入陈涉旗下，并得到陈涉的重用。陈中这个地方的父老一致认为陈涉英勇反抗秦朝、光复楚地，功劳很大，希望立他为楚王。陈涉于是询问两人的意见，他们回答说：「秦朝暴虐无道，奴役百姓，搜括钱财，害得平民百姓国破家亡。将军你有胆识，无所畏惧，不顾自己的生死，为天下除害。如今将军刚到陈地，就想称王，是将天下视为私有。希望将军不要称王，赶快引兵西进，立六国的后人为王，结合众人的力量，一举推翻秦朝，如此才能成就帝业。反之，今天在陈中称王，恐怕会失去百姓对你的向心力，无法成就帝业。」但是陈涉听不进去，仍自立为楚王。这里的原文「瞋目张胆」本来是「张大眼，壮著胆」的意思，后来演变出「明目张胆」这句成语，用来形容有胆识，无所畏惧。现在语义则转化为贬义，用来比喻肆无忌惮的公然做坏事。"},
  {"name": "明修栈道，暗度陈仓", "cid": 296891, "pid": 11702019, "num": 200, "meaning": "〖解释〗指刘邦将从汉中出兵攻项羽时，故意明修栈道，迷惑对方，暗中绕道奔袭陈仓，取得胜利。陈仓，古县名，在今陕西省宝鸡市东。", "source": "〖出处〗元・无名氏《暗度陈仓》第二折：“着樊哙明修栈道，俺可暗度陈仓古道。这楚兵不知是智，必然排兵在栈道守把。俺往陈仓古道抄截，杀他个措手不及也。”", "example": "〖示例〗", "story": "楚汉相争，刘邦被逼去汉中。他烧毁栈道表示不回关东。后来韩信献计：派兵明着修复栈道吸引敌人，主力却从小路偷袭陈仓。汉军一举成功。后来用它指表面做一套、暗中做另一套。"},
  {"name": "明哲保身", "cid": 296891, "pid": 11702020, "num": 201, "meaning": "明达事理、洞见时势的人，不参与会带给自己危险的事。语本《诗经．大雅．烝民》。后亦用「明哲保身」指为了个人得失而丧失原则的庸俗处世态度。_x000D_\n△「独善其身」", "source": "《诗经．大雅．烝民》", "example": "事情发生后，大家才对他先知卓见、明哲保身的智慧佩服不已。", "story": "「明哲保身」本来是称颂他人的一句话。明哲，是说一个人明达事理，洞见时势；保身，是说这个人能择安去危，保全其身，远离祸害。出自于《诗经．大雅．烝民》这篇诗。这篇诗是周宣王的大臣尹吉甫，为称颂宣王能任用贤臣仲山甫中兴王室而作。全诗共分八章，在诗的第四章，称赞仲山甫能奉行王命，能了解邦国的好坏；是一个明智，能保其身的人；只知道日夜奋力办事，以事奉宣王。这是「明哲保身」的原义。后来这句成语的语义开始偏向「保身」，明哲的目的是为了保全自身免受外界侵扰，把自身利益得失置于最优先，为了达此目的，可以放弃原本该坚持的原则。例如明代梁辰鱼《浣纱记》第一二出，提到伍子胥报了楚国杀父之仇说：「但大仇既报，吾愿已毕。今欲飘然去国，明哲保身，省得落于奸臣之手。」这里的「明哲保身」显非原来用法，于是「明哲保身」这句成语就从原来积极赞颂的意义，一转变成消极退守的意义了。"},
  {"name": "木人石心", "cid": 296891, "pid": 11702030, "num": 202, "meaning": "木作的人，石造的心。比喻意志坚定，任何外在事物皆不足以动其心。语出《晋书．卷九四．隐逸列传．夏统》。后亦用「木人石心」形容人冷酷无情。", "source": "《晋书．卷九四．隐逸列传．夏统》", "example": "大家都说他是木人石心，对人总是冷冰冰的。", "story": "据《晋书．卷九四．隐逸列传．夏统》载，晋太尉贾充十分欣赏夏统，想留下予以重用，但却被拒绝，于是先后以雄壮威武的军容、仪仗乐队和装扮华丽的妓女来引诱他，但他都不为所动，最后贾充只好放弃，并对人说：「此吴儿是木人石心也。」文中，贾充以「木人石心」一语比喻夏统意志坚定，任何外在事物皆不足以动摇他的心。后来到了宋朝刘斧《青琐高议．别集．卷二．谭意歌传》：「客抚掌大骂曰：『张生乃木人石心也，使有情者见之，罪不容诛。』」 「木人石心」一语语义转变，用来形容人冷酷无情。"},
  {"name": "南柯一梦", "cid": 296891, "pid": 11702031, "num": 203, "meaning": "淳于棼梦中出任南柯太守，历尽人生穷通荣辱，醒来才知道是一场梦。典出唐．李公佐《南柯太守传》。后用「南柯一梦」比喻人生如梦，富贵得失无常。", "source": "唐．李公佐《南柯太守传》（据《唐人小说》引）", "example": "人生得又何叹，失又何怨，恰似南柯一梦罢了。", "story": "唐人李公佐曾经写过一篇传奇小说《南柯太守传》，相传在唐德宗贞元七年九月，东平郡人淳于棼（ㄈㄣˊ）与友人在自家门前的大槐树下饮酒，他因为喝了太多而醉得不醒人事。被两个朋友送回家后，恍惚中作了一个梦。在梦中他被大槐安国国王招为驸马，当了南柯郡太守，广受人民爱戴，不但享尽了荣华富贵，显赫一时，子女也都有很好的发展和归宿。后来公主因病过世，于是淳于棼罢去南柯郡太守的职位回到国都。过了一段时间，国王察觉他心中闷闷不乐，于是要他回家乡探望亲人。淳于棼回到家后，发现自己竟仍旧睡在东厢房。送他回来的两个紫衣使者于是大声呼唤他的名字，他才从梦中清醒过来。醒来后，看到家里的仆人拿著扫帚在打扫庭院，之前送他回来的两个朋友正在洗脚，太阳还没有下山，喝剩的酒也还放在东窗下，一切都没有改变。没想到才作一会儿梦，却好像经历了一辈子，于是他将刚才的梦境告诉了两个朋友，并且回到大槐树下。他们发现树下有个蚁穴，挖开一看，穴中布置竟如同梦里所见的大槐安国一般。自此他从这个梦，领悟到荣华富贵的虚浮，和人世的变化无常。从此一心向道。后来这个故事浓缩成「南柯一梦」，用来比喻人生如梦，富贵得失无常。"},
  {"name": "南山可移，判不可摇", "cid": 296891, "pid": 11702032, "num": 204, "meaning": "终南山可以搬走，判决却不可动摇。形容办案公正坚决，判决不可更改。", "source": "《旧唐书·李元纮传》", "example": "法官叔叔说南山可移，判不可摇，坚决维护了公平。", "story": "唐朝时，太平公主权势很大，霸占了和尚的碾硙。李元纮审理后，把碾硙判还和尚。上级窦怀贞怕得罪公主，让他改判。李元纮在判决书后写：南山或可改移，此判终无动摇。人们赞他刚正不阿。"},
  {"name": "南辕北辙", "cid": 296891, "pid": 11702033, "num": 205, "meaning": "辕，大车前部套在牲口左右两边的木头，用以拖车。辙，车辆驶过留下的痕迹。「南辕北辙」指本要向南，但却驾车往北行，离目的地越来越远。比喻行动和想要达到的目的相反。典出《战国策．魏策四》。后亦用「南辕北辙」比喻二者彼此背道而驰，或比喻遥隔两地。_x000D_\n△「背道而驰」", "source": "《战国策．魏策四》", "example": "想成功却又不努力，岂非南辕北辙？", "story": "据《战国策．魏策四》载，战国时，魏国安厘王想要出兵攻打赵国首都邯郸。臣子季梁得知了这个消息，立即从旅途中折返，想回去劝阻。一回到魏国，季梁顾不得衣服的脏乱和满身的尘埃，便匆匆忙忙地赶去见安厘王，告诉他说：「我在路上遇到一个人，他要去楚国，却驾车往北方走。我问他说你要去南方的楚国，怎么会往北方走呢？他回答说他有很快的马、很多的旅费、很好的马伕，所以绝对可以到达目的地。但实际上因为他是往相反的方向走，马愈快、旅费愈多、马伕愈好，反而使他离楚国愈远。今天大王您想成就霸王之业，取信于天下诸侯，依仗著强大的军力去攻打赵国，想借此扩充领地，提高声望，其实这样的举动愈多，愈失信于天下，离成就霸王事业的心愿也就愈远，这不正如想到楚国却往北方走一样，永远达不到目的！」后来这个故事被浓缩成「南辕北辙」，用来比喻志向和行为背道而驰，现在凡是做「背道而驰」的事，都可以称为「南辕北辙」。另外，这句成语还可引申用来比喻遥隔两地。"},
  {"name": "南州冠冕", "cid": 296891, "pid": 11702034, "num": 206, "meaning": "南方人才中杰出的人。指才识出众的人。", "source": "《三国志·庞统传》", "example": "他在学校里成绩最好，是同学们公认的南州冠冕。", "story": "东汉末年，庞统年轻时去拜访名士司马徽。两人谈了一整天，司马徽十分佩服，说：我住在这里，却不知您这样的奇才，您真是南州的冠冕啊！庞统后来与诸葛亮齐名。人们用此词称赞杰出人才。"},
  {"name": "难兄难弟", "cid": 296891, "pid": 11702035, "num": 207, "meaning": "「难兄难弟」之「难」，有二读，其意义也不同：（一）音ㄋㄢˊ，本义是做弟弟的太好，那么做哥哥的人就「难为兄」，而做哥哥的太好，做弟弟的人就「难为弟」，是形容兄弟二人才德相当，难分高下。语本南朝宋．刘义庆《世说新语．德行》。后世多反用其义，讽刺两人同样差劲，表现差不多。（二）音ㄋㄢˋ，形容同处困境、共同患难的朋友。_x000D_\n△「患难之交」", "source": "南朝宋．刘义庆《世说新语．德行》", "example": "这两位兄弟品学一样好，真可说是难兄难弟。", "story": "东汉时太丘县令陈寔有两个儿子，大儿子叫元方，小儿子叫季方。兄弟两人学问渊博，品德高超，在当地享有盛名，因此有人称他们父子三人为「三君」。有一次，元方的儿子长文，和季方的儿子孝先，互相争论，都觉得自己的父亲是最优秀的。两人各执一词，没有结果，便决定去问祖父陈寔，请他裁决。陈寔听完后，回答说：「元方这个哥哥做得真不容易，而身为弟弟的季方也很不简单。」意思是说季方好得使元方难做他的哥哥，互相匹配；而元方也好得使季方难做他的弟弟，互相匹配。后来「难兄难弟」这句成语就从这里演变而出，用来形容兄弟二人才德相当，难分高下。后世转而用于讽刺两人同样差劲，表现差不多。以上两个意义的「难」都要读成ㄋㄢˊ。今人则把「难」读成ㄋㄢˋ，多用以形容同处困境、共同患难的朋友。"},
  {"name": "鸟尽弓藏，兔死狗烹", "cid": 296891, "pid": 11702036, "num": 208, "meaning": "鸟打光了，弓就被收起；兔抓完了，猎狗就被煮吃。比喻功成后抛弃甚至杀害功臣。", "source": "《史记·越王勾践世家》", "example": "帮助国王打天下后，他怕遭鸟尽弓藏，便早早辞官回家。", "story": "春秋时，范蠡帮越王勾践灭了吴国。他写信劝好友文种：飞鸟打尽，良弓收藏；狡兔死掉，猎狗被烹。越王只可共患难，不可同享乐。文种不听，后来果然被勾践逼死。此词警示功臣的下场。"},
  {"name": "宁为玉碎，不为瓦全", "cid": 296891, "pid": 11702037, "num": 209, "meaning": "宁做玉器被打碎，不做瓦器而保全。比喻宁愿为正义事业牺牲，不愿丧失气节，苟且偷生。", "source": "《北齐书・元景安传》：“大丈夫宁可玉碎，不能瓦全。”", "example": "咱们～。能突围就突围，万一出不去，他们拚到底吧。（姚雪垠《李自成》第一卷第十二章）", "story": "公元550年，北朝的东魏大将军高洋逼迫东魏孝静帝退位，建立了北齐王朝。次年又毒死了孝静帝和他的三个儿子。有一年出现了日食，高洋担心自己的皇位不保，问一个亲信：“王莽夺了刘家的天下，为什么后来刘秀又能把天下夺回去?”那亲信说：“陛下，这要怪王莽自己了：他没有把刘氏家族斩尽杀绝。”高洋马上又开了杀戒：把东魏姓元（原姓拓跋）的二十五家直系皇族700多人全部杀光，连婴儿也无一幸免。"},
  {"name": "怒发冲冠", "cid": 296891, "pid": 11702038, "num": 210, "meaning": "犹「怒发冲冠」。见「怒发冲冠」条。01.《封神演义》第二八回：「子牙看到切情之处，怒发冲冠：『此贼若不先除，恐为后患！』」", "source": "", "example": "", "story": "此处所列为「怒发冲冠」之典故说明，提供参考。头发直竖，把戴的帽子都顶了起来，这是古人用来形容极度愤怒的样子。古代成年人是要戴冠的。和「怒发冲冠」相关最有名的故事当属蔺相如「完璧归赵」了。战国时代，秦王想用十五座城池换取赵国的和氏璧。赵王因宦者令缪贤推荐，召见蔺相如，并且问他对这件事的看法。蔺相如不想使秦国有攻打赵国的借口，主张送和氏璧到秦国去，并说：「君王如确定没有合适的人选，我愿意带著和氏璧出使。秦国真的给城，璧就留给秦国；不给，我会将和氏璧完好的送回赵国。」于是赵王派他带著和氏璧西行入秦国。到了秦国，蔺相如发觉秦王并不是真正想用十五座城池来交换和氏璧，于是在秦王欣赏和氏璧时，假意的说璧上有瑕疵要指给秦王看。等和氏璧回到他的手上，立刻后退了几步，倚柱而立，气得头发竖立，顶起帽子，说秦王既无意把城池偿还赵王，他只好把头、璧都在柱上撞碎。事实上，在《庄子．盗跖》篇中就已提到盗跖一听孔子来访，气得「发上指冠」，这和「怒发冲冠」的意思是一样的。《史记．卷八六．刺客列传．荆轲》中讲到燕太子丹在易水之边为荆轲送行，壮烈的场面让在场的人「发尽上指冠」，内心慷慨激昂到发尽直竖，意思也是相近的。《庄子》的典故虽较早，但是推究后来所用的「怒发冲冠」，当以蔺相如故事较为贴近。"},
  {"name": "呕心沥血", "cid": 296891, "pid": 11702039, "num": 211, "meaning": "「呕心」，把心吐出来。＃语本南朝梁．刘勰《文心雕龙．隐秀》。「沥血」，把血滴尽。语出南朝梁．元帝〈与诸藩令〉。「呕心沥血」比喻费尽心思，用尽心血。", "source": "「呕心」：＃南朝梁．刘勰《文心雕龙．隐秀》*1*\n「沥血」：南朝梁．元帝〈与诸藩令〉（据《文馆词林》卷六九五引）", "example": "这部小说是他的呕心沥血之作，也是他所有作品中最好的。", "story": "「呕心沥血」这句成语有两个典源，第一个是「呕心」，来自于南朝梁刘勰所写的《文心雕龙》。在〈隐秀〉篇中，他说文人在写作时，重视创意的人，无不想找出跟别人不一样的意念；重视辞采的人，则挖空心思，想写出美丽的词句。无论何种人，为达到目的，甚至琢磨到似乎要将心、胆吐出；有时经年累月地反复苦思，但这还不足以形容他们的辛苦。这里的「呕心」和「吐胆」的意思是一样的，都是比喻创作的苦心。唐代诗人李贺就是一位「呕心」创作的人。在李商隐所写的〈李贺小传〉提到他常常带著仆人出游，骑著驴子，背著一只破旧袋子，遇有灵感，就立即写下来丢入袋中。到晚上回到家时，已经是满满的一袋子纸片了，李贺的母亲看到这种情形，就说：「我的儿子大概是要将心呕出后才会停止吧！」这是关于「呕心」一语典源的资料。至于第二个「沥血」的典故，则出自于南朝梁元帝所写的〈与诸藩令〉中。文中写道：今日国库充足，谷仓丰盈，占有全楚，涵盖了王畿以外的南方。我们拥有万艘船舰，和众多强悍勇猛的骑兵。只要以极少的兵力，就可防守地势险要的关隘，更能以文克敌，不战而胜。大家不求富贵，不挂念妻儿，如此用尽心血，极尽辛劳，时时自我警惕，奋发图强，准备杀敌报仇雪耻，这是为了什么呢？就是为了消灭铲除贪暴的人。这里的原文就用了「沥血叩心」，来比喻「费尽心血，极尽辛劳」。后来这两个典源被合用成「呕心沥血」，用来比喻费尽心思，用尽心血。"},
  {"name": "赔了夫人又折兵", "cid": 296891, "pid": 11702040, "num": 212, "meaning": "送给人夫人，又折损了自己的兵将，大大吃亏。相传周瑜曾施计，假装要将孙权的妹妹嫁给刘备，以取荆州，结果弄巧成拙，不但没得到荆州，反而孙权的妹妹真的被娶走，并且又折损了许多兵将。后用「赔了夫人又折兵」以比喻不但没有占到便宜，反而吃大亏。语出元．无名氏《隔江斗智》第二折。", "source": "元．无名氏《隔江斗智》第二折", "example": "有了这次赔了夫人又折兵的教训，他再也不会上当了。", "story": "「赔了夫人又折兵」这句成语常见於戏曲小说之中，意指没占到便宜还吃了大亏。《隔江斗智》一出戏，演的是三国时代诸葛亮和周瑜为了争夺荆州互相斗智的故事。周瑜为了夺回荆州，假意将孙权的妹妹孙安小姐嫁给刘备，想趁著送亲、洞房、回门等时机对刘备不利，可是没想到计谋被诸葛亮识破，结果「赔了夫人又折兵」，不但没得到荆州，反而孙权的妹妹真的被娶走，并且又折损了许多兵将。后来「赔了夫人又折兵」被用来比喻不但没有占到便宜，反而吃大亏。"},
  {"name": "鹏程万里", "cid": 296891, "pid": 11702041, "num": 213, "meaning": "大鹏飞行的路程数万里。语本《庄子．逍遥游》。后用「鹏程万里」比喻前程远大，不可限量。\n△「扶摇直上」", "source": "《庄子．逍遥游》", "example": "一帆风顺靠运气，鹏程万里靠志气。", "story": "庄子是先秦道家思想的代表人物，他的哲学宗旨是要人们超越世俗的价值观，不要去计较那些是非、大小、有用无用等的判断，因为这些都是人为的，并非恒常不变。人们如果一味计较这些，身心就会被牢牢绑住；要学著抛弃这种种的束缚，才能得到真正的放任自得，也就是庄子所谓「逍遥」的境界。为了引导人们能接受他的思想，庄子运用很多的寓言，来启发人们。在〈逍遥游〉中，庄子举了一个鹏鸟高飞的寓言，说明人要先懂得「适性」，才能知道自己也有天生的长处，不会一味羡慕别人。在这个寓言中，庄子先说北海有一种鲲鱼，大得不得了，后来这种鱼变成了鹏鸟。鹏鸟也是大得不得了，奋飞起来的时候，张开翅膀像悬在天边的云。当时有一位专门记叙奇特事物的齐谐，他说：鹏鸟要从北海飞到南海时，翅膀一打，击水的面积广达三千里，乘著扶摇盘旋而上，高达九万里！原文以鹏鸟为喻，又说其「抟扶摇而上者九万里」，后来演变成「鹏程万里」这句成语，用来比喻前程远大，不可限量。"},
  {"name": "平易近人", "cid": 296891, "pid": 11702042, "num": 214, "meaning": "指政令平和简易，贴近民意。语本《史记．卷三三．鲁周公世家》。后用「平易近人」形容态度和蔼亲切，容易接近。亦用于形容诗文浅白易懂。", "source": "《史记．卷三三．鲁周公世家》", "example": "老师十分平易近人，有问题直接向他反应即可。", "story": "「平易近人」原作「平易近民」。据《史记．卷三三．鲁周公世家》载，周公和姜太公都因为辅佐武王打败商纣有功，分别受封于鲁和齐。但是周公一直留在都城协助处理政事，就派他的儿子伯禽去管理。伯禽上任三年后才向周公回报政绩，而姜太公上任五个月就回报他的政绩。原来伯禽为了改革鲁地的风俗和礼制，花了三年的时间才完成；姜太公则是简化君臣之礼，顺应齐地风俗来治理。周公在听到伯禽迟于回报的原因后，就曾叹气说：鲁国将来会臣服于齐国，因为政令平和简易，贴近民意，人民必定会来归顺。后来「平易近人」这个成语就从这里演变而出，用来形容态度和蔼亲切，容易接近。亦用来形容诗文浅白易懂。"},
  {"name": "萍水相逢", "cid": 296891, "pid": 11702043, "num": 215, "meaning": "浮萍漂浮水面，聚散不定。比喻两个人本来不相识，因机缘巧合偶然相逢，同时亦指交情尚属微浅。语出唐．王勃〈秋日登洪府滕王阁饯别序〉。", "source": "唐．王勃〈秋日登洪府滕王阁饯别序〉（据《全唐文．卷一八一．王勃》引）", "example": "纵使萍水相逢，无缘也难深交。", "story": "浮萍是一种浮生在水面的水草，叶扁平而小，面背皆青，有须根下垂水中，会随水流四处漂动。古人观察浮萍的漂动，觉得人生的聚散，有如浮萍，所以有「萍水相逢」的说法。一般认为这句话是出自于唐代王勃所写的〈秋日登洪府滕王阁饯别序〉，也就是通俗所称的〈滕王阁序〉。这篇文章是王勃参加洪州都督阎公于滕王阁上盛宴时所作。其中「落霞与孤鹜齐飞，秋水共长天一色」传诵千古。但除这两句外，文章中也有几句写到奔波天涯的失意游子，「关山难越，谁悲失路之人；萍水相逢，尽是他乡之客」。意思是说：「群山峻岭，是如此难以超越，但有谁会去同情于迷路于其中的人？在天涯奔波中，偶然相遇的人竟都是流落在外的异乡人。」当然王勃在文章中，说这几句话是别有所指的，是在为那些有志难伸的人，抒发自己的看法。后来「萍水相逢」被摘出成一句成语，比喻人本素不相识，因机缘巧合偶然相逢。就缘分来说，自是有缘；但就交情来讲，则尚属微浅。这句成语有时偏于缘分，有时偏于交情，使用时要特别留意。"},
  {"name": "破釜沉舟", "cid": 296891, "pid": 11702044, "num": 216, "meaning": "打破锅釜又凿沉船，让自己没有退路，以求战争胜利。＃典出汉．司马迁《史记．卷七．项羽本纪》。后用「破釜沉舟」比喻不惜切断自己的退路，以求努力获得最好的成果。", "source": "《史记．卷七．项羽本纪》", "example": "事已至此，只有破釜沉舟，作最后一搏。", "story": "《史记．卷七．项羽本纪》记载秦朝末年，群雄起义反秦，秦将章邯率兵攻赵，以重兵围攻巨鹿。楚怀王派宋义、项羽救赵，但宋义却停兵不进。项羽杀了宋义取得军权后，派遣二万兵将渡过漳水，救援巨鹿。之后，赵将陈余又请求项羽派更多兵力支援，项羽于是带领全部的军队渡河，然后将渡河的船弄沉，打破煮饭的锅子，烧掉驻扎的营地，并只带三天干粮，以示必死之决心，不做撤退的打算。经过九次大战，终于打败秦军。这即是历史上有名的「巨鹿之战」，项羽为使士卒拚死战斗，渡河之后，即将渡船弄沉，把釜甑打破，以断绝士兵后退的念头。后来「破釜沉舟」这句成语就从这里演变而出，形容做事果决，义无反顾。"},
  {"name": "破镜重圆", "cid": 296891, "pid": 11702045, "num": 217, "meaning": "破成两半的镜子再次复合。指南朝陈徐德言与妻乐昌公主于战乱离散时各执半镜，作为他日相见的信物，后果因此得以相聚。典出唐．孟棨《本事诗．情感》。后用「破镜重圆」比喻夫妻离散或感情决裂后重新团圆合好。", "source": "唐．孟棨*1*《本事诗．情感》（据《历代诗话续编》引）", "example": "在离散二十年后，他们夫妻终于破镜重圆。", "story": "南北朝末年，北周丞相杨坚杀了静帝自立为皇帝，建立隋朝。接著隋朝举兵南下，攻打南朝陈。虽然国难当前，陈后主整天却只知饮酒赋诗作乐，即使隋的大军已经逼近首都建康，他仍没有丝毫的警醒。太子舍人徐德言料定国家将亡，到时夫妻必在战乱中分离，便对他的妻子乐昌公主说：「要是国家灭亡了，以妳的才艺容貌，一定会被俘虏，落入权贵人家。」为了希望将来两人能再团圆，他把一面铜镜分为两半，一人保存一半，并约定每年的元宵节将破镜拿到京城的市场去卖，当作两人相见的信物。后来陈灭亡，两人果然在战乱中失散。徐德言照约定带著半面铜镜，在元宵节的时候到京城的市场叫卖。虽然他没有见到乐昌公主，却发现有一个仆役也在叫卖破铜镜。徐德言款待他到自己住的地方，又拿自己的破镜出来相合，果然是乐昌公主的半面破镜。他才知道，原来乐昌公主已经成为隋朝功臣越国公杨素的宠妾。他很伤心，便在乐昌公主的那面破镜上题了一首诗，意思是说虽然夫妻都还活著，却再也无法团聚了。乐昌公主看了诗以后非常难过，再也不肯吃东西。杨素知道这件事情之后，非常感动，就让乐昌公主回到徐德言身边，这对夫妻终于能够重新团圆。后来这个故事被浓缩成「破镜重圆」，用来比喻夫妻离散或感情决裂后重新团圆合好。"},
  {"name": "扑朔迷离", "cid": 296891, "pid": 11702046, "num": 218, "meaning": "指兔子雌雄的特性。语本古辞〈木兰诗〉二首之一。但因雌雄两兔在一起奔跑时，难以分辨，因此后用「扑朔迷离」形容事物错综复杂，难以骤然明了真相。亦用于形容景色迷蒙。", "source": "古辞〈木兰诗〉二首之一（据《乐府诗集．卷二五．横吹曲辞》引）", "example": "这件扑朔迷离的谋杀案，警方正全力侦办中。", "story": "古乐府诗里有一首〈木兰诗〉，叙述一位女子代父从军的故事。这个名叫木兰的女孩子，有天在织布时，突然停下来叹气，烦恼著日前朝廷下了征召令，要召她父亲上战场。木兰觉得父亲年事已高，可能无法承受战地生活，而家里也没有哥哥可以代父亲上战场。于是，孝顺的木兰决定自己女扮男装，代父亲去从军。在军中，木兰凭著坚忍不拔的精神，过了十二年都没被发现是女儿身，还建立了不少功绩。凯旋归来后，她婉拒了君王赏赐的官位，只要求能回乡过原本的生活。木兰回到故乡后，家人非常高兴地迎接她。她回到房间，脱下军装，换回女儿装，出来与同袍见面，大家都惊讶得不得了，这个在军中一同出生入死的战友，竟然是个女孩子！〈木兰诗〉最后以兔子来比喻这段女扮男装的奇事。在平常时候，兔子是很容易分辨雌雄的。雄兔脚扑朔－－个性比较好动，脚会不安分的乱踢；而雌兔眼迷离－－个性比较静，常将眼睛瞇起来休息。但两只一起奔跑时，是很难分辨雌雄的。后来「扑朔迷离」这句成语就从这里演变而出，形容事物错综复杂，难以骤然明了真相。亦用于形容景色迷蒙。"},
  {"name": "璞玉浑金", "cid": 296891, "pid": 11702047, "num": 219, "meaning": "比喻天然美质，未加修饰。多用来形容人的品质淳朴善良。", "source": "南朝・宋・刘义庆《世说新语・赏誉》：“王戎目山巨源如璞玉浑金，人皆钦其宝，莫知名其器。”", "example": "灵芝继起殊寻常，浑金璞玉其器良。（清・黄遵宪《别赖云芝同年》诗）", "story": "魏晋时期，在文学上有名气的“竹林七贤”之一的山涛，40岁才当上官，在京城任尚书吏郎，他很敬重有才学的嵇康，因工作调动想推荐嵇康去接替他的位置，可嵇康不愿。后来他为吏部尚书，启用嵇绍。王戎盛赞山涛是没有琢磨的璞玉。"},
  {"name": "欺世盗名", "cid": 296891, "pid": 11702048, "num": 220, "meaning": "「欺世」，欺骗世人。※语或本《韩非子．诡使》。「盗名」，盗取名誉。语出《荀子．不苟》。「欺世盗名」比喻欺骗世人，盗取名誉。\n△「沽名钓誉」", "source": "「欺世」：※《韩非子．诡使》\n「盗名」：《荀子．不苟》", "example": "他是个欺世盗名，混淆视听，不可信任的人。", "story": "「欺世盗名」系由「欺世」及「盗名」二语组合而成。\n「欺世」是出自《韩非子．诡使》。战国七雄中的韩国，因为饱受强邻秦国的威胁，加上国君无能，人心涣散，以致内忧外患交迫，随时都可能亡国。韩非身为韩国的诸公子之一，曾在荀子门下受业学习，希望能用一己之才，为国效力，挽救国势。他虽屡次上书劝谏韩王，却无法受到重用。于是他把满腔的壮志雄心，写成《韩非子》一书。在〈诡使〉篇中韩非认为，君主掌握法度，是为了要拥有生杀的权柄，然而现在遵守法度，想要忠心侍奉君主的人，却不得进见；而言语巧诈，行为奸轨，侥幸得以偷欺于世的人，反而能够常常接近君王，得到重用。\n「盗名」则是出自《荀子．不苟》。荀子认为：富贵是人性所爱，贫贱是人性所恶，如果有人厌恶富贵，喜爱贫贱，这是违反人性，用来盗取声望的作法。这两个典源，一见「偷世」，一见「盗名」，后来被合用演变成「欺世盗名」，用来比喻欺骗世人，盗取名誉。"},
  {"name": "奇货可居", "cid": 296891, "pid": 11702049, "num": 221, "meaning": "收藏奇珍异品，等待高价出售。比喻利用某种专长或有价值的东西以谋利。语出《史记．卷八五．吕不韦列传》。", "source": "《史记．卷八五．吕不韦列传》", "example": "他看准了水在大漠地区必定奇货可居，一本万利。", "story": "据《史记．卷八五．吕不韦列传》载：战国时有一个非常成功的商人吕不韦，他虽然事业有成，但深感商人社会地位太低，所以萌发了从政的雄心。当时，秦安国君有一个儿子名叫子楚，他被送到赵国当人质。由于秦国屡次攻打赵国，所以赵国对子楚很不礼遇，生活用度也不宽裕，经济拮据，日子过得很不称心。当时吕不韦正好在赵都邯郸做生意，看到子楚的特殊背景和处境，认为「奇货可居」，于是就去求见子楚。吕不韦对子楚说：「我能光大你的门庭。」子楚听后笑著说：「您还是先光大自己门庭，然后再光大我的门庭吧！」吕不韦说：「您有所不知，我的门庭是有待您的门庭光大后才能光大啊！」子楚心知吕不韦所说意思，便和他促膝深谈。吕不韦告诉子楚自己的计划：秦昭王死后，安国君得立为秦王，如果安国君华阳夫人能立子楚为继承人，那么子楚就可争到太子之位。后来吕不韦的计划果然成功了，子楚被立为太子，继位为国君，于是拜吕不韦为丞相。吕不韦果然因为子楚这个奇货，而得到了数不尽的名与利。后来「奇货可居」就用来比喻利用某种专长或有价值的东西以谋利。"},
  {"name": "骑虎难下", "cid": 296891, "pid": 11702050, "num": 222, "meaning": "骑著老虎，害怕被咬而不敢下来。比喻事情迫于情势，无法中止，只好继续做下去。＃语本南朝宋．何法盛〈晋中兴书〉。", "source": "＃南朝宋．何法盛〈晋中兴书〉（据《太平御览．卷四六二．人事部．游说下》引）", "example": "我这套计谋目的在引敌深入，让他们骑虎难下。", "story": "永嘉之乱后，晋室南迁，天下仍不太平，各地均有叛乱。晋成帝时，苏峻起兵叛乱，进逼京师，情势十分危急。那时以陶侃为首，联合温峤等人共同讨伐叛军，却一直无法取胜。陶侃感到势不可为，想要退兵，温峤便说服他，说：「天子受到小人逼迫，社稷动荡不安，正是臣子报效国家的时机。如今的情势，已经不容我们退缩，就好像骑上了老虎，难以下来啊！」陶侃无法反驳，便留下来继续领导众人，终于平定了苏峻之乱。后来「骑虎难下」这句成语，就从南朝宋．何法盛〈晋中兴书〉所记温峤言「骑虎之势，可得下乎」演变而出，比喻事情迫于情势，无法中止，只好继续做下去。"},
  {"name": "旗鼓相当", "cid": 296891, "pid": 11702051, "num": 223, "meaning": "军旗和战鼓表现出的气势相当，形容两方军队阵容、声势不相上下。※＃语或本《后汉书．卷一三．隗嚣公孙述列传．隗嚣》。后用「旗鼓相当」比喻双方势均力敌。\n△「旗鼓相望」、「势均力敌」", "source": "※＃《后汉书．卷一三．隗嚣公孙述列传．隗嚣》*1*", "example": "这两队实力旗鼓相当，这场球赛精采可期。", "story": "「旗鼓相当」典源作「鼓旗相当」。古时作战，军中都是以敲击战鼓及挥舞旗帜来指挥进退，鼓声大作或旗帜飞扬都可表现出壮盛的气势。这两者的气势相当，就表示双方军队的阵容与声势不相上下。据《后汉书．卷一三．隗嚣列传》载，新莽末年，东汉人隗嚣（ㄨㄟˇ　ㄒㄧㄠ）在陇西一带据地为王，称西州上将军；公孙述则占有今四川一带，称蜀中皇帝。当时，尚未取得政权的汉光武帝刘秀兵力多布署在东部，其西部军力无法与两方的任一方相抗衡，为避免两大豪强合作，他于是想拉拢隗嚣，孤立公孙述，便写了一封信给隗嚣，信中说道：「如令子阳到汉中、三辅，愿因将军兵马，鼓旗相当。」子阳，即公孙述的字。这句话的意思是说：如果公孙述来到汉中及京都长安附近，希望我能获得你的援助，以使我们与公孙述的军队阵容和兵力相当。刘秀信中「鼓旗相当」这个词语，后来在文献中颇常见，但多作「旗鼓相当」，用来比喻双方势均力敌。另外，在《辂（ㄌㄨˋ）别传》中有段描述：十五岁的管辂聪明伶俐，颇有才名。有一次，琅邪太守单（ㄕㄢˋ）子春邀请他到家中谈话，管辂到了以后，发现另有几位文人学者在场，管辂问单子春：「今天是要我一个人与在座几位对答吗？」单子春则说：「吾欲自与卿旗鼓相当。」也就是说：我想要自己一人与你势均力敌地对谈。「旗鼓相当」这个成语不局限于军事战况上，而可以广泛用在一般事务。"},
  {"name": "杞人忧天", "cid": 296891, "pid": 11702052, "num": 224, "meaning": "古时杞国有个人，因为担心天会塌下来而忧虑不安。典出《列子．天瑞》。后用「杞人忧天」比喻缺乏根据且不必要的忧虑。\n△「庸人自扰」", "source": "《列子．天瑞》", "example": "事情状况未明，大家先别杞人忧天，乱了阵脚！", "story": "《列子．天瑞》中有一则故事：从前有个杞国人因为成天担忧天会崩塌，地会陷落，每天睡不著觉，也吃不下饭。后来有人开导他说：「天其实是气体聚积而成，气体本来就是无所不在，你现在已经是整天在这团气体里活动呼吸了，怎么会担心它崩塌呢？」他听了以后，不但没有因此而放心，反而担心起以气体构成的天，会不会无法支撑日月星辰的重量，日月星辰会因此而坠落。那个人只好又劝他说：「日月星辰也不过是气体中发亮的部分，即使坠落也不会伤人啊！」终于，他停止了对天的担忧，却转而忧虑不知道什么时候地会塌陷。那个人接著解释：「地是由许多土块累积成的，这些土块密密实实的充塞在每个角落，你已经是整天在上面行走踩踏，有什么理由让你疑心地会塌陷呢？」他听了这番话后，心中的疑虑终于消失了。后来这个故事被浓缩成「杞人忧天」，用来比喻缺乏根据且不必要的忧虑。"},
  {"name": "起死回生", "cid": 296891, "pid": 11702053, "num": 225, "meaning": "即「起死回生」。见「起死回生」条。01.《太平广记．卷五九．太玄女》引《女仙传》：「行三十六术甚效，起死回生，救人无数。」", "source": "", "example": "", "story": "此处所列为「起死回生」之典故说明，提供参考。扁鹊是战国时的名医。有一天他经过虢国，听说虢国太子猝死，便来到宫门前，向侍从打听原委。了解太子的病症，又得知断气不到半天，还未入殓后，就跟侍从保证自己可以救回太子。侍从本来不相信，但听了扁鹊治病的方法，惊佩不已，立刻禀报虢君。虢君赶紧请扁鹊进宫。扁鹊对虢君说：「依我看，太子这是尸厥症，因体内会气不通而昏死过去，实际上并未真地死亡，还有机会救回。」于是命令弟子准备好医疗用具，针灸太子的三阳五会等穴道。不一会儿，太子就醒过来了。扁鹊再叫弟子用药交替热敷他的腋下，并将太子扶起坐著，调理身体的阴阳之气。之后再连续服药二十天，太子就完全康复了。经历这件事情，所有人都说扁鹊能让死人复生，但扁鹊却说：「不是我能让死人复生，是这人还有机会存活，而我能将他救回而已。」后来「起死回生」这句成语就从这里演变而出，用来比喻医术高明。亦用于比喻毫无希望的情势扭转过来。"},
  {"name": "千变万化", "cid": 296891, "pid": 11702054, "num": 226, "meaning": "形容变化无穷。＃◎语出《列子．周穆王》。_x000D_\n△「瞬息万变」", "source": "《列子．周穆王》*1*_x000D_\n《列子．汤问》", "example": "魔术师的表演千变万化，让人叹为观止。", "story": "《列子．周穆王》有一段记载：周穆王时，有一异人从西方极远之国来，他能进出水火，穿透金石，使山川夷为平地，把城市迁到别处；能凌空而不会坠下，碰撞实物也不受阻挡。变化多端，无穷无极。周穆王对他非常敬畏，奉若神明。典源又见《列子．汤问》。其内容则是记载周穆王西游时，遇到一个巧匠，他制作的木偶与真人无异，并且在巧匠的操控下跳起舞来，动作千变万化，十分灵巧。周穆王见了非常惊异，称赞工匠的技艺精巧，有如自然的化育。「千变万化」就是直摘自典源的一个成语，被用来形容变化无穷。"},
  {"name": "前车之鉴", "cid": 296891, "pid": 11702055, "num": 227, "meaning": "鉴：镜子，为教训。前面车子翻倒的教训。比喻先前的失败，可以做为以后的教训。", "source": "汉・刘向《说苑・善说》：“《周书》曰：‘前车覆，后车戒。’”", "example": "～，请自三思。（清・陈忱《水浒后传》第二十五回）", "story": "西汉时，贾谊上书汉文帝说：秦朝因暴政而亡，前面的车翻了，后面的车要小心。他劝文帝施行仁政，以秦为戒。后来“前车之鉴”指把前人失败的教训当作自己的警戒，避免再犯同样的错。"},
  {"name": "前功尽弃", "cid": 296891, "pid": 11702056, "num": 228, "meaning": "指以前辛苦获得的成果，全部废弃。◎语本《战国策．西周策》。_x000D_\n△「功亏一篑」、「百步穿杨」、「百发百中」", "source": "《战国策．西周策》_x000D_\n《战国策．魏策三》", "example": "这件事现在不能停，一停下来，就会前功尽弃。", "story": "「前功尽弃」原作「前功尽灭」、「前功必弃」。据《战国策．西周策》载，苏厉是战国时谋士。有一次，他听说秦国大将白起即将带兵攻打魏国都城大梁，就对周王说：「白起曾经打败了韩、魏、赵等国，并且杀害魏国将领，攻占了许多土地。现在他又要出兵攻打大梁，大梁一旦被攻下，周王室就会面临危险，您应该想办法阻止。」于是建议周王派人前往秦国去对白起说：「以前楚国有一个名叫养由基的人，善于射箭。在距离柳树一百步的地方射击，射出一百支箭，每一箭都能射中柳叶，一旁观看的人都夸赞射得很好。但是有一个路过的人，却说：『的确射得很好，但是可以再教导他射箭的方法。』养由基听了，就说：『大家都说我射得很好，你却说可以教导我，那你为何不代替我射那柳叶呢？』那个人说：『我不能教导你伸左臂、屈右臂的射箭本领，但是你今天射柳叶百发百中，却不善于休息，等一下疲倦了，一箭也射不中，就会前功尽弃。』就像你现在打败了许多国家，取得许多土地，功劳很大。又即将要出兵经过周王室的所在地去攻打魏国，如果这一仗不能取得胜利，就会前功尽弃了。所以你还是假装生病，不要出兵的好。」典源又见《战国策．魏策三》。叙述秦昭王三十二年时，秦国派穰侯魏冉攻打魏国，包围首都大梁。魏国大夫须贾向穰侯说：「魏国现在发动三十万精兵驻守大梁，秦和楚、赵三国联军，是绝不可能攻下大梁的。一旦攻城失利，也会对您不利，您以前的功业一定要全部报废了。」穰侯听了觉得很有道理，便从大梁罢兵而去。「前功尽弃」这句成语就从这里演变而出，指以前辛苦获得的成果，全部废弃。"},
  {"name": "秦镜高悬", "cid": 296891, "pid": 11702058, "num": 229, "meaning": "即「明镜高悬」。见「明镜高悬」条。01.清．李渔《比目鱼》第三二出：「若非秦镜高悬，替老夫伸冤雪枉，不止陨身一旦，亦且遗臭万年。」", "source": "", "example": "", "story": "此处所列为「明镜高悬」之典故说明，提供参考。根据《西京杂记》的记载，刘邦攻入咸阳宫时，寻获宝物一方明镜，它能照见人的五脏六腑，也能鉴别人心正邪。秦始皇常利用它来照宫女，凡心胆慌张跳动的就杀死她。杜甫〈洗兵马〉诗「司徒清鉴悬明镜」句，正式用「悬明镜」来称许司徒李光弼，从此人们就以「明镜（秦镜）高悬」来比喻官吏办事明察洞烛，执法公正严明。"},
  {"name": "青出于蓝", "cid": 296891, "pid": 11702059, "num": 230, "meaning": "蓝，蓼（ㄌㄧㄠˇ）蓝，可以提取靛（ㄉㄧㄢˋ）青染料的植物。「青出于蓝」指青色是从蓼蓝里提炼出来的，但是颜色比蓼蓝还深。比喻求学能使人进步。＃语本《荀子．劝学》。后用「青出于蓝」比喻弟子胜过老师，或后辈优于前辈。\n△「冰寒于水」、「后来居上」", "source": "＃《荀子．劝学》", "example": "徒弟能青出于蓝，正是老师最大的安慰。", "story": "战国时代大哲学家荀子写了一篇〈劝学〉的文章来鼓励大家多学习。学习有什么好处呢？就像靛青是从蓼蓝提炼出来，但是颜色比蓼蓝还要青；冰是水结冻而成，但是温度比水还要低。学习就像这种提炼和结冻的效果一样。我们把一根直挺挺的木条用𫐓的工夫，慢慢使它弯曲，制成车轮。等它弯曲合乎规矩后，就是经过日晒干枯也不会再恢复原状了。这种𫐓的工夫也是学习。所以木头要划得直，得靠绳墨；金属要磨锐，得靠砺石。君子就是要接受绳墨般的约束，砺石般的磨炼，假如能广泛地去学习，而且能时时反省自己，那就不会有什么过错了。后来就从荀子这段话中演变成「青出于蓝」这句成语，原来是用来比喻学习的效果，后多用来比喻学生表现较老师出色，晚辈成就超过前辈。"},
  {"name": "青云直上", "cid": 296891, "pid": 11702060, "num": 231, "meaning": "青云，青天上的云。「青云直上」指直达云端，比喻顺利而迅速地升上高位。语本《史记．卷七九．范睢蔡泽列传．范睢》。", "source": "《史记．卷七九．范睢蔡泽列传．范睢》", "example": "院长仕途得以青云直上，除了能力好，得人和更是其中关键。", "story": "范睢，字叔，战国时魏国人。他曾在魏国中大夫须贾府中做事。有一次，范睢跟随须贾出使齐国时，被须贾怀疑私通齐国。因此回国后，须贾将这件事告诉了魏相国魏齐，魏齐在盛怒之下，差点把范睢打死。后来范睢诈死逃出魏国，改名张禄。到秦国后，范睢逐渐取得秦王信赖，成为秦国相国，而魏国人对此并不知情，认为他早已死去。后来魏王获知秦国将攻打韩、魏两国，便派须贾出使秦国。范睢听说须贾要来秦国，于是隐藏身分，并穿著破旧的衣服与须贾相见。须贾见范睢还活著，不禁大吃一惊，问：「你现在做什么事呢？」范睢回答说：「我在当差役。」这时须贾怜悯地说：「范叔怎么会贫寒到这个地步！」于是送给他一件粗丝袍。并且顺便问说：「秦国的相国张君，你知道他吧？我听说他在秦王那里很得宠，天下大事都由相国张君来决定。这次我出使的成功与否也都取决于张君。你有没有跟相国张君熟悉的朋友啊？」范睢说：「我的主人跟他熟识，即使是我也能求见，请让我帮您引见。」范睢于是弄来一辆四匹马拉的大车，并亲自替须贾驾驭，直接进入秦国相府。相府里的人看到范睢驾车前来都纷纷回避离开。须贾对这样的情景感到很奇怪。到了相国官邸门口，范睢对须贾说：「请在此稍等，我替您先进去向相国通报一声。」须贾在门口等了很长时间，便问门卒说：「范叔进去很久都还不出来，是怎么一回事呢？」门卒说：「这里没有范叔这个人。」须贾说：「就是刚才帮我驾车的那个人啊！」门卒说：「他就是我们相国张君啊！」须贾没想到范睢竟然靠自己能力到达如在青云之上的显要地位，一听大惊失色，自知被算计了，于是赶紧脱掉衣服光著上半身，跪地前行，请求谅解。后来范睢看在须贾曾送他衣物的分上，表示须贾尚念旧情，因此饶了须贾。后来「青云直上」这句成语就从这里演变而出，用来比喻顺利而迅速地升到高位。"},
  {"name": "倾国倾城", "cid": 296891, "pid": 11702061, "num": 232, "meaning": "倾，倾覆。「倾国倾城」，指倾覆城邦家国。形容女子的美艳，会带来祸害。＃语本汉．袁康《越绝书．卷九．越绝计倪外传一一》。后用「倾国倾城」形容女子极为美丽动人。", "source": "＃汉．袁康《越绝书．卷九．越绝计倪外传一一》", "example": "红颜最怕岁月催，纵有倾国倾城之貌，到头来也难免白发苍苍。", "story": "《越绝书》是重要史书之一，内容主要记载春秋战国时吴越的历史。吴国阖闾执政时，以伍子胥为相，伐楚以争天下。当此之际，吴之邻国越屡屡派兵袭吴，于是吴、越交战，阖闾战败并伤重而死。吴王夫差即位后，为报父仇，带兵攻入越都会（ㄍㄨㄟˋ）稽，越王句越被迫求和。伍子胥劝夫差不可接受句践的求和，以免留下后患，但夫差志得意满下仍是答应了越的求和。伍子胥屡次进谏，夫差却听信太宰嚭（ㄆㄧˇ）的谗言，赐其自杀。《越绝书》记此事，慨叹夫差不信伍子胥而听信太宰嚭的谗言，这就好像昔日晋献公受骊姬迷惑，使得众叛亲离，种下晋国衰败的祸根；亦犹如过去周幽王纵容褒姒，以致失信于群臣，使犬戎得以入侵。骊姬与褒姒都是极为妖媚美丽的女子，但却又是极为不祥，招来「倾城倾国」的祸害。而越王句越，忍辱负重，生聚教训，发动大军，围困夫差于姑苏山上，求降不得而自杀，吴国果然倾覆，句践终于复兴越国。后来「倾国倾城」这句成语就从这里演变而出，用来形容女子的美艳，可以带来祸害。其实此一语义，早在《诗经》中就已经见到。《诗经．大雅．瞻卬》有「哲妇倾城」这样的句子，意思是「妇人多谋深虑乃乱国」，此处「倾城」，便是「倾覆邦国」义。但后来「倾国倾城」这个成语语意转变，专以形容女子的美艳。"},
  {"name": "趋炎附势", "cid": 296891, "pid": 11702062, "num": 233, "meaning": "「趋炎附势」之「趋」，典源作「趣」。「趣」通「趋」，此指依附。炎，指有权势的人。「趋炎附势」指奉承依附有权势的人。语本晋．王沈〈释时论〉。\n△「攀龙附凤」", "source": "晋．王沈〈释时论〉（据《晋书．卷九二．文苑列传．王沈》引）", "example": "这种趋炎附势的小人，不必理会他！", "story": "王沈生于极端重视门第的晋朝，年轻时虽然很有文采，但出身寒门，还是无法打入上流社会，于是他写了篇〈释时论〉，以抒发郁郁不得志的心情。其中提到：在温暖地方的人，都是喜欢热的人。但能够知道冶炼金属的方法，只有掌炉漆炭的人。就像想要打入上流社会，出身是很重要的。出身卑贱的人，常常被人污辱；出身尊贵的人，却常得到荣耀。肉食的有钱人不断出入于华厦，粗茶淡饭的穷人只能往来于田野。讲求名利的人，向有势力的人逢迎谄媚；而讲求名声的，却因为钱财，而原形毕露。实在是很令人感叹。后来「趋炎附势」这句成语就从这里演变而出，用来比喻依附权势。"},
  {"name": "曲高和寡", "cid": 296891, "pid": 11702063, "num": 234, "meaning": "曲调愈高雅，跟著唱和的人就愈少。比喻无法引起大众的共鸣。语本战国楚．宋玉〈对楚王问〉。_x000D_\n△「下里巴人」、「阳春白雪」", "source": "战国楚．宋玉〈对楚王问〉（据《文选．卷四五．对问》引）", "example": "这种无伴奏的清唱音乐，由于曲高和寡，根本没有市场。", "story": "宋玉是战国时代楚国的著名文学家，善于辞赋，作品有〈九辩〉〈招魂〉等，与屈原并称「屈宋」。关于宋玉的生平，今存甚少，且互相矛盾，依《史记．屈原列传》末尾所记，可知宋玉应是屈原的一个后辈，曾向屈原学习，但因出身寒微，而致仕途蹇困。有一次楚襄王对宋玉说：「我听到许多有关于你的不好传言，是不是因为你的言行举止有不端正的地方呢？」宋玉擅长言论，马上就说：「请大王先宽恕我的过错，让我先讲一段故事。」楚襄王答应了，于是宋玉便说道：「有一个外地的歌者来到了郢都，在市集中唱著下里、巴人这些通俗的歌曲，一开始跟著他一起唱和的人有数千人之多；后来他改唱阳阿、薤露等比较不俗的歌曲，跟著唱和的人就只剩下数百人；等到他唱起阳春、白雪这种高妙、优雅的歌曲，又夹杂著许多高难度的技巧，国中能够一起唱和的人就寥寥无几了。这不是因为歌者唱得不好听，而是因为曲子愈高雅，能够跟著唱和的人也就愈少。同样的，那些批评我的人，不过是些平庸之辈，怎么能够欣赏、了解我的为人呢？」后来「曲高和寡」这句成语就从这里演变而出，用来比喻无法引起大众的共鸣。"},
  {"name": "取而代之", "cid": 296891, "pid": 11702064, "num": 235, "meaning": "指夺取别人的地位而由自己代替。现也指以某一事物代替另一事物。", "source": "西汉・司马迁《史记・项羽本纪》：“秦始皇帝游会稽，渡浙江，梁与籍俱观。籍曰：‘彼可取而代也。’”", "example": "清帝方今玩于彼股掌之上，及其时则～耳。（蔡东藩、许廑父《民国通俗演义》第八十六回）", "story": "秦末，项羽随叔父看秦始皇巡游，排场盛大。年轻的项羽脱口而出：那个人，我可以取而代之！叔父吓得捂住他的嘴。后来项羽果然起兵反秦，成为西楚霸王。此词指取代别人、取而代之。"},
  {"name": "犬牙交错", "cid": 296891, "pid": 11702065, "num": 236, "meaning": "错：交叉，错杂。比喻交界线很曲折，象狗牙那样参差不齐。也比喻情况复杂，双方有多种因素参差交错。", "source": "东汉・班固《汉书・中山靖王传》：“诸侯王自以骨肉至亲，先帝所以广封连城，犬牙相错者，为盘石宗也。”", "example": "这两个国家的边界线～。", "story": "汉高祖刘邦开国之后，分别封功臣到各地为王。但是因为这些王候在地方上拥有强权，甚至有谋反叛变的意思，于是汉高祖就一一把他们消灭了。"},
  {"name": "群策群力", "cid": 296891, "pid": 11702066, "num": 237, "meaning": "聚合众人的智慧和能力。语本汉．扬雄《法言．重黎》。\n△「同心同德」、「同心协力」、「戮力同心」", "source": "汉．扬雄《法言．重黎》", "example": "参加这个游戏，大家要群策群力才能过关。", "story": "根据《史记．卷七．项羽本纪》的记载，秦朝灭亡之后，楚、汉争夺天下，结果在垓下这个地方，刘邦的汉军重挫了项羽的楚军，之后项羽突破重围逃到乌江，在乌江畔，他说：「天之亡我，我何渡为！」觉得没有颜面回去见故乡的父老，于是自刎而死。项羽将自己失败的原因归为天命所致，但汉朝的扬雄不赞同，他认为：「刘邦懂得运用众人的计策和力量，因此可以得到天下；而项羽因为不能知人善任，刚愎自用，最后落得兵败自刎的下场，这和天命有什么关系呢？」此段话见载于《法言》，后来「群策群力」这句成语就从原文中的「汉屈群策，群策屈群力。」演变而出，用来指聚合众人的智慧和能力。"},
  {"name": "人非圣贤，孰能无过", "cid": 296891, "pid": 11702067, "num": 238, "meaning": "旧时指一般人犯错误是难免的。", "source": "先秦・左丘明《左传・宣公二年》：“人谁无过，过而能改，善莫大焉。”", "example": "人非圣贤，孰能无过，只要肯改就是好孩子。", "story": "春秋时，晋灵公残暴，大臣士季劝他说：人谁无过，犯了错能改，再好不过。晋灵公嘴上认错却不改，终被杀。这句话原意是人人都会犯错，可贵在知错能改。后来缩成“人非圣贤，孰能无过”。"},
  {"name": "人弃我取", "cid": 296891, "pid": 11702068, "num": 239, "meaning": "别人抛弃的东西我拾起来。原指商人廉价收买滞销物品，待涨价卖出以获取厚利，后用来表示不跟别人争，仍然有好处。", "source": "西汉・司马迁《史记・货殖列传》：“李克务尽地力，而白圭乐观时变，故人弃我取，人取我与。”", "example": "别人不喜欢的旧书，他人弃我取，竟读成了大学问。", "story": "战国时，商人白圭善于经营。别人争着买时他卖出，别人抛售时他买进，人弃我取，人取我与。他把握时机，低价收、高价卖，终成巨富。后来“人弃我取”指抓住别人忽视的机会。"},
  {"name": "人自为战", "cid": 296891, "pid": 11702069, "num": 240, "meaning": "为战：作战。人人能独立地战斗。", "source": "西汉・司马迁《史记・淮阴侯列传》：“此所谓‘驱市人而战之’，其势非置之死地，使人人自为战。”", "example": "今深入万里，置之死地，士无反顾之心，所谓～者也。（《晋书・袁乔传》）", "story": "楚汉相争，韩信率军攻赵，背水列阵。他对手下说：前面是水，后面是敌，退路已断，大家只有人自为战，拼死才能活命！士兵被逼无奈，个个奋勇，竟大败赵军。此词指人人各自奋战。"},
  {"name": "忍辱负重", "cid": 296891, "pid": 11702070, "num": 241, "meaning": "忍受屈辱怨谤而承担重任。语出《三国志．卷五八．吴书．陆逊传》。", "source": "《三国志．卷五八．吴书．陆逊传》", "example": "当年句践为了复国，忍辱负重，历尽艰辛。", "story": "据《三国志．卷五八．吴书．陆逊传》载，三国时，蜀吴交战，吴主孙权任命陆逊为大都督，带领兵马迎战蜀军。但陆逊手下的一批老将和皇亲贵族，认为他只是个书生，毫无战功，所以不服他的领导。陆逊于是召集众将说：「我以一介书生负此重任，是主上赏识我能够忍受屈辱而承担重任的一点长处。而大家也各自有应尽的职责，不容懈怠。今后若有人不听号令，我将以军法处置！」后来陆逊用计击败刘备，取得胜利，大家见识到他的机智谋略，才完全的心服口服。后来「忍辱负重」被用来形容忍受屈辱怨谤而承担重任。"},
  {"name": "任人唯贤", "cid": 296891, "pid": 11702071, "num": 242, "meaning": "贤：有德有才的人。指用人只选有德有才的人。", "source": "《尚书・咸有一德》：“任官惟贤才，左右惟其人。”", "example": "选拔干部应当是～。", "story": "商朝时，伊尹辅佐商汤灭夏建国。他在《咸有一德》中说：任用官吏，只选有德行有才能的人，不可任人唯亲。商汤照此治国，天下安定。后来“任人唯贤”成为选才的重要原则。"},
  {"name": "日不暇给", "cid": 296891, "pid": 11702072, "num": 243, "meaning": "暇：空闲；给：足够。指事情繁多，时间不够，来不及做完。", "source": "西汉・司马迁《史记・封禅书》：“ 虽受命而功不至，至梁父矣而德不洽，洽矣而日有不暇给，是以即事用希。”", "example": "谁知一个传十，十个传百，官幕两途拿轿子来接的渐渐有～之势。（清・刘鹗《老残游记》第三回）", "story": "汉高祖刘邦打下天下后，天天忙于封赏功臣、制定法令、安定百姓，事情多得做不完。他在诏书里说自己“日不暇给”，时间总是不够用。后来人们用这个词形容事务繁忙、没有空闲。"},
  {"name": "孺子可教", "cid": 296891, "pid": 11702073, "num": 244, "meaning": "孺子，小孩子。「孺子可教」指年轻人可以教诲栽培。用于称许之意。语出《史记．卷五五．留侯世家》。", "source": "《史记．卷五五．留侯世家》", "example": "才吩咐过一次，他就永志不忘，真是孺子可教。", "story": "「孺子」原是幼童的通称，也可以用于指年轻人，「孺子可教」就是说这个年轻人值得教诲。《史记．卷五五．留侯世家》中记载，张良原是战国时韩国贵族，韩国被秦国灭了之后，他想为国家报仇，于是请了一位大力士与他一起刺杀秦始皇，但是没有成功，因此而被通缉，只好隐姓埋名到下邳避难。有一天，张良到桥上散步，有一位穿著褐衣的老人，到张良面前就故意把鞋子掉到桥下，并且很不客气地对张良说：「小伙子，下去替我捡鞋！」张良非常惊讶，想上前揍他一顿。但看他年纪大，就勉强忍耐下来，到桥下替他捡鞋。捡上来后，老人又说：「帮我穿上！」张良百般不情愿，但心想好人就做到底吧，便跪著帮他穿鞋。老人伸脚穿鞋后，笑著离开，张良大吃一惊，目送他远去。老人走了一里路又回来说：「孺子可教啊！五日后天亮时来这里和我踫面。」老人后来又连续测验张良多次，确定他能忍人所不能忍，是个不可多得的人才后，便送给他一本《太公兵法》，相传是姜太公辅佐周武王伐纣后所著的兵书，要他仔细研读，将来可为王者师。后来，张良果真利用这本书中的兵法，帮助汉高祖刘邦打天下，建立了汉朝。「孺子可教」后来就被用来称许可以教诲栽培的年轻人。"},
  {"name": "塞翁失马", "cid": 296891, "pid": 11702074, "num": 245, "meaning": "比喻暂时受到损失，却因祸得福，终于得到好处。典出《淮南子．人间》。", "source": "《淮南子．人间》", "example": "失败为成功之母，不正好阐释了塞翁失马的道理吗？", "story": "边塞附近有户善于养马的人家，某天，家中的马儿忽然跑到胡地去了，邻人们都前来安慰。父亲却不在意地说：「这没什么好难过的，怎知不会带来什么好运呢？」过了几个月，那走失的马居然带著一群胡人的骏马回来，邻人都来道贺。但是父亲却说：「这也不必太高兴，怎知不会是灾祸的前兆呢？」果然不久，儿子在骑马时跌断了腿，邻人又赶来慰问。父亲说：「腿跌断了，怎知不是我们的福气呢？」过了一年，胡人入侵，当地年轻人都被召去作战，大多数人不幸战死，儿子却因为瘸腿，保全了性命。后来这个故事被浓缩成「塞翁失马，安知非福」或「塞翁失马」，用来比喻因祸得福。"},
  {"name": "三寸之舌", "cid": 296891, "pid": 11702075, "num": 246, "meaning": "犹「三寸不烂之舌」。见「三寸不烂之舌」条。01.《史记．卷七六．平原君虞卿列传．平原君》：「毛先生一至楚，而使赵重于九鼎大吕。毛先生以三寸之舌，彊于百万之师。」（源）02.《隋唐演义》第四一回：「全凭弟三寸之舌，用一夕话，务要说他来同事，方见平昔间交情。」", "source": "", "example": "", "story": "此处所列为「三寸不烂之舌」之典故说明，提供参考。舌头是说话的主要器官，长约三寸，古人多用「三寸舌」或「三寸之舌」来表示口才。例如《史记．卷七六．平原君虞卿列传．平原君》载，战国时，秦国攻打赵国，首都邯郸被围，情况相当危急。赵王派平原君到楚国求援，想联合楚国来抵抗秦国。平原君要从门下食客选二十个人一起去楚国，但挑来挑去只挑到十九人，还剩一个人挑不出来，有个叫毛遂的人便自我推荐，平原君姑且接纳了他。到了楚国，平原君一直不能说服楚王援助赵国。毛遂仗剑向前，向楚王分析情势，义正辞严，气势凌人，楚王便答应与赵国订立盟约。平原君完成任务回到赵国后，赞赏毛遂说：「毛先生一到楚国，就使我们赵国的地位大大提升，比九鼎大吕还要有分量。毛先生三寸的舌头，真是比百万军力还要强大。」自此便一直将毛遂奉为上宾。另外如《史记．卷五五．留侯世家》，内容则是表述汉高祖刘邦的军师张良，在协助刘邦平定天下后，动了归隐的念头。他推荐萧何担任丞相，并向刘邦表达自己凭著「三寸舌」成为皇帝的军师，位极人臣，已达到一般人最想要的目标了，于愿足矣！所以希望能辞去职务，隐居修道。"},
  {"name": "三顾茅庐", "cid": 296891, "pid": 11702076, "num": 247, "meaning": "指汉末刘备往访诸葛亮，凡三次，才得见。◎语本三国蜀．诸葛亮〈前出师表〉。后用「三顾茅庐」比喻对贤才真心诚意的邀请、拜访。\n△「初出茅庐」", "source": "三国蜀．诸葛亮〈前出师表〉（据《三国志．卷三五．蜀书．诸葛亮传》引）\n《三国志．卷三五．蜀书．诸葛亮传》", "example": "董事长以三顾茅庐的诚心，到处延揽人才。", "story": "东汉末年天下纷乱，打著「复兴汉室」名号起兵的刘备，在屯田新野时，从徐庶口中得知避居在南阳隆中的诸葛亮是个能人，于是前去拜访，一连去了三次，才见到人。诸葛亮在〈前出师表〉中提到了这件事：「先帝不以臣卑鄙，猥自枉屈，三顾臣于草庐之中。」刘备不顾身分，一连三次专程拜访的诚心，终于感动诸葛亮答应出山替他奔波效力。后来「三顾茅庐」这句成语就从这里演变而出，用来比喻对贤才真心诚意的邀请、拜访。"},
  {"name": "三生有幸", "cid": 296891, "pid": 11702077, "num": 248, "meaning": "三生：佛家指前生、今生、来生；幸：幸运。三世都很幸运。比喻非常幸运。", "source": "元・王实甫《西厢记》第一本第二折：“今能一见，是小生三生有幸矣。”", "example": "", "story": "三生有幸"},
  {"name": "丧家之犬", "cid": 296891, "pid": 11702078, "num": 249, "meaning": "无家可归的狗。比喻无处投奔，到处乱窜的人。", "source": "明・兰陵笑笑生《金瓶梅词话》第47回：“忙忙如丧家之犬，急急如漏网之鱼。”", "example": "敌人溃不成军，惶惶如～。", "story": "春秋时，孔子周游列国推广主张，常遭冷遇。一次在郑国与弟子走散，有人对子贡说：东门口那个人，狼狈得像丧家之犬。孔子听后笑着说：形容我的样子倒挺恰当。此词指无处安身的可怜人。"},
  {"name": "丧心病狂", "cid": 296891, "pid": 11702079, "num": 250, "meaning": "「丧心」，失掉本心。语出《左传．昭公二十五年》。「病狂」，疯狂的病症。语出《汉书．卷七三．韦贤传》。「丧心病狂」指丧失理性，举止荒谬、反常。亦用来形容人残忍可恶到了极点。\n△「丧尽天良」", "source": "「丧心」：《左传．昭公二十五年》\n「病狂」：《汉书．卷七三．韦贤传》", "example": "这种丧心病狂的匪徒，天理难容。", "story": "「丧心病狂」系由「丧心」及「病狂」二语组合而成。\n「丧心」见于《左传．昭公二十五年》。根据记载，春秋时，鲁国使节叔孙婼（ㄖㄨㄛˋ）到宋国访问，并代表季孙氏迎娶宋元公的女儿。宴会上，当大家喝得正愉快时，宋元公和坐在身旁的叔孙婼哭了起来。佐礼的乐祁在退席后就对别人说：「国君和叔孙婼恐怕快要死了！我曾经听说过：『应该悲伤的时候却欢乐，应该欢乐的时候却悲伤，是丧失心性的举动。』心的精神是魂魄，魂魄丧失了，怎么能活得长久？」这里的文献原文就用了「丧心」一语。\n「病狂」则见于《汉书．卷七三．韦贤传》。扶阳侯韦贤有四个儿子，大儿子早逝，所以二儿子韦弘为爵位的继承人。当韦贤病重时，韦弘正好被关在牢里等待判决，族人问他谁是继承人，他因为怨恨自己的儿子受罪而不肯说。于是他的门生义倩等人和族人假传他的命令，上书朝廷说他的少子玄成是爵位继承人。玄成接到父丧和继承爵位的消息，但他知道这不是父亲的本意，于是假装生了疯病，在床上大小便，任意发笑，胡乱说话。到了长安，等父亲下葬后，以疯病为理由拒绝征召继承爵位。这里的文献原文就用了「病狂」一语。后来「丧心」和「病狂」被合用成「丧心病狂」这句成语，用来指丧失理性，举止荒谬、反常。亦用于形容人残忍可恶到了极点。"},
  {"name": "杀鸡焉用牛刀", "cid": 296891, "pid": 11702080, "num": 251, "meaning": "即「割鸡焉用牛刀」。见「割鸡焉用牛刀」条。01.《水浒传》第八五回：「常言道：杀鸡焉用牛刀。那里消得正统军自去？只贺某聊施小计，教这一伙蛮子死无葬身之地。」02.《精忠岳传》第四七回：「杀鸡焉用牛刀！谅一草寇，待末将等前去拏来；何劳元帅亲自出马？」", "source": "", "example": "", "story": "此处所列为「割鸡焉用牛刀」之典故说明，提供参考。春秋吴国人言偃，字子游，是孔子的学生，以文学著称。他在担任鲁国武城首长时，用礼乐教化百姓。有一天，孔子到武城，听到武城一片弦乐歌声，便微微笑说：「割鸡焉用牛刀？」意思是：杀鸡何必用宰牛的刀，以此来调侃子游，治理武城这么一个小地方，还须大费周章地动用礼乐教化吗？子游听后则回答说：「我曾经听老师您说过：『做官的学道，就会爱恤人民；老百姓学道，就会容易接受指挥。』」孔子立即向同行弟子表示子游的话是对的，自己刚才不过是说笑罢了。后来「割鸡焉用牛刀」被用来比喻处理小事，毋需大才。"},
  {"name": "伤风败俗", "cid": 296891, "pid": 11702081, "num": 252, "meaning": "伤、败：败坏。指败坏社会风俗。多用来遣责道德败坏的行为。", "source": "《魏书・游明根传附肇》：“肇，儒者，动存名教，直绳所举，莫非伤风败俗。”", "example": "纣王以为妲己好意，岂知内藏～之情，大坏纲常礼义之防。（明・许仲琳《封神演义》第十九回）", "story": "伤风败俗"},
  {"name": "盛气凌人", "cid": 296891, "pid": 11702082, "num": 253, "meaning": "凌，欺侮。「盛气凌人」指用傲慢的气势压迫别人。语本宋．楼钥《攻媿集．卷八八敷文阁学士宣奉大夫致仕赠特进汪公行状》。_x000D_\n△「仗气凌人」、「咄咄逼人」", "source": "宋．楼钥《攻媿集．卷八八．敷文阁学士宣奉大夫致仕赠特进汪公行状》", "example": "他就是得到冠军，也不必如此盛气凌人！", "story": "「盛气凌人」原作「盛气临人」。典故出自宋代楼钥《攻媿集．卷八八．敷文阁学士宣奉大夫致仕赠特进汪公行状》一文。文章中提到当时户部侍郎李椿年建议重新丈量民田的经界，朝廷选派汪大猷担任龙游县的覆勘官。当时李椿年的规定十分严峻，凡是丈量过的田，重新勘验，如有隐藏，不论多少，一律处以黥刑，流放到远方。因为气势压迫于人，所以人民纵有不服，也没有敢跟他对抗的。后来「盛气凌人」这句成语就从这里演变而出，指用骄横的气势压迫别人。但是这条成语也有人认为出自于较早的唐．孙元晏〈咏史〉诗中的〈谢澹云霞友〉。诗云：「仗气凌人岂可亲，只将范泰是知闻。缘何唤作云霞友？却恐云霞未似君。」据《南史．卷一九．谢晦列传》，南朝宋谢晦的堂叔谢澹，是谢安的孙子。澹为人任达仗气，和当时的范泰结为「云霞之交」。他颇受宋武帝赏识，所以原来要托付他在受禅时，担任进奉玉玺的大任。但是有一次陪武帝吃饭时，谢澹不但喝醉酒，还大言不会屈顺任何人的意思。武帝虽因谢澹是方外之士，不与他计较，但是心里著实不高兴，也就不让他进奉玉玺了。由这个故事可知，谢澹的「仗气凌人」是恃才傲物的意思，和「盛气凌人」的用法不同。"},
  {"name": "贪得无厌", "cid": 296891, "pid": 11702083, "num": 254, "meaning": "厌：满足。贪心永远没有满足的时候。", "source": "《四游记・三至岳阳飞度》：“洞宾叹曰：‘人心贪得无厌，一至于此！’”", "example": "他～的性子，随着年岁的增长，更加残忍了。（梁斌《红旗谱》八）", "story": "春秋时，晋国的知伯贪心不足，向韩、魏两家索要土地。他得到一块还想要更多，贪得无厌。韩魏两家忍无可忍，联合赵家反过来灭了知氏。后来“贪得无厌”警告人贪心太多终会害了自己。"},
  {"name": "贪多务得", "cid": 296891, "pid": 11702084, "num": 255, "meaning": "贪：求多；务：务必。原指学习上务求尽多地获得知识。后泛指对其他事物贪多并务求取得。", "source": "唐・韩愈《进学解》：“贪多务得，细大不捐。”", "example": "而泛观古人之文，则又博而寡要，且惧夫～，而遂溺于文。（清・方宗诚《古文简要序》）", "story": "唐朝文学家韩愈在《进学解》中写自己读书：贪多务得，细大不捐。意思是哪怕再小的知识也要学，力求广博。原本是褒义，称赞勤学。后来也用来批评人贪心，什么都想占为己有。"},
  {"name": "贪生怕死", "cid": 296891, "pid": 11702085, "num": 256, "meaning": "贪：舍不得。贪恋生存，畏惧死亡。指对敌作战畏缩不前。", "source": "东汉・班固《汉书・文三王传》：“今立自知贼杀中郎曹将，冬日迫促，贪生畏死，即诈僵仆阳病，徼幸得逾于须臾。”", "example": "他们没有一个～而逃跑的，他们知道多一个人多一分力量。（曲波《林海雪原》二）", "story": "西汉时，梁王刘立犯了死罪，冬天将到，他上书说自己也怕死，想拖延时间。书中用了“贪生畏死”一语。后来演成“贪生怕死”，指人只顾保命、临危退缩。人们常用它批评懦弱的人。"},
  {"name": "贪小失大", "cid": 296891, "pid": 11702086, "num": 257, "meaning": "因贪图小利而造成重大损失。＃语本《吕氏春秋．慎大览．权勋》。\n△「得不偿失」", "source": "＃《吕氏春秋．慎大览．权勋》*1*", "example": "投资要把眼光放得长远些，以免贪小失大，后悔莫及。", "story": "根据《吕氏春秋．慎大览．权勋》的记载：战国时代，燕将乐毅率领五国（燕、秦、韩、魏、赵）的军队攻打齐国，齐王派触子领军迎战于济水之上。在敌众我寡的情况下，触子深感为难，齐王却出言羞辱威胁以逼使他出战。结果触子虽然勉强出战，却故意使齐军败北，而他自己就乘机逃得无影无踪。后来齐国的另一将军达子又率领残兵，驻守在国都城门，为了激励士气，只好向齐王请求赏金，齐王不但不给，还把他怒骂一顿。这一来，达子与燕军交战，当然大败，不但达子阵亡，齐王也逃到莒邑。燕军追入城门，就趁势把齐国金库所藏的金子掠夺一空，这就是「贪于小利以失大利」的好例子。后来「贪小失大」这句成语就从这里演变而出，用于表示因贪图小利而造成重大损失的意思。"},
  {"name": "螳螂捕蝉", "cid": 296891, "pid": 11702087, "num": 258, "meaning": "螳螂只顾著捕蝉，不知有大鸟在身后正要啄食牠。＃典出《庄子．山木》。后用「螳螂捕蝉」比喻眼光短浅，只贪图眼前的利益而忽略背后隐藏的危险。", "source": "＃《庄子．山木》*1*", "example": "他一心都在算计别人，没想到这次竟然螳螂捕蝉，被人暗算了。", "story": "有一天，庄子在雕陵闲游，看到一只奇特的大鸟飞进别人的栗园里，停在树上。他不知不觉地被大鸟吸引，提起衣服下摆走进园中，想用弹弓射下大鸟。他走过去，往树丛里望，发现有只蝉躲在树荫里，因为太舒适而松懈下来，完全不知道身后有只螳螂，用树叶遮蔽，正扑身向前抓牠。那只螳螂抓到蝉后，得意洋洋的，同样也没警觉到身后有只大鸟，正伸著脖子啄牠。庄子看到这种情形，有所警惕，悟得「利益」与「祸患」相连相倚的道理，于是丢下弹弓，转身便要离开，但被守园人发现而指责了一顿。此事让庄子闷闷不乐了三天，并体悟到唯有随时保有真我，不为外物干扰，才能避于祸害。「螳螂捕蝉」这句成语就是由这故事浓缩而来，用来比喻眼光短浅，只贪图眼前的利益而忽略背后隐藏的危险。另外，在汉朝刘向《说苑》中亦载有一事：春秋时代，吴王想发兵攻打楚国，而且不准任何人对此事进谏。有个随侍想劝阻他，却又不敢，于是故意在早上拿著弹弓到庭院里，让露水沾湿他的衣服。如此连续三天，吴王问他说：「你为什么要这样呢？」他便回答：「有只蝉在树上唱歌，不知螳螂在后面要抓牠。同样的，螳螂忙著捕蝉，也不知道身后有只黄雀要吃牠。黄雀则是伸著脖子要啄螳螂，也不知道我在树下准备把牠射下。牠们三个都只顾眼前的利益，完全无暇顾及身后的危险。」吴王听了，警觉到有许多国家正对吴国虎视眈眈，恐怕会利用吴国专力伐楚时乘隙进攻，于是便打消攻楚的念头。由于这个故事，于是有了「螳螂捕蝉，黄雀在后」的成语，与单用「螳螂捕蝉」一语同义。"},
  {"name": "天经地义", "cid": 296891, "pid": 11702088, "num": 259, "meaning": "天地间原本如此而不容改变的道理。语本《左传．昭公二十五年》。\n△「理所当然」", "source": "《左传．昭公二十五年》", "example": "要有收获就得耕耘，这是天经地义的事。", "story": "根据《左传》记载：鲁昭公二十五年的夏天，叔诣和晋国赵鞅、宋国乐大心、卫国北宫喜、郑国游吉等在黄父会盟，商讨安定王室的事情。赵鞅令诸侯的大夫们给周天子输送粮食，准备好戍守的将士，并说：「明年将要送天子回王城。」子太叔游吉进见赵鞅，赵鞅问他揖让进退的礼节。子太叔回答：「这是仪，不是礼。」赵鞅再问：「那什么叫做礼呢？」子太叔回答说：「我曾听先大夫子产说过：『礼，是上天的规范，大地的准则，人民的行事依据。』天地的规范准则，人民就加以效法。」后来「天经地义」这句成语，就从《左传》文中「天之经也，地之义也」演变而出，指天地间原本如此而不容改变的道理。"},
  {"name": "天罗地网", "cid": 296891, "pid": 11702089, "num": 260, "meaning": "天空地面遍布罗网。比喻防范极为严密，无法逃脱。＃语出《大宋宣和遗事．亨集》。", "source": "＃《大宋宣和遗事．亨集》*1*", "example": "警方已设下天罗地网，诱捕嫌犯。", "story": "「罗」，是捕鸟的网子。天上地下都布满了网子，表示被严密地包围，难以逃脱。《大宋宣和遗事．亨集》中，贾奕与李师师本是一对恋人，但因为李师师受到天子宠爱，贾奕不敢冒渎，只好忍痛和李师师分手。不料贾奕的心情尚未平复，又被高俅陷害，下于狱中，难以逃脱。「才离阴府恓惶难，又值天罗地网灾。」就是形容贾奕命运多舛，一波未平，一波又起。后来「天罗地网」这句成语被用来比喻防范布置得极为严密而无法逃脱。另在元．施惠《幽闺记》第二〇出中，主角亦用「离天罗，入地网」形容自己落入山贼之手，逃生无望的处境。"},
  {"name": "天衣无缝", "cid": 296891, "pid": 11702090, "num": 261, "meaning": "古代传说天神的衣服，不用针线缝制，故没有缝痕。＃典出《神异经》。后用「天衣无缝」比喻诗文浑然天成，没有斧凿痕迹；亦用于比喻事物或计划周密完美，没有一丝破绽或缺点。", "source": "＃《神异经》（据《太平御览．卷六八五．服章部二．委貌冠》引）*1*", "example": "这篇推理小说的结构，简直是天衣无缝、无懈可击。", "story": "《神异经》大约是一本汉代的小说。此书是在《山海经》的影响下产生的，不论是在内容、笔法等各方面都有意模仿《山海经》，只是作者另外添加了神仙方术和儒家思想的观念在其中。《神异经》记载了一段故事：西方边远的地方有一些人，他们不必阅读传统的典籍巨著，但行为思想，却能合乎礼仪规范。天神赐给他们衣服，男的穿著红色衣服，白色腰带，戴著帽子；女的穿著绿色衣服，戴著华丽的首饰。这些天衣不是用一般凡间针线缝制，所以都没有缝痕。后来这个故事被浓缩成「天衣无缝」，用来比喻诗文浑然天成，没有斧凿痕迹；亦用于比喻事物或计划周密完美，没有一丝破绽或缺点。"},
  {"name": "天真烂漫", "cid": 296891, "pid": 11702091, "num": 262, "meaning": "「天真烂漫」之「烂漫」，典源作「烂熳」。「烂熳」同「烂漫」。「天真烂漫」形容性情率真，毫不假饰。＃语本宋．龚开〈高马小儿图〉诗。", "source": "＃宋．龚开〈高马小儿图〉诗（据元．吴师道《吴礼部诗话》引）*1*", "example": "小孩子们个个天真烂漫、活泼可爱。", "story": "「天真烂漫」典源作「天真烂熳」。龚开，江苏淮阴人，为南宋著名画家。他最喜爱画鬼怪和锺馗，风格奇特，但可惜存世的作品极少。〈高马小儿图〉为其画作之一，此画描绘了一名沙陀族少年与一匹骏马，画中并赋有一诗，述载此画作产生之背景。其中四句「此儿此马俱可怜，马方三齿儿未冠。天真烂熳好容仪，楚楚衣装无不宜」，意思是说：画中骏马约才三岁，少年亦青涩未成年，他们的神态天真无邪，毫不矫饰，两者的组合惹人喜爱，似乎无论以什么样光鲜整齐的衣著来装饰都将十分合适。后来「天真烂漫」这句成语就从这里演变而出，用来形容性情率真，毫不假饰。出现「天真烂漫」的书证如宋．岳珂《宝真斋法书赞．卷五．张长史春草三帖跋》：「长史以草圣得名，盖其天真烂漫，妙入神品，而非矩矱步武者。」长史即张长史，指的是盛唐时著名书法家张旭，他极好喝酒，酒后形骸放浪，意气洒脱，放荡不羁。而其字又如其人，挥洒之间，笔势奇特奔逸、连绵回绕，故有「草圣」之称。岳珂评张旭之所以能为「草圣」，乃因其性格率真，不为传统规矩所拘束，故能创造出新的风格。"},
  {"name": "同仇敌忾", "cid": 296891, "pid": 11702092, "num": 263, "meaning": "「同仇」，一致对抗仇敌。语出《诗经．秦风．无衣》。「敌忾」，抵御怨恨的人。语本《左传．文公四年》。「同仇敌忾」指共同抵御仇敌。", "source": "「同仇」：《诗经．秦风．无衣》\n「敌忾」：《左传．文公四年》", "example": "将士们热血滔滔、同仇敌忾，这场战争必胜无疑。", "story": "「同仇敌忾」系由「同仇」及「敌忾」二语组合而成。\n「同仇」出自《诗经．秦风．无衣》，内容是说：即使没有足够的衣服，仍然可以共穿战袍，整理武器，一起杀敌。描述了慷慨赴战的志气，反映战士之间的友谊，从穿衣到杀敌，都愿意患难与共。\n「敌忾」则是出自《左传．文公四年》，内容叙述宁武子婉转批评了鲁国僭用天子的歌乐。卫国的宁武子到鲁国访问，文公设宴款待，席间文公命乐工们演奏〈湛露〉和〈彤弓〉两首诗歌。宁武子没有辞谢，也没有赋诗应和，按当时的外交礼节而言，是很失礼的。于是文公派管理礼宾事务的官员私下探问原因，宁武子说：「我以为那两首诗歌是乐工为了练习而演奏的，因为它们是演奏于天子的宴会。以前诸侯在正月时，前往京师向天子朝贺，天子设宴奏乐，此时赋〈湛露〉，就表示诸侯愿意共同抵御天子所痛恨的人，为天子效命。天子因此赐给他们红色和黑色的弓、箭，以彰显他们的功劳，并设宴乐酬赏。现在我只是奉命来继续两国的友好关系，承蒙君王赐宴，岂敢触犯大礼而自取罪过呢？」后来这两个典源被合用成「同仇敌忾」，用来指共同抵御仇敌。也作「敌忾同仇」。"},
  {"name": "同工异曲", "cid": 296891, "pid": 11702093, "num": 264, "meaning": "即「异曲同工」。见「异曲同工」条。01.唐．韩愈〈进学解〉：「下逮庄骚，太史所录，子云相如，同工异曲。」（源）", "source": "", "example": "", "story": "此处所列为「异曲同工」之典故说明，提供参考。「异曲同工」原作「同工异曲」。「曲」指曲调，「工」指巧妙。韩愈是唐代的著名文人，他精通六经百家，崇尚儒学，排斥佛老，文章自成一家，为后世治古文者所取法。其登进士第后，曾任国子博士、监察御史等职，却因直言敢谏，屡次被贬，久久不得升迁。韩愈自认才高，不应受此待遇，因此作〈进学解〉一文自嘲。文中叙述一日国子先生教诲学生说：「学业要精进，就要勤勉；学业之所以荒废，就是因为嬉戏。」学生却回说：「老师您如此勤勉向学，作品的旨趣，及得上《庄子》、《楚辞》的宏肆深奥，写作技巧也如同《史记》般丰富，能力比得上扬雄、司马相如等人，虽然风格不同，但是技巧造诣是一样的高明，内容丰富，文笔豪放。您如此努力，却屡次被黜，官运不顺，自己都该好好想想，干嘛还训示别人！」文中的国子先生即韩愈自称，韩愈藉著别人的口吻，宣泄自己怀才不遇的愤慨，原用以自嘲。后来「异曲同工」这句成语就从这里演变而出，原用来比喻不同人的辞章或言论同样精彩，后则用于比喻不同的作法收到同样的功效。"},
  {"name": "同心同德", "cid": 296891, "pid": 11702094, "num": 265, "meaning": "心：思想；德：信念。指思想统一，信念一致。", "source": "《尚书・泰誓》：“受有亿兆夷人，离心离德。予有乱臣十人，同心同德。”", "example": "郭沫若《归国杂吟》：“四万万人齐蹈厉，～一戎衣。”", "story": "周武王伐纣前，在《泰誓》中说：受（纣王）有亿万臣子，却各有各的心；我有乱臣十人，却同心同德。正因上下齐心，周军终在牧野大胜。此词指众人目标一致、团结奋斗。"},
  {"name": "痛定思痛", "cid": 296891, "pid": 11702095, "num": 266, "meaning": "事后追思当时所遭的痛苦，也不知如何处理，而更加伤心。语本唐．韩愈〈与李翱书〉。后也用「痛定思痛」比喻吸取惨痛教训，警惕未来。", "source": "唐．韩愈〈与李翱书〉（据《全唐文．卷五五二．韩愈》引）", "example": "父母之丧，如何能忘？痛定思痛，痛何如哉！", "story": "韩愈，字退之，唐河阳人。他自幼父母双亡，由兄嫂抚养长大。后来哥哥死于贬谪之地，靠著嫂嫂教养成人。艰苦的环境并没有限制韩愈的志气，他努力读书，终于如愿在朝廷为官。但个性耿直的韩愈，屡次犯颜直谏，因而被一再贬黜。在韩愈给他弟子李翱的〈与李翱书〉中提及：他在京八九年，没有收入，都靠求人度日，过得非常辛苦。在心灵上也留下不小的创伤。事过之后，回想起当时的情形，更是令人伤心得不知如何自处。可见他是如何地志不得伸。后来「痛定思痛」这句成语就从这里演变而出，用来比喻吸取惨痛教训，警惕未来。"},
  {"name": "痛心疾首", "cid": 296891, "pid": 11702096, "num": 267, "meaning": "疾首，头痛。心中痛恨到头都痛了。比喻痛恨到极点。语出《左传．成公十三年》。_x000D_\n△「咬牙切齿」、「深恶痛绝」", "source": "《左传．成公十三年》*1*", "example": "这些痛心疾首的往事，不提也罢！", "story": "据《左传．成公十三年》载，春秋时代鲁成公十三年四月，因为秦国违背双方在令狐订立的盟约，于是晋侯派吕相出使秦国，目的是断绝两国的盟友关系。吕相传达的内容大致上说：「晋献公和秦穆公时，两国关系十分密切，不但订立盟约，还结为姻亲。之后秦穆公又帮助在外流亡的晋公子重耳，返国当上国君。但是两国为了国界的问题，秦国的态度反复，时常来犯。为了解决纷争，最后两国订立『令狐之盟』，没想到秦国不但背弃盟约，并且和楚国结盟，对上天和秦国、楚国的历代先君盟誓说：『秦国虽然和晋国结交往来，但只追求利益，不顾其他。』事实上，楚人厌恶秦国的反复无常，于是转告晋国，要好好惩罚意志不专一的秦国。其他诸侯知道这件事后，也都痛恨秦国到了极点，大家都来亲近晋国。晋国要秦国做个了断，是要战争还是要和平共处。」同年五月，晋国和诸侯国联军，打败秦国。后来原文中的「痛心疾首」演变为成语，用来指痛恨到极点。"},
  {"name": "痛饮黄龙", "cid": 296891, "pid": 11702097, "num": 268, "meaning": "泛指打败敌人而开怀畅饮。见「直捣黄龙」条。01.《精忠岳传》第七七回：「丹心誓补前人事，浩气临戎不顾身；痛饮黄龙雪旧耻，平吞鸭绿报新君。」", "source": "", "example": "", "story": "此处所列为「直捣黄龙」之典故说明，提供参考。「黄龙」是指黄龙府，在今吉林省境，宋朝时为金人的都城。「直捣黄龙」本来是岳飞讨伐金人时，以直抵金人都城黄龙府与部下相激勉，所采取的应战策略。后来扩大引申，除了战事以外，也可以用在各种竞赛中，为了争取胜利所用的策略，直接深入对方内部要地。《宋史．卷三六五．岳飞列传》提到，岳飞在对抗金人的战役中，屡战屡胜，士气高昂。自燕京以南，金兵的号令无法施行，许多金朝的将领、官兵也都率领部众向岳飞投降。岳飞的军队士气大振，岳飞也很高兴，就勉励将士说：「我们要深入敌军，直接攻克金人的都城黄龙府，然后大家就可以痛快地尽情喝酒以资庆祝！」后来「直捣黄龙」这个成语就从这里演变而出，用以借指直接进击敌方都城、巢穴。"},
  {"name": "推心置腹", "cid": 296891, "pid": 11702098, "num": 269, "meaning": "把赤忱之心推到人家肚子里。比喻以至诚待人。＃语本《东观汉记．卷一．光武帝纪》。", "source": "＃《东观汉记．卷一．光武帝纪》", "example": "他对朋友向来推心置腹，坦诚相待。", "story": "据《东观汉记．卷一．光武帝纪》载，西汉末年，王莽篡汉，改国号为「新」，推行改革政策，却因法令烦苛，弄得民不聊生，四方分裂。此时刘秀兄弟也以恢复汉室为号召，拥立刘玄为更始皇帝，加入反王莽政权的阵容。刘秀待人诚恳，擅于用兵，军民悦服。邯郸一役，刘秀大败莽军，被刘玄封为萧王。后来刘秀又北上击败强大的铜马军以及其他的割据势力，战败军队纷纷投降。刘秀收编降卒，原先的首领也都分派官职。但是这些首领们仍然心存疑虑，深怕刘秀终会对他们不利。刘秀看出他们的心态，就下令让他们仍然回去带领自己的部队，自己只带著极少的随从前去巡察。降将们看到刘秀对他们毫无戒心，十分信赖，便说：「萧王把他的赤诚之心都推移到人家的肚子里了，我们怎能不舍命回报呢？」后来「推心置腹」这句成语就从这里演变而出，比喻以至诚待人。"},
  {"name": "完璧归赵", "cid": 296891, "pid": 11702100, "num": 270, "meaning": "蔺相如奉使秦国，交涉以和氏璧换取秦国十五城时，识破秦国的诡诈，用计使璧安然回到赵国。语本《史记．卷八一．廉颇蔺相如列传》。后用「完璧归赵」比喻物归原主。\n△「怒发冲冠」、「价值连城」", "source": "《史记．卷八一．廉颇蔺相如列传》", "example": "你捡到的棒球手套，既知失主，理当完璧归赵。", "story": "战国时代，秦王想用十五座城池换取赵国的和氏璧。赵王因宦者令缪贤推荐，召见蔺相如，并且问他对这件事的看法。蔺相如不想使秦国有攻打赵国的借口，主张送和氏璧到秦国去，完成与秦国十五座城池的交换。并说：「君王如确定没有合适的人选，我愿意带著和氏璧出使。秦国真的给城，璧就留给秦国；不给，我会将和氏璧完好的送回赵国。」于是赵王派他带著和氏璧西行入秦国。到了秦国，蔺相如发觉秦王并不是真正想用十五座城池来交换和氏璧，于是在秦王欣赏和氏璧时，假意的说璧上有瑕疵要指给秦王看。等和氏璧回到他的手上，立刻后退了几步，倚柱而立，气得头发竖立，顶起帽子，便以要击碎和氏璧来威胁秦王。秦王没有办法，只好答应他斋戒五天的要求。蔺相如就趁著五天的缓冲时间，暗中派人将和氏璧送回赵国。秦王发觉，已经来不及挽回，为了显示自己的度量大，只好放蔺相如回到赵国。「完璧归赵」这句成语就从这里演变而出，用来比喻物归原主。"},
  {"name": "玩火自焚", "cid": 296891, "pid": 11702108, "num": 271, "meaning": "玩火的人，反倒烧死自己。比喻盲动、蛮干的人最后将自食恶果。语本《左传．隐公四年》。\n△「治丝而棼」、「众叛亲离」", "source": "《左传．隐公四年》", "example": "玩火自焚的军事狂人，古今中外，不胜枚举。", "story": "据《左传．隐公四年》载，春秋时代，卫国公子州吁（ㄒㄩ）弑兄夺位，多数大臣百姓都不赞成他的行为，所以州吁打算出兵攻伐与卫国有世怨的郑国，希望能借此提高自己的威望。恰巧当时宋国殇公即位，郑国收留了从宋国出奔的公子冯，并且想要用武力送他回国为君。州吁便以此为名，联合宋、陈、蔡等国出兵攻打郑国。但四国联军连续打了五日，都无法攻入郑国城门，无功而返。鲁隐公就此事问大夫众仲说：「你觉得州吁的计谋最后会得逞吗？」众仲回答：「我只听过以德服人，没听过以战乱为手段可以让人心悦诚服。以乱服人，就像要整理丝线却不先找出头绪，只会让情况愈来愈糟。州吁这个人仗著强大的武力，进行残忍的征伐，总有众人反叛，亲信背离的一日，他的计谋显然难以得逞。况且用兵就像是玩火一样，如果不知节制，终究会引火上身，烧死自己。」后来，四国联军又再次出兵攻郑，虽然取得了胜利，但州吁并未因此而获得百姓的爱戴，反而在不久后就被杀了。果然如众仲的预言般，州吁最后真的害死了自己。后来「玩火自焚」这句成语就从这里演变而出，用来比喻盲动、蛮干的人最后将自食恶果。"},
  {"name": "玩物丧志", "cid": 296891, "pid": 11702109, "num": 272, "meaning": "一味玩赏珍奇异品，因而丧失了原有的壮志。语出《书经．旅獒》。后来「玩物丧志」用来形容沉溺于某样事物，因而荒废了应做的事。", "source": "《书经．旅獒》", "example": "他要不是沉迷于网咖，玩物丧志，岂会荒废了学业？", "story": "西周时，武王姬发遵其父文王之遗志，即位的第二年起兵灭商纣，取得了天下，建立周王朝。从此武王威名远播，中原地区外的部族首领，常进贡奇珍异物。有一次，西戎进贡了一种特有的獒犬，武王因仍陶醉于灭纣的战功中，所以放纵自己，耽于逸乐，整天与獒犬游猎嬉戏，荒废了朝政。朝中大臣召公见此情况，便作〈旅獒〉一文劝谏武王，其中有两句话说：「一味把人当成玩弄的对象，那是丧失做人的道德；一味玩赏器物，将丧失原有的雄心壮志。」武王于是从善如流，收敛心性，重新回到政务上，专心于国事。后来「玩物丧志 」被用来形容沉溺于某样的事物，因而荒废了应做的事。"},
  {"name": "万事俱备，只欠东风", "cid": 296891, "pid": 11702110, "num": 273, "meaning": "一切都准备好了，只差东风没有刮起来，不能放火。比喻什么都已准备好了，只差最后一个重要条件了。", "source": "明・罗贯中《三国演义》第49回：“欲破曹公，宜用火攻；万事俱备，只欠东风。”", "example": "我们现在是～，只要机器一来，马上就可以安装了。", "story": "三国赤壁之战，周瑜定火攻之计，船、薪、诈降都备好，只差东南风。诸葛亮预测将有东风，筑坛借风，火攻大破曹军。后来“万事俱备，只欠东风”指什么都齐了，就差最关键的一件。"},
  {"name": "妄自尊大", "cid": 296891, "pid": 11702111, "num": 274, "meaning": "狂妄地自尊自大。语出《后汉书．卷二四．马援列传》。\n△「不修边幅」、「夜郎自大」", "source": "《后汉书．卷二四．马援列传》", "example": "稍有成就就妄自尊大的人，难成大器。", "story": "王莽末年，群雄四起，经过几次的争战后，就属隗（ㄨㄟˇ）嚣、公孙述、刘秀三人的势力最大。据《后汉书．卷二四．马援列传》载，隗嚣派马援前往蜀地探探公孙述的实力，马援和公孙述原是旧识，所以马援本以为他俩这次见面，一定可以像从前一样无所不谈。没想到马援抵达蜀地后，公孙述却摆出帝王的大场面，还要以皇帝的名义，给马援封爵。马援很不高兴，私底下跟公孙述左右的人说：「现在是谁的天下都还未底定，公孙述不趁现在去求取贤士，帮自己争天下，反而在这里讲排场，自以为是皇帝，天下英才如何会久留？」于是就告辞走了。马援回去对隗嚣说：「公孙述只是井底之蛙而已，却狂妄自大。你根本不用担心他这股势力，只要专心全力对付刘秀就够了！」后来原文中的「妄自尊大 」就用来指毫无根据的自尊自大。"},
  {"name": "望尘莫及", "cid": 296891, "pid": 11702112, "num": 275, "meaning": "只能远望前面车马扬起的尘土，而无法赶得上。比喻远远落在他人之后。＃语本《庄子．田子方》。\n△「失之交臂」、「亦步亦趋」、「奔逸绝尘」、「瞠乎其后」", "source": "＃《庄子．田子方》*1*", "example": "他能力太强了，让我们望尘莫及。", "story": "「望尘莫及」的意思就是看著前面的人扬起的灰尘自己却无法赶上。这句成语或者是出自于《庄子．田子方》。《庄子．田子方》中有一段孔子和颜渊的故事：有一天颜渊请教孔子：「夫子走的时候，我也跟著走；夫子快步走，我也跟著快步走；夫子快跑时，我也跟著快跑。可是当夫子奔走速度达到非常快速的时候，我却只能在后面瞪著眼睛直看。」颜渊所要表达的意思是，孔子做什么，他也跟著做什么，但是却发现某些地方是无法跟上脚步的。有些时候，孔子不需要说什么，众人就自然信服；不曾亲近或偏袒，但情意却自然而周到；没有爵位，而百姓却自然的归向。这些在颜渊的心中，一直无法解释是什么缘故，总觉得孔子像是在前面快速奔跑，自己在后面，却怎么样也追不上。《庄子》原文的「夫子奔逸绝尘，回瞠若乎后者」，后来也许就演变成「望尘莫及」这句成语，用来比喻远远落在他人之后。"},
  {"name": "望梅止渴", "cid": 296891, "pid": 11702113, "num": 276, "meaning": "曹操编造前方梅林结了很多果实，诱使士兵流出口水以解渴的故事。典出南朝宋．刘义庆《世说新语．假谲》。后用「望梅止渴」比喻以空想来安慰自己。\n△「画饼充饥」", "source": "南朝宋．刘义庆《世说新语．假谲》", "example": "他没钱买别墅，只好天天看著房屋广告望梅止渴了。", "story": "东汉末年，曹操带领著大军要去讨伐张绣，走到半路，因为天气十分炎热，又找不到水源，身上揹著沉重行囊的士兵个个都又渴又累。此时足智多谋的曹操，心生一计，就对士兵们说：「弟兄们，前面不远的地方有一大片的梅林，结满了又酸又甜的果实，可以生津解渴。」士兵们听到之后，每个人脑中都想起梅子那酸中带著甘甜的味道，嘴里不由自主的生出津液，精神为之一振，不再感到口渴。曹操借此终于找到水源，解除部队没水喝的窘境。后来这个故事被浓缩成「望梅止渴」，用来比喻以空想来安慰自己。"},
  {"name": "望门投止", "cid": 296891, "pid": 11702114, "num": 277, "meaning": "投止：投宿。在窘迫中见有人家就去投宿。比喻情况急迫，来不及选择存身的地方。", "source": "南朝・宋・范晔《后汉书・党锢传・张俭》：“俭得亡命，困迫遁走，望门投止，莫不重其名行，破家相容。”", "example": "你兄弟在外，隐姓埋名，或是找一个地方藏身，或是到处漂泊，～。（姚雪垠《李自成》第二卷第四十章）", "story": "东汉时，张俭因弹劾宦官被迫逃亡。一路上他看见谁家门就进去求宿，人们敬佩他的义气，甘冒杀头之险收留他。很多家庭因此遭难，却无一人后悔。后来“望门投止”形容仓皇避难。"},
  {"name": "望洋兴叹", "cid": 296891, "pid": 11702115, "num": 278, "meaning": "叹，同「叹」。「望洋兴叹」即「望洋兴叹」。见「望洋兴叹」条。01.元．刘埙《隐居通议．卷一〇．诗歌五》：「真能笼乾坤万里于一咏之内，千古吟人，望洋兴叹。」按：此指自叹不如。02.《糊涂世界》卷六：「佘念祖未到的时候，满心高兴，颇有跃跃欲试的意思，到过之后，大概情形看了一看，亦觉得望洋兴叹了。」按：此指无能为力。", "source": "", "example": "", "story": "此处所列为「望洋兴叹」之典故说明，提供参考。「望洋兴叹」本指看到海洋之大而仰视发出惊叹。典源出自于《庄子．秋水》。秋天洪水暴涨，许多小河，都带著丰沛水量，汇聚到黄河。黄河变得非常宽广，隔水相望，两岸的牛马都看不清楚。黄河的水神河伯，看著自己盛大的水流，不禁沾沾自喜，认为天底下最壮美的，全都在这儿了。他兴奋地顺著水流向东而行，一直到了北海。河伯向东边望去，只见白浪涛天，茫茫一片，看不到水的尽头。这时河伯才发现自己是多么渺小，心里觉得十分惭愧。他仰著头叹息说：「我本来以为自己很了不起，现在看到大海这么宽广无尽，才知道自己真是井底之蛙，眼光实在是太狭小了！」后来，「望洋兴叹」这句成语就从「望洋向若而叹」演变而出，用来比喻因力量不够而感到无可奈何。后人也有望文生义，误解「望洋兴叹」为对著大洋兴叹，此解不可取。"},
  {"name": "为虎作伥", "cid": 296891, "pid": 11702116, "num": 279, "meaning": "伥，音ㄔㄤ，传说中被虎吃掉后又供虎使唤的鬼。「为虎作伥」指被虎咬死的人，灵魂将化为鬼而为虎所役使。＃典出唐．裴铏《传奇》。后用「为虎作伥」比喻帮恶人做坏事。", "source": "＃唐．裴铏《传奇》（据《太平广记．卷四三〇．马拯》引）*1*", "example": "我真不知道他是这么坏的人，竟然为虎作伥当了帮凶。", "story": "唐朝时，流传著这么一个老虎吃人而且役使鬼魂的传说。在唐代裴铏《传奇》中可见此一传说：有一天，某处山上的两个人发现老虎吃完人后，竟脱掉虎皮，改穿禅衣，变成山上道场中的老和尚。这两个人非常害怕，想找个方法逃下山，就骗和尚说井里有异常的声音，待老和尚走到井边查看时，把他推落井去，老和尚马上化为老虎，两人就合力用大石头把老虎砸死，逃下山去了。将近黄昏的时候，他们遇到一个猎人，猎人在路边张开弓弩，设下暗箭，并在树上搭了一个棚子，住在上面。猎人对他们两人说：「不要触动我埋伏的机关。」又说：「这里离山下还很远，老虎又非常凶残，你们何不暂时到棚子上来避一避？」两人一听到老虎就很害怕，于是就爬了上去。两人惊魂未定，忽然看到三、五十人路过，有和尚，有道士，有男人，还有妇女，他们唱歌吟诗，玩笑起舞，吵吵闹闹地走到猎人张弓的地方。他们看到猎人架设的弓箭时，非常生气地说：「早上有两个家伙杀害了我们的老禅师，我们都还没找他们算帐呢，现在竟然还敢想要谋害我们将军！」就触发机关，把箭发出去，然后继续往前走。两个人听到这些话后，就问猎人是怎么回事。猎人说：「这些都是被老虎吃掉后又被控制的鬼，走在老虎前面吆喝开道的。」两人就要猎人重新张弓搭箭，后来老虎果然来了，前爪触到机关，一箭射中老虎，老虎就倒下死了。那些伥鬼也终于不必再受老虎控制，大家纷纷感谢猎人后就散去了。后来这个故事被浓缩成「为虎作伥」，用来比喻帮恶人做坏事。"},
  {"name": "围魏救赵", "cid": 296891, "pid": 11702117, "num": 280, "meaning": "原指战国时齐军用围攻魏国的方法，迫使魏国撤回攻赵部队而使赵国得救。后指袭击敌人后方的据点以迫使进攻之敌撤退的战术。", "source": "明・罗贯中《三国演义》第30回：“曹军劫粮，曹操必然亲往；操即自出，寨心空虚，可纵兵先击曹操之寨；操闻之，必速还。此孙膑‘围魏救赵’之计也。”", "example": "倘用～之计，且不来解此处之危，反去取我梁山大寨，如之奈何！（明・施耐庵《水浒全传》第六十四回）", "story": "战国时，魏国围攻赵都邯郸。齐王派田忌、孙膑救援。孙膑说：不如直捣魏都大梁，魏军必回自救，赵国之围自解。齐军依计，在桂陵大败回援的魏军。这就是著名的“围魏救赵”。"},
  {"name": "未可厚非", "cid": 296891, "pid": 11702118, "num": 281, "meaning": "厚非：过分责难、责备。不能过分责备。指说话做事虽有缺点，但还有可取之处，应予谅解。", "source": "东汉・班固《汉书・王莽传中》：“莽怒，免英官。后颇觉悟，曰：‘英亦未可厚非。’复以英为长沙连率。”", "example": "但叶遂宁和梭波里是～的，他们先后给自己唱了挽歌，他们有真实。（鲁迅《三闲集・在钟楼上》）", "story": "西汉末，王莽执政时，有大臣说对匈奴不该太宽。王莽却说：他们远来归顺，未可厚非，不能太苛责。意思是不能过分非难。后来“未可厚非”指不应过分责备，含有宽容、体谅之意。"},
  {"name": "纸上谈兵", "cid": 296891, "pid": 11702119, "num": 282, "meaning": "在文字上谈论用兵的策略。典出《史记．卷八一．廉颇蔺相如列传．赵奢》。后用「纸上谈兵」比喻不切实际的议论。_x000D_\n△「纸上空谈」", "source": "《史记．卷八一．廉颇蔺相如列传．赵奢》", "example": "这些想法都只是纸上谈兵，真正实施必有困难。", "story": "据《史记．卷八一．廉颇蔺相如列传．赵奢》载，战国时赵国名将赵奢的儿子赵括，从小熟读兵书，说起用兵的方法有条有理，自觉天下人都无法超越他。有一次，与父亲谈论起作战之道时，连父亲也都驳不倒他。可是赵奢并不认为这是一件值得称颂嘉许的事，并且告诉妻子说：「作战是一件攸关生命安危的事，而赵括却看得太容易了，将来赵王没有用他当将军就罢了，如果起用他，那么让赵国大败的一定就是赵括。」后来，秦国出兵攻打赵国，当时赵奢已经去世，相国蔺相如又病重无法辅政，只剩大将军廉颇独撑大局。廉颇治军有方，深谋远虑，他见秦军强大，不能硬拚，于是下令坚守营垒，不理秦军百般挑战，使秦兵久战无功。于是秦王便派出间谍，散布谣言说：「秦军最怕的是赵奢的儿子赵括统领大军。」结果赵孝成王竟中计想改派赵括替代廉颇，但赵括的母亲却上书表示反对，蔺相如也表示同样意见，说到：「赵括虽然熟读兵书，却不懂得灵活运用，非大将之才。」但赵王不听建言，还是派了赵括领兵抗秦。赵括接掌兵权后，马上改变廉颇的战略，军官也大批更换。秦将白起听到这个消息，非常高兴，用计截断赵军的运粮后路，围困赵军。过了四十几天，赵军粮草吃尽，赵括率领精锐部队企图突围，结果遭秦军乱箭射死，赵国四十万军士也都被秦军俘虏，并且被活埋。后来这个故事被浓缩成「纸上谈兵」，用来比喻不切实际的议论。"},
  {"name": "重于泰山，轻于鸿毛", "cid": 296891, "pid": 11702121, "num": 283, "meaning": "死有像泰山一样重，有像鸿毛一样轻。指人的死意义有大有小，价值不同。", "source": "司马迁《报任安书》", "example": "老师常说，为大家牺牲就重于泰山，为自己偷懒就轻于鸿毛。", "story": "西汉史学家司马迁因替李陵说话被处宫刑。他在《报任安书》中写道：人固有一死，或重于泰山，或轻于鸿毛。他为完成《史记》忍辱活下来。此语劝人死得有意义，活得知轻重。"},
  {"name": "专心致志", "cid": 296891, "pid": 11702122, "num": 284, "meaning": "专一心思，集中精神。语出《孟子．告子上》。_x000D_\n△「一暴十寒」、「专心一意」、「专精一思」", "source": "《孟子．告子上》", "example": "他正专心致志地准备联考，你别打扰他。", "story": "孟子是战国时代的大思想家，后人尊称他为「亚圣」。当时人们对于齐王管理政事没什么成就，而孟子不加辅佐的事很不满意，但孟子说：「不要怪那齐王不够聪明啊！就算天下最容易生长的生物，如果让它在太阳下曝晒一天，又放在寒冷的地方十天，也没有办法存活。我跟齐王相处的时间有限，一旦我离开，那些奸臣小人又来动摇大王的决心，我就算能让大王萌生一些向善的念头，又有什么用呢？就拿下围棋的技能来说，这本来是个小技术，但是假使不能专心学习，就得不到它的精妙。弈秋，是全国闻名的棋手，让他同时教二个人下围棋，一个专心一志，集中精神的听从老师的教导；另一个却心不在焉，老想著会不会有大鸟飞来，要如何拉弓射鸟等等。虽然二个人同时学围棋，但效果一定是不同的。是他的聪明才智不如人吗？不是，只因他没有专心学习罢了！」后来原文中的「专心致志」成为一句成语，用来指专一心思，集中精神。"},
  {"name": "惴惴不安", "cid": 296891, "pid": 11702123, "num": 285, "meaning": "形容因恐惧担忧而心神不安宁。◎语本《诗经．秦风．黄鸟》。", "source": "《诗经．秦风．黄鸟》\n《诗经．小雅．小宛》", "example": "因为是第一次出国，自己内心难免有点惴惴不安。", "story": "《诗经》是最早的一部诗歌总集，大抵收录周初至春秋中叶的作品，反映了当时的社会生活、人民思想和情感。〈黄鸟〉是一首挽歌。根据史书记载，秦穆公死时，共有一百七十七人陪葬，其中包括子车氏的奄息、仲行、针虎三位贤良大臣。人民哀怜他们的命运，作〈黄鸟〉一诗以悼之，其内容反映了人民对统治者无理要求的憎恨与无奈，并传达出对受害者的无限同情。其中一段说道：黄雀交交地悲鸣，栖息在酸枣树上。是谁要跟著穆公去殉葬呢？是子车奄息啊！才德出众的奄息，走到将活埋自己的墓穴之前，禁不住恐惧而全身战栗。苍天啊苍天，为什么要杀害这样的好人啊？若能救赎他的性命，我愿代他死百回。其中「惴惴」是形容恐惧的样子。典源又见《诗经．小雅．小宛》，此诗内容是在讽刺周幽王的无才无德，并劝诫自己兄弟在乱世中要潜迹以避祸。其中「惴惴小心，如临于谷」则是表述在深谷之前，谨慎恐惧的样子。后来「惴惴不安」这句成语就从这里演变而出，用来形容因恐惧担忧而心神不安宁。"},
  {"name": "捉襟见肘", "cid": 296891, "pid": 11702124, "num": 286, "meaning": "「捉襟见肘」之「襟」，典源作「衿」。「衿」同「襟」。见，音ㄒㄧㄢˋ，露出。「捉襟见肘」形容人衣衫破败，才抓住衣襟蔽胸，又露出了手肘。＃语本《庄子．让王》。后用「捉襟见肘」比喻短缺不足、穷于应付的窘态。_x000D_\n△「纳屦踵决」、「踵决肘见」、「顾此失彼」", "source": "＃《庄子．让王》*1*", "example": "这个游民衣衫褴褛，捉襟见肘，在寒天中发抖著行进。", "story": "「捉襟见肘」的意思是说人所穿的衣服完全破烂，才抓住衣襟免于露胸，又露出了手肘。《庄子．让王》篇载：曾子在卫国的时候，十年都没有添制新衣，要把帽子戴正，帽带就断了；抓住衣襟，手肘又露了出来；穿上鞋子，脚后跟又钻了出来；生活过得非常艰苦。后来「捉襟见肘」这句成语就从这里演变而出，形容衣衫破败，生活困窘，如《二十年目睹之怪现状》第三四回：「摊上坐了一人，生得眉清目秀，年纪约有四十上下，穿了一件捉襟见肘的夏布长衫。」《韩诗外传》卷一则提到孔子的学生原宪过著贫苦的生活，「振襟则肘见」，但却自得其乐，沉浸在求学、求道的快乐中。其中「振襟肘见」一语，跟「捉襟见肘」略有不同，「振襟」是整理衣襟的意思。现今则常用「捉襟见肘」比喻困乏不足、穷于应付的窘态。"}
];
